TELEGRAM_API = f"https://api.telegram.org/bot{BOT_TOKEN}" if BOT_TOKEN else None


def notify_admin(text: str):
    """
    Message the admin chat. Returns the sent message id, which is what lets an
    admin reply "approve" to a specific alert and have it act on the right one.
    """
    if not TELEGRAM_API or not ADMIN_CHAT_ID:
        return None
    try:
        r = requests.post(f"{TELEGRAM_API}/sendMessage",
                          json={"chat_id": int(ADMIN_CHAT_ID), "text": text}, timeout=10)
        return (r.json().get("result") or {}).get("message_id")
    except Exception:
        return None


def notify_admin_action(text: str, action: str, ref_id) -> None:
    """
    An admin alert that can be acted on by replying to it. The sent message id
    is remembered against the action, so a one word reply lands on the right
    member or screenshot every time, even with ten alerts in a row.
    """
    mid = notify_admin(text + "\n\nOr just reply yes to this message and I'll do it.")
    if not (mid and ref_id):
        return
    conn = get_db()
    if not conn:
        return
    try:
        with conn, conn.cursor() as cur:
            cur.execute("""INSERT INTO tg_actions (message_id, action, ref_id)
                           VALUES (%s,%s,%s) ON CONFLICT (message_id) DO NOTHING""",
                        (mid, action, ref_id))
    except Exception:
        pass
    finally:
        conn.close()


def take_tg_action(message_id):
    """The action a given admin alert carries, if any. Left in place until done."""
    if not message_id:
        return None
    conn = get_db()
    if not conn:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT action, ref_id FROM tg_actions WHERE message_id=%s", (message_id,))
            row = cur.fetchone()
            return (row[0], row[1]) if row else None
    except Exception:
        return None
    finally:
        conn.close()


def clear_tg_action(message_id):
    conn = get_db()
    if not conn:
        return
    try:
        with conn, conn.cursor() as cur:
            cur.execute("DELETE FROM tg_actions WHERE message_id=%s", (message_id,))
    except Exception:
        pass
    finally:
        conn.close()


def is_admin_chat(chat_id):
    """Only the configured admin chat can approve anything from Telegram."""
    if not ADMIN_CHAT_ID or chat_id is None:
        return False
    try:
        return int(chat_id) == int(ADMIN_CHAT_ID)
    except (TypeError, ValueError):
        return False


def forward_photo_to_admin(from_chat_id, message_id, caption: str = "") -> bool:
    """Copy a photo the user sent into the admin chat so it can actually be reviewed."""
    if not TELEGRAM_API or not ADMIN_CHAT_ID:
        return False
    try:
        r = requests.post(
            f"{TELEGRAM_API}/copyMessage",
            json={
                "chat_id": int(ADMIN_CHAT_ID),
                "from_chat_id": from_chat_id,
                "message_id": message_id,
                "caption": caption[:1000] if caption else None,
            },
            timeout=10,
        )
        return r.status_code == 200
    except Exception:
        return False


def send_telegram_message(chat_id, text: str) -> bool:
    if not TELEGRAM_API or not chat_id:
        return False
    try:
        r = requests.post(f"{TELEGRAM_API}/sendMessage", json={"chat_id": int(chat_id), "text": text}, timeout=10)
        return r.status_code == 200
    except Exception:
        return False


