def members_by_name(needle, limit=6):
    """Find members by part of their name, for admin commands in the bot."""
    needle = (needle or "").strip()
    if len(needle) < 2:
        return []
    conn = get_db()
    if not conn:
        return []
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("""SELECT * FROM members
                           WHERE merged_into IS NULL
                             AND LOWER(COALESCE(name,'')) LIKE %s
                           ORDER BY created_at DESC LIMIT %s""",
                        (f"%{needle.lower()}%", limit))
            return [dict(r) for r in cur.fetchall() or []]
    except Exception:
        return []
    finally:
        conn.close()


def connect_token(member_id):
    """A short signed token for a one tap connect link, so it cannot be guessed
    or passed around to claim someone else's account."""
    raw = f"{member_id}:{app.secret_key}".encode()
    return f"{member_id}-" + hashlib.sha256(raw).hexdigest()[:10]


def member_id_from_token(token):
    try:
        mid = int(str(token).split("-")[0])
    except Exception:
        return None
    return mid if connect_token(mid) == token else None


def find_chat_for_member(member):
    """
    Find this person's own Telegram chat WITHOUT needing a verification code.

    The bot asks everyone for their phone number, and stores it against their
    chat on their screenshots. So if they have ever spoken to the bot from that
    number, we can connect them off the phone number alone, which is what the
    form matches on too. Never returns the admin chat.
    """
    if not member:
        return None
    norm = (member.get("phone_normalized")
            or normalize_phone(member.get("phone") or "")) or ""
    if not norm:
        return None
    conn = get_db()
    if not conn:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute("""SELECT chat_id, username FROM photo_submissions
                           WHERE phone=%s AND chat_id IS NOT NULL
                           ORDER BY created_at DESC LIMIT 5""", (norm,))
            for chat_id, username in cur.fetchall() or []:
                if chat_id and not is_admin_chat(chat_id):
                    return {"chat_id": chat_id, "username": username or ""}
    except Exception:
        return None
    finally:
        conn.close()
    return None


def connect_member_chat(member_id, chat_id, username="", why="matched on phone number"):
    """Tie a member to their own Telegram, then send anything they are owed."""
    if not chat_id or is_admin_chat(chat_id):
        return False
    conn = get_db()
    if conn:
        try:
            with conn, conn.cursor() as cur:
                cur.execute("""UPDATE members SET chat_id=%s,
                               telegram_username=COALESCE(NULLIF(telegram_username,''), %s),
                               updated_at=NOW() WHERE id=%s""",
                            (chat_id, (username or "").lstrip("@"), member_id))
        finally:
            conn.close()
    audit(member_id, "Telegram connected", why)
    # Send them everything now. Not just what was queued: someone approved long
    # before this chat existed is owed nothing on paper, but has still never
    # received their code or their links.
    try:
        if not flush_owed(member_id):
            _m = get_member_by_id(member_id)
            _have = get_member_sections(member_id)
            if _m and _m.get("status") == "approved" and _have:
                deliver_sections(member_id, set(_have), note="sent when their Telegram connected")
    except Exception:
        pass
    return True


def flush_owed(member_id):
    """
    Anything this person was approved for while we had no way to message them.
    Called the moment their Telegram links, so they get their code and links
    without anyone remembering to do it by hand.
    """
    owed = [x for x in (_meta_get(f"owed:{member_id}") or "").split(",") if x]
    if not owed:
        return False
    _meta_set(f"owed:{member_id}", "")
    try:
        deliver_sections(member_id, set(owed), note="held until your Telegram was connected")
        return True
    except Exception:
        return False


def member_for_chat(chat_id, username=None):
    """
    Which account does this Telegram chat belong to? Chat ID is the strongest
    link because it survives someone changing their @username, and plenty of
    people have no username at all.

    The admin chat is never a member. If it were, a reply of "yes" would be
    read as a member answering a question, and anything meant for a member
    would come to admin instead of to them.
    """
    if not chat_id:
        return None
    if is_admin_chat(chat_id):
        return None
    conn = get_db()
    if not conn:
        return None
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("""SELECT * FROM members WHERE chat_id=%s AND merged_into IS NULL
                           ORDER BY created_at ASC LIMIT 1""", (chat_id,))
            row = cur.fetchone()
            if row:
                return row
            handle = (username or "").lstrip("@").lower()
            if handle:
                cur.execute("""SELECT * FROM members
                               WHERE LOWER(REPLACE(COALESCE(telegram_username,''),'@','')) = %s
                                 AND merged_into IS NULL
                               ORDER BY created_at ASC LIMIT 1""", (handle,))
                row = cur.fetchone()
                if row:
                    # Remember the chat so next time we match without the handle.
                    cur.execute("UPDATE members SET chat_id=%s WHERE id=%s", (chat_id, row["id"]))
                    return row
    except Exception:
        return None
    finally:
        conn.close()
    return None


def add_photo_file_id(chat_id, kind, file_id):
    """
    Keep the Telegram file id for each screenshot so the admin page can show
    the images itself, rather than sending you back to Telegram to look.
    """
    if not file_id:
        return
    conn = get_db()
    if not conn:
        return
    try:
        with conn, conn.cursor() as cur:
            cur.execute("""SELECT id, file_ids FROM photo_submissions
                           WHERE chat_id=%s AND kind=%s AND status='pending'
                           ORDER BY id DESC LIMIT 1""", (chat_id, kind))
            row = cur.fetchone()
            if not row:
                return
            existing = [f for f in (row[1] or "").split(",") if f]
            if file_id in existing:
                return
            existing.append(file_id)
            cur.execute("UPDATE photo_submissions SET file_ids=%s WHERE id=%s",
                        (",".join(existing[-4:]), row[0]))
    except Exception:
        pass
    finally:
        conn.close()


