def get_events(include_archived=False, space=None):
    """Events for one space, or all of them for the admin list."""
    conn = get_db()
    if not conn:
        return []
    try:
        with conn.cursor() as cur:
            wheres = [] if include_archived else ["archived = FALSE"]
            args = []
            if space:
                wheres.append("COALESCE(space,'her') = %s")
                args.append(space)
            clause = ("WHERE " + " AND ".join(wheres)) if wheres else ""
            cur.execute(f"""SELECT id, title, body, when_text, place, image_url, archived,
                                   COALESCE(space,'her')
                            FROM events {clause} ORDER BY id DESC""", tuple(args))
            cols = ("id", "title", "body", "when_text", "place", "image_url", "archived", "space")
            return [dict(zip(cols, r)) for r in cur.fetchall()]
    except Exception:
        return []
    finally:
        conn.close()


