def journal_written_days(member_id, limit=400):
    conn = get_db()
    if not conn:
        return set()
    try:
        with conn.cursor() as cur:
            cur.execute("""SELECT day FROM journal
                           WHERE member_id=%s AND body IS NOT NULL AND body <> ''
                           ORDER BY day DESC LIMIT %s""", (member_id, limit))
            out = set()
            for (d,) in cur.fetchall():
                out.add(d if isinstance(d, str) else d.isoformat())
            return out
    except Exception:
        return set()
    finally:
        conn.close()


def journal_streak(member_id):
    """(current_streak, best_streak, total_pages). A streak counts consecutive
    days written, still alive if today hasn't been written yet."""
    written = journal_written_days(member_id) if member_id else set()
    if not written:
        return 0, 0, 0
    days = sorted(date.fromisoformat(d) if isinstance(d, str) else d for d in written)
    total = len(days)
    best = run = 1
    for a, b in zip(days, days[1:]):
        run = run + 1 if (b - a).days == 1 else 1
        best = max(best, run)
    today = date.today()
    last = days[-1]
    if last in (today, today - timedelta(days=1)):
        current = 1
        i = len(days) - 1
        while i > 0 and (days[i] - days[i-1]).days == 1:
            current += 1
            i -= 1
    else:
        current = 0
    return current, best, total


