HOUSE_NAMES = ("charlotte", "inner circle", "innercircle", "inner circle trading")


def is_house_answer(referred_by):
    """Did they say the house rather than a partner? "Inner Circle", "Charlotte"
    and blank all mean the same thing: this one is Charlotte's own."""
    t = (referred_by or "").strip().lower()
    return (not t) or any(h in t for h in HOUSE_NAMES)


def belongs_to_house(m, marketers):
    """Charlotte's own client: no partner matched, or the answer named the
    house. A partner record called Charlotte never steals her own clients."""
    mk = marketer_match(m.get("referred_by"), marketers)
    if mk is None:
        return True
    return (mk.get("name") or "").strip().lower() in HOUSE_NAMES


HOUSE_WORDS = ("inner circle", "innercircle", "inner-circle", "the inner circle",
               "charlotte", "charlote", "charolette", "charlott", "char ",
               "admin", "the admin", "the team", "head office", "the owner",
               "the page", "the website", "the site", "found you myself", "no one",
               "nobody", "myself")


def is_house(text):
    """Answers that mean us rather than a partner: Inner Circle, admin, or
    Charlotte, however it's typed. All three are the same person, and none of
    them should ever pay a partner."""
    t = (text or "").strip().lower()
    if not t:
        return True
    return any(w in t for w in HOUSE_WORDS)


def open_claims():
    """Partners telling us someone is theirs, waiting to be matched up."""
    conn = get_db()
    if not conn:
        return []
    try:
        with conn.cursor() as cur:
            cur.execute("""SELECT id, marketer_id, name, phone, phone_normalized, deposit, member_id
                           FROM partner_claims WHERE status='open'
                           ORDER BY created_at DESC LIMIT 200""")
            return [dict(zip(("id", "marketer_id", "name", "phone", "phone_normalized",
                              "deposit", "member_id"), r)) for r in cur.fetchall()]
    except Exception:
        return []
    finally:
        conn.close()


def claims_for_member(m, claims, marketers):
    """
    Which partners have said this person is theirs. Usually one. If two
    partners onboard someone with the same name on the same day, both show
    and nothing is assumed: you choose.
    """
    norm = (m.get("phone_normalized") or normalize_phone(m.get("phone") or "")) or ""
    name = (m.get("name") or "").strip().lower()
    out, seen = [], set()
    for c in claims:
        matched = False
        if c.get("member_id") and c["member_id"] == m["id"]:
            matched = True
        elif norm and c.get("phone_normalized") and c["phone_normalized"] == norm:
            matched = True
        elif name and (c.get("name") or "").strip().lower() == name:
            matched = True
        if not matched:
            continue
        mk = next((k for k in marketers if k["id"] == c["marketer_id"]), None)
        if mk and mk["id"] not in seen:
            seen.add(mk["id"])
            out.append((c, mk))
    return out


def claim_for_member(m, claims, marketers):
    """The single claim on this person, or nothing if there are none or if two
    partners are claiming and it needs your eyes."""
    hits = claims_for_member(m, claims, marketers)
    return hits[0] if len(hits) == 1 else (None, None)


def awaiting_assignment(members, marketers):
    """
    Anyone onboarded without naming a partner sits in holding until you decide
    who they belong to. Better a short queue you check than a silent guess.
    """
    out = []
    for m in members:
        if m.get("attribution_set"):
            continue
        if marketer_match(m.get("referred_by"), marketers):
            continue          # they named a partner, nothing to decide
        if not member_qualified(m) and not (m.get("account_number") or "").strip():
            continue          # not far enough along to matter yet
        out.append(m)
    return out


def marketer_match(referred_by, marketers):
    """Which marketer a member's referrer answer points at, or None for us.
    Matches on the marketer's name or any alias, case-insensitive, anywhere in
    the answer, so "found you through Lucy's story" lands on Lucy. Anything
    meaning the house, Inner Circle, admin or Charlotte, never matches a
    partner."""
    text = (referred_by or "").strip().lower()
    if not text:
        return None
    if is_house(text):
        # unless a partner's actual name is also in there, which wins
        for mk in marketers:
            names = [mk["name"]] + [a.strip() for a in (mk.get("aliases") or "").split(",") if a.strip()]
            for n in names:
                if n and n.lower() in text and not is_house(n):
                    return mk
        return None
    for mk in marketers:
        names = [mk["name"]] + [a.strip() for a in (mk.get("aliases") or "").split(",") if a.strip()]
        for n in names:
            if n and n.lower() in text:
                return mk
    return None


def members_created_in_month(month):
    """All non-merged members whose record began in the given YYYY-MM month."""
    conn = get_db()
    if not conn:
        return []
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("""SELECT * FROM members
                           WHERE merged_into IS NULL
                             AND COALESCE(NULLIF(kudo_month, ''), to_char(created_at, 'YYYY-MM')) = %s
                           ORDER BY created_at DESC""", (month,))
            return cur.fetchall()
    except Exception:
        return []
    finally:
        conn.close()


def member_qualified(m):
    """Qualified means onboarded and genuinely started: approved with an
    account, £300 in and 10 trades done. The report is believed when it
    speaks: someone showing no deposit, or clearly under 10 trades, isn't
    qualified however registered they are. Where the report is silent on a
    number, nobody is failed on missing data."""
    if not (m.get("status") == "approved"
            and bool(str(m.get("account_number") or "").strip())):
        return False
    if m.get("kudo_report_at"):
        try:
            if m.get("kudo_deposit") is not None and float(m["kudo_deposit"]) <= 0:
                return False
        except Exception:
            pass
        try:
            if m.get("kudo_trades") is not None and int(m["kudo_trades"]) < 10:
                return False
        except Exception:
            pass
    return True


def member_unfunded(m):
    """Registered with Kudo but never deposited: the report shows them at zero."""
    try:
        return bool(m.get("kudo_report_at")) and m.get("kudo_deposit") is not None \
            and float(m["kudo_deposit"]) <= 0
    except Exception:
        return False


def member_roi(m):
    """The client's ROI from the latest Kudo report, or None before any report."""
    v = m.get("kudo_roi")
    try:
        return float(v) if v is not None else None
    except Exception:
        return None


def roi_holding(m):
    """Whether they're at or above the 1.5 bar. None means no report yet."""
    r = member_roi(m)
    return None if r is None else (r >= 1.5)


def member_payable(m):
    """What actually releases money at month close: onboarded, ROI holding,
    and the month-close check ticked by you against the report."""
    return member_qualified(m) and roi_holding(m) is True and bool(m.get("q_roi"))


