def esc(value):
    """Escape anything a member typed before it goes into a page."""
    return html.escape(str(value if value is not None else ""), quote=True)


def fmt_date(value):
    try:
        return value.strftime("%d %b %Y")
    except Exception:
        return ""


def fmt_datetime(value):
    try:
        return value.strftime("%d %b %Y, %H:%M")
    except Exception:
        return ""


def flash_banner():
    """Feedback after a redirect, passed through the query string."""
    ok = request.args.get("ok", "")
    err = request.args.get("err", "")
    if err:
        return f'<div class="adm-flash warn">{esc(err)}</div>'
    if ok:
        return f'<div class="adm-flash">{esc(ok)}</div>'
    return ""


def member_card(m, sections, view=""):
    """
    One row in the admin lists. Shows who they are, what they've submitted and
    what they're waiting on, with an approve button right here so nothing needs
    opening first.
    """
    status = m.get("status") or "pending"
    cls = "is-approved" if status == "approved" else "is-pending"

    pills = "".join(f'<span class="pill on">{SECTION_LABELS[s]}</span>'
                    for s in SECTION_KEYS if s in sections)
    if not pills:
        pills = '<span class="pill">no access yet</span>'

    waiting = requested_sections(m, sections)
    if waiting:
        pills += "".join(f'<span class="pill gold">wants {SECTION_LABELS[s]}</span>'
                         for s in SECTION_KEYS if s in waiting)

    tg = (m.get("telegram_username") or "").lstrip("@")
    bits = [(m.get("tier") or "").title()]
    if m.get("account_number"):
        bits.append(f"Gold acct {esc(m['account_number'])}")
    if m.get("currency_account_number"):
        bits.append(f"PU Prime acct {esc(m['currency_account_number'])}")
    if m.get("deposit_amount"):
        bits.append(f"£{esc(m['deposit_amount'])}")
    if "advanced" in (sections or set()) or m.get("paid"):
        bits.append("Advanced: paid")
    elif "advanced" in requested_sections(m, sections or set()):
        bits.append("Advanced: asked, payment to check")
    else:
        bits.append("Advanced: no")
    bits.append(f"@{esc(tg)}" if tg else "no Telegram")
    bits.append("chat linked" if m.get("chat_id") else "no chat linked")
    bits.append(f"joined {fmt_date(m.get('created_at'))}")
    meta = " · ".join(filter(None, bits))

    # Who this person counts to, and a one-tap way to change it if it's wrong.
    assign_bit = ""
    if status != "declined":
        _mks = get_marketers()
        _hit = marketer_match(m.get("referred_by"), _mks)
        _now = _hit["name"] if _hit else "Inner Circle (you)"
        _opts = ('<option value="">Inner Circle (you)</option>'
                 + "".join(f'<option value="{k["id"]}"'
                           + (" selected" if _hit and k["id"] == _hit["id"] else "")
                           + f'>{esc(k["name"])}</option>' for k in _mks))
        assign_bit = (
            f'<form method="POST" action="/admin/member/{m["id"]}/assign" '
            f'style="display:flex; gap:8px; flex-wrap:wrap; align-items:center; margin-top:8px; '
            f'font-size:12.5px; color:var(--ink-dim);">'
            f'<span>Counted to <strong style="color:var(--gold-bright);">{esc(_now)}</strong>'
            + (" &middot; confirmed" if m.get("attribution_set") else " &middot; not confirmed yet")
            + '</span>'
            f'<select name="to" style="width:auto; padding:5px 9px; font-size:12px;">{_opts}'
            f'<option value="hold">Put back in the holding list</option></select>'
            f'<button class="btn btn-ghost btn-sm" style="padding:4px 10px; font-size:11px;">'
            f'Change</button></form>')

    referral_bit = ""
    if status != "declined" and not (m.get("referred_by") or "").strip() and m.get("chat_id"):
        referral_bit = (
            f'<form method="POST" action="/admin/member/{m["id"]}/ask-referral" '
            f'style="margin-top:8px;"><button class="btn btn-ghost btn-sm" '
            f'style="padding:5px 10px; font-size:11px;">Ask them who referred them</button>'
            f'<span style="color:var(--ink-dim); font-size:11.5px; margin-left:8px;">'
            f'No name on their form. This asks on Telegram before you approve.</span></form>')

    partner_bit = ""
    if status == "approved":
        already = next((k for k in get_marketers() if k.get("member_id") == m["id"]), None)
        if already:
            partner_bit = (f'<div style="font-size:12.5px; margin-top:8px; color:var(--ink-dim);">'
                           f'&#129309; Partner: <a href="/admin/marketers/{already["id"]}" '
                           f'class="inline-link">{esc(already["name"])}</a></div>')
        else:
            partner_bit = (
                f'<details style="margin-top:8px;"><summary style="cursor:pointer; '
                f'color:var(--ink-dim); font-size:12.5px;">Make them a partner</summary>'
                f'<form method="POST" action="/admin/member/{m["id"]}/make-partner" '
                f'style="display:flex; gap:8px; flex-wrap:wrap; align-items:center; margin-top:8px;">'
                f'<input name="password" placeholder="Hub password (blank makes one)" '
                f'style="width:190px; padding:6px 10px; font-size:12px;">'
                f'<input name="rate" placeholder="$ per client" '
                f'style="width:110px; padding:6px 10px; font-size:12px;">'
                f'<label style="display:flex; gap:5px; align-items:center; font-size:12px;">'
                f'<input type="checkbox" name="is_kudo" value="1" checked style="width:auto;">Kudo</label>'
                f'<label style="display:flex; gap:5px; align-items:center; font-size:12px;">'
                f'<input type="checkbox" name="is_pu" value="1" style="width:auto;">PU Prime</label>'
                f'<button class="btn btn-ghost btn-sm" style="padding:5px 10px; font-size:11px;">'
                f'Set up partner</button></form>'
                f'<p style="color:var(--ink-dim); font-size:11.5px; margin:6px 0 0;">Creates their '
                f'partner hub and links it to this member account, so one login opens both.</p>'
                f'</details>')

    unlinked_note = ""
    if status == "approved" and not m.get("chat_id") and (m.get("access_code") or "").strip():
        unlinked_note = (
            f'<div style="border:1px solid rgba(196,112,127,.5); border-radius:9px; '
            f'padding:10px 14px; margin-top:10px; font-size:13px; color:var(--ink-dim);">'
            f'&#128244; Approved but no Telegram linked, so nothing could reach them there. '
            f'Their code: <strong style="color:var(--gold-bright); font-family:\'IBM Plex Mono\', '
            f'monospace;">{esc(m["access_code"])}</strong>. Text it to them, and tell them to '
            f'message our bot the word <strong>links</strong> so everything connects.</div>')

    if waiting:
        labels = ", ".join(SECTION_LABELS[s] for s in SECTION_KEYS if s in waiting)
        already = (status == "approved") or bool(sections)
        if already:
            decline = (
                f'<form method="POST" action="/admin/member/{m["id"]}/decline" style="margin-top:8px;">'
                f'<input type="hidden" name="back" value="/admin?view={view}">'
                f'<textarea name="note" rows="2" placeholder="Tell them why, this is sent to them with the decline" '
                f'style="width:100%; background:var(--bg); border:1px solid var(--line); color:var(--ink); '
                f'padding:10px 12px; border-radius:9px; font-size:13.5px; font-family:inherit; '
                f'resize:vertical; margin-bottom:8px;"></textarea>'
                f'<button type="submit" class="btn btn-ghost btn-sm">Decline request &amp; send message</button>'
                f'</form>')
        else:
            decline = (
                f'<form method="POST" action="/admin/member/{m["id"]}/decline" style="margin-top:8px;">'
                f'<input type="hidden" name="back" value="/admin?view={view}">'
                f'<textarea name="note" rows="2" placeholder="Optional: add your own words, sent to them via the bot with the standard message" '
                f'style="width:100%; background:var(--bg); border:1px solid var(--line); color:var(--ink); '
                f'padding:10px 12px; border-radius:9px; font-size:13.5px; font-family:inherit; '
                f'resize:vertical; margin-bottom:8px;"></textarea>'
                f'<button type="submit" class="btn btn-ghost btn-sm">Decline, ask to check details &amp; resubmit</button>'
                f'</form>')
        approve = (
            f'<form method="POST" action="/admin/member/{m["id"]}/approve" style="margin-top:12px;">'
            f'<input type="hidden" name="back" value="/admin?view={view}">'
            f'<button type="submit" class="btn btn-primary btn-sm">Approve {labels}</button>'
            f'</form>'
            + decline
        )
    else:
        approve = ""

    return (
        f'<div class="adm-card {cls}">'
        f'<a href="/admin/member/{m["id"]}" style="text-decoration:none; color:inherit; display:block;">'
        f'<div class="adm-card-top">'
        f'<span class="adm-card-name">{esc(m.get("title") or "")} {esc(m.get("name") or "Unnamed member")}</span>'
        f'<span class="adm-phone">{esc(pretty_phone(m.get("phone")))}</span>'
        f'</div>'
        f'<div class="adm-meta">ID #{m["id"]} · {meta}</div>{unlinked_note}{assign_bit}'
        f'{referral_bit}{partner_bit}'   
        f'<div style="margin-top:6px;">{pills}</div>'
        f'</a>'
        f'{approve}'
        f'</div>'
    )


# Admin tabs: the daily work first, the occasional things after. The partner
# side lives behind the Partner hub door in the strip above, not in here.
ADMIN_NAV = [
    ("/admin", "Members", "members"),
    ("/admin/photos", "Screenshots", "photos"),
    ("/admin/inbox", "Inbox", "inbox"),
    ("/admin/analytics", "Analytics", "analytics"),
    ("/admin/hub", "Board", "boards"),
    ("/admin/submissions", "Feedback", "feedback"),
    ("/admin/results", "Results", "results"),
    ("/admin/videos", "Videos", "videos"),
    ("/admin/events", "Events", "events"),
    ("/admin/duplicates", "Duplicates", "duplicates"),
]


def admin_layout(title: str, content: str, active: str = "") -> str:
    """
    The back office. Deliberately not the member site: no public tabs, no
    marketing nav, no footer. Everything an admin needs is one click away and
    it always looks like a control panel, never like the shop front.
    """
    def cls(key):
        return "on" if key == active else ""

    links = "".join(f'<a href="{href}" class="{cls(key)}">{label}</a>'
                    for href, label, key in ADMIN_NAV)

    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>{esc(title)} · Inner Circle admin</title>
{FONT_LINK}
<style>{BASE_CSS}</style>
</head>
<style>
  /* The control panel, with the same depth as the rest of the site so it does
     not feel like a spreadsheet bolted on the side. */
  body {{
    background:
      radial-gradient(90% 60% at 50% -6%, rgba(214,172,60,.30), transparent 62%),
      radial-gradient(70% 55% at 100% 8%, rgba(196,112,127,.18), transparent 66%),
      radial-gradient(60% 50% at 0% 26%, rgba(120,92,180,.10), transparent 70%),
      linear-gradient(168deg,
        #3A2C14 0%, #2C2211 18%, #1E1810 42%, #14100B 68%, #0C0A08 88%, #070605 100%);
    background-attachment: fixed;
    background-repeat: no-repeat;
    background-size: cover;
  }}
  /* A warm band behind the header, the way the other sides open */
  .adm-top {{
    background: linear-gradient(180deg, rgba(58,44,20,.86), rgba(20,16,11,.72));
    backdrop-filter: blur(10px);
    border-bottom: 1px solid rgba(214,172,60,.22);
  }}
  .adm-nav {{
    background: rgba(20,16,11,.62);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid rgba(214,172,60,.14);
  }}
  .adm-nav a.on {{ color: #F0CE7A; border-bottom-color: #F0CE7A; }}
  .adm-card, .adm-panel, .form-panel {{
    background: rgba(30,24,16,.78);
    backdrop-filter: blur(6px);
    border-color: rgba(214,172,60,.16);
  }}
  .adm-card:hover {{ border-color: rgba(214,172,60,.30); }}
  h1, h2, h3 {{ color: #FBF4E6; }}
  .adm-hero {{
    padding: 30px 0 22px;
    background:
      radial-gradient(60% 140% at 12% 0%, rgba(214,172,60,.16), transparent 70%),
      linear-gradient(180deg, rgba(58,44,20,.42), transparent 100%);
    border-bottom: 1px solid rgba(214,172,60,.12);
    margin-bottom: 6px;
  }}
  .adm-hero-eyebrow {{
    font-family: 'IBM Plex Mono', monospace; font-size: 10.5px; letter-spacing: .18em;
    text-transform: uppercase; color: rgba(240,206,122,.75);
  }}
  .adm-hero-title {{
    font-family: 'Fraunces', Georgia, serif; font-size: 30px; margin: 6px 0 0;
    color: #FBF4E6; letter-spacing: -.01em;
  }}
  @media (max-width: 560px) {{
    .adm-hero {{ padding: 22px 0 16px; }}
    .adm-hero-title {{ font-size: 24px; }}
  }}
</style>
<body class="theme-admin">
<div class="adm-shell">
  <header class="adm-top">
    <div class="wrap">
      <a href="/admin" class="adm-brand">INNER&middot;CIRCLE <span>admin</span></a>
      <div class="adm-top-right">
        <a href="/" target="_blank" rel="noopener">View live site &#8599;</a>
      </div>
    </div>
  </header>
  <div class="admin-strip"><div class="wrap">
    <span class="view-switch">
      <a href="/admin/view/admin" class="on">Admin site</a>
      <a href="/admin/view/partner">Partner side</a>
      <a href="/admin/view/member">Main site</a>
    </span>
    <a href="/admin/logout">Log out of admin</a>
  </div></div>
  <nav class="adm-nav">
    <div class="wrap">{links}</div>
  </nav>
  <div class="adm-hero"><div class="wrap">
    <span class="adm-hero-eyebrow">Admin</span>
    <h1 class="adm-hero-title">{title}</h1>
  </div></div>
  <main>{content}</main>
</div>
</body>
</html>"""


def meta_pixel_html():
    """
    The Meta pixel, plus a click event for anyone heading to Telegram, since
    nothing inside Telegram can be measured and the click is the only signal
    we get. Returns nothing at all when no pixel id is set, so the site stays
    clean by default.
    """
    if not META_PIXEL_ID:
        return ""
    return """
<script>
  !function(f,b,e,v,n,t,s){if(f.fbq)return;n=f.fbq=function(){n.callMethod?
  n.callMethod.apply(n,arguments):n.queue.push(arguments)};if(!f._fbq)f._fbq=n;
  n.push=n;n.loaded=!0;n.version='2.0';n.queue=[];t=b.createElement(e);t.async=!0;
  t.src=v;s=b.getElementsByTagName(e)[0];s.parentNode.insertBefore(t,s)}(window,
  document,'script','https://connect.facebook.net/en_US/fbevents.js');
  fbq('init', '__PIXEL_ID__');
  fbq('track', 'PageView');
  document.addEventListener('click', function (e) {
    var a = e.target && e.target.closest ? e.target.closest('a') : null;
    if (!a || !a.href) return;
    if (a.href.indexOf('t.me/') !== -1 || a.href.indexOf('telegram.me/') !== -1) {
      try { fbq('trackCustom', 'TelegramClick', { page: location.pathname }); } catch (err) {}
    }
  }, true);
</script>
<noscript><img height="1" width="1" style="display:none"
  src="https://www.facebook.com/tr?id=__PIXEL_ID__&ev=PageView&noscript=1"></noscript>
""".replace("__PIXEL_ID__", META_PIXEL_ID)


def base_layout(title: str, content: str, active: str = "", theme: str = "") -> str:
    def nav_class(key):
        if key == active:
            return "active"
        # both course tabs sit under the older "education" key
        if active == "education" and key in ("fundamentals", "advanced"):
            return ""
        return ""

    try:
        logged_in = bool(session.get("member_id"))
    except Exception:
        logged_in = False

    try:
        has_community = has_access("her")
    except Exception:
        has_community = False

    community_label = "Female Wealth" if has_community else "Community"

    site_view = session.get("site_view", "admin") if session.get("admin") else ""
    if session.get("admin"):
        adm_on = ' class="on"' if site_view not in ("member", "partner") else ""
        par_on = ' class="on"' if site_view == "partner" else ""
        mem_on = ' class="on"' if site_view == "member" else ""
        admin_strip = ('<div class="admin-strip"><div class="wrap">'
                       '<span class="view-switch">'
                       f'<a href="/admin/view/admin"{adm_on}>Admin site</a>'
                       f'<a href="/admin/view/partner"{par_on}>Partner side</a>'
                       f'<a href="/admin/view/member"{mem_on}>Main site</a>'
                       '</span>'
                       '<a href="/admin/logout">Log out of admin</a>' 
                       '</div></div>')
    else:
        admin_strip = ""

    on_partner_page = request.path.startswith("/partners") or request.path == "/favourites"
    if not admin_strip and session.get("marketer_id"):
        try:
            _pk = next((k for k in get_marketers() if k["id"] == session["marketer_id"]), None)
        except Exception:
            _pk = None
        if _pk:
            _pboard_pill = unread_pill(hub_unread("partners", f"p{_pk['id']}"))
            _pmsg_pill = unread_pill(partner_unread_count(_pk["id"]))
            admin_strip = ('<div class="admin-strip"><div class="wrap">' 
                           '<a href="/partners" class="brand" style="font-family:\'Fraunces\', serif; '
                           'font-size:15px; letter-spacing:.06em; color:#F5F0E8; margin-right:6px;">'
                           'INNER<span style="color:var(--gold-bright);">·</span>CIRCLE '
                           '<span style="font-size:11px; letter-spacing:.14em; color:var(--gold-bright);">'
                           'PARTNERS</span></a>'
                           '<span class="view-switch">'
                           f'<span style="color:var(--ink-dim); margin-right:6px;">{esc(_pk["name"])}</span>' 
                           '<a href="/partners">Partner home</a>'
                           f'<a href="/partners/board">Board{_pboard_pill}</a>'
                           f'<a href="/partners/messages">Messages{_pmsg_pill}</a>'
                           '<a href="/partners/events">Events</a>'
                           '<a href="/partners/training">Onboarding</a>'
                           '<a href="/partners/hub">My hub</a>'
                           '<a href="/partners/courses">Courses</a>'
                           '<a href="/partners/claim">Claim</a>' 
                           '<a href="/partners/account">My account</a>'
                           '<a href="/">Main site</a>'  
                           '</span>'
                           '<a href="/partners/logout">Log out of partner hub</a>'
                           '</div></div>')

    if session.get("admin") and site_view == "partner":
        # the owner on her own partner side: partner doors, admin strip above
        nav_cta = '<a href="/partners" class="nav-cta">Partner home</a>'
        tabs = "".join(f'<a href="{href}" class="{nav_class(key)}">{label}</a>' for href, label, key in [
            ("/partners", "Partner home", "partners"),
            ("/partners/hub", "My hub", "partnershub"),
            ("/partners/training", "Onboarding", "partnertraining"),
            ("/partners/courses", "Courses", "partnercourses"),
            ("/partners/account", "My account", "partneraccount"),
            ("/admin/marketers", "Pay & partners", "adminmarketers"),
            ("/become-a-partner", "Recruit page", "recruitpage"),
        ])
    elif session.get("admin") and site_view != "member":
        # Admin sees the whole site plus the admin side of it, and stays admin
        # while moving between the two. Nothing here logs them out.
        nav_cta = '<a href="/admin" class="nav-cta">Admin</a>'
        tabs = "".join(f'<a href="{href}" class="{nav_class(key)}">{label}</a>' for href, label, key in [
            ("/admin", "Members", "adminhome"),
            ("/admin/photos", "Screenshots", "adminphotos"),
            ("/admin/inbox", "Inbox", "admininbox"),
            ("/admin/analytics", "Analytics", "adminanalytics"),
            ("/admin/hub", "Board", "adminhub"),
            ("/her/hub", "Female Wealth", "community"),
            ("/education/fundamentals", "Foundation", "fundamentals"),
            ("/education/advanced", "Advanced", "advanced"),
            ("/signals", "Signals", "signals"),
        ])
    elif logged_in or session.get("admin"):
        # Members, and admins previewing the members' site. Same bar the member
        # sees, and the strip above it is the way back to the admin side.
        nav_cta = '<a href="/account" class="nav-cta">My Account</a>'
        granted = current_sections()
        links = [("/account", "My Account", "account"),
                 ("/my-signals", "Your Signals", "signals")]
        if "fundamentals" in granted:
            links.append(("/education/fundamentals", "Foundation Course", "fundamentals"))
        if "advanced" in granted:
            links.append(("/education/advanced", "Advanced Course", "advanced"))
        else:
            links.append(("/education/advanced", "Unlock Advanced", "advanced"))
        if "signals_currency" not in granted:
            links.append(("/signals", "Extra Signals", "extra"))
        if "her" in granted:
            links.append(("/her", community_label, "community"))
        links.append(("/messages", "Messages", "messages"))
        # Partner doors live in the strip above, once, so they never appear
        # twice on the same screen.

        tabs = "".join(f'<a href="{href}" class="{nav_class(key)}">{label}</a>'
                       for href, label, key in links)
    else:
        nav_cta = '<a href="/unlock" class="nav-cta">Log In</a>'
        base_links = [
            ("/onboarding", "Onboarding", "onboarding"),
            ("/education/fundamentals", "Foundation Course", "fundamentals"),
            ("/education/advanced", "Advanced Course", "advanced"),
            ("/community", "Community", "community"),
            ("/signals", "Extra Signals", "signals"),
        ]
        # A logged-in partner reaches her hub from the strip above, not here.
        tabs = "".join(f'<a href="{href}" class="{nav_class(key)}">{label}</a>'
                       for href, label, key in base_links)

    on_partner_side = False
    try:
        on_partner_side = request.path.startswith("/partners")
    except Exception:
        pass
    if on_partner_side:
        # the partner strip already carries the brand, the doors and the log
        # out, so a second bar underneath is just noise
        topnav = ""
    else:
        topnav = f"""<nav class="topnav">
  <div class="wrap">
    <a href="/" class="brand">INNER<span class="dot">·</span>CIRCLE</a>
    <div class="navlinks">
      <a href="https://t.me/Innercircleverifybot" target="_blank" rel="noopener" style="color: var(--gold);">Support</a>
    </div>
    {nav_cta}
  </div>
</nav>"""

    # On the partner side the strip above is the only bar they need, so the
    # member tab bar stays out of the way.
    tabbar_html = ("" if (on_partner_page and session.get("marketer_id") and not session.get("admin"))
                   else f'<div class="tabbar"><div class="wrap">{tabs}</div></div>')

    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{title}, Inner Circle</title>
{FONT_LINK}
<style>{BASE_CSS}</style>
</head>
<body class="{theme}">
{topnav}
{admin_strip}
{tabbar_html}
{content}
<script>
  // Heading to Telegram is the nearest thing to a conversion, and nothing
  // inside Telegram can be measured, so the click is counted here.
  document.addEventListener('click', function (e) {{
    var a = e.target && e.target.closest ? e.target.closest('a') : null;
    if (!a || !a.href) return;
    if (a.href.indexOf('t.me/') === -1 && a.href.indexOf('telegram.me/') === -1) return;
    try {{
      var body = new FormData();
      body.append('page', location.pathname);
      navigator.sendBeacon('/event/telegram', body);
    }} catch (err) {{}}
  }}, true);
</script>
<a href="https://t.me/Innercircleverifybot?start=help" target="_blank" rel="noopener" class="support-float">💬 Need help?</a>
<div class="disclaimer-strip">
  Educational content only, not financial advice. Trading carries risk, past performance is never a guarantee of future results.
</div>
<footer>
  <div class="wrap">
    <span>© Inner Circle</span>
    <div class="foot-links">
      <a href="/onboarding">Onboarding</a>
      <a href="/education">Education</a>
      <a href="/community">Community</a>
      <a href="https://t.me/Innercircleverifybot" target="_blank" rel="noopener">Support</a>
    </div>
  </div>
</footer>
{meta_pixel_html()}
</body>
</html>"""


