def ocr_image_bytes(blob):
    """
    Read an image on the server, if this machine happens to have an OCR engine.
    Most don't, and that's fine: the browser reads photos, and the paste box is
    always there. Returns text, or None.
    """
    try:
        import pytesseract
        from PIL import Image as _Image
        import io as _io
        img = _Image.open(_io.BytesIO(blob))
        if img.width < 1400:
            img = img.resize((img.width * 2, img.height * 2))
        return pytesseract.image_to_string(img.convert("L"))
    except Exception:
        return None


def rows_from_text(text):
    """
    Rows from plain text: a copied report table, or what the browser read out
    of a screenshot. Tries the portal's block layout first, then tabs, then
    commas, then whitespace columns. Returns None if there is nothing usable.
    """
    if not text or not text.strip():
        return None
    lines = [l.rstrip() for l in text.replace("\r", "").split("\n") if l.strip()]
    if not lines:
        return None
    block = parse_kudo_block_export([[l] for l in lines])
    if block:
        return block
    # A Registrations Report read off a screen: let the report-aware parser have
    # it before any general purpose splitting, since money like $1,994.81 makes
    # a comma split produce nonsense.
    joined = " ".join(lines).lower()
    if any(w in joined for w in ("kudotrade", "first dep", "net dep", "registrations report")):
        screen = parse_kudo_screen_text(lines)
        if screen:
            return screen
    rows = []
    for l in lines:
        if "\t" in l:
            parts = [p.strip() for p in l.split("\t")]
        elif l.count(",") >= 2:
            parts = [p.strip() for p in l.split(",")]
        else:
            parts = [p for p in re.split(r"\s{2,}", l.strip()) if p]
        if len(parts) >= 2:
            rows.append(parts)
    if len(rows) < 2:
        # last resort: a screenshot read line by line, where each client's
        # numbers sit on their own lines. The block parser handles that shape
        # when there are account numbers and money to pair up.
        return parse_kudo_screen_text(lines)
    return rows


def parse_kudo_screen_text(lines):
    """
    A Registrations Report read off a screen or a photo. Read that way the
    table can come out in any order: sometimes column by column, sometimes in
    chunks, with the Total row tagging along.

    So rather than trusting the layout, this uses the report's own arithmetic.
    Money arrives in runs that each end with a total equal to the run before
    it, and that is what marks one column's worth of figures. The runs are then
    matched to the money headings in the order they appear (commission, first
    deposit, net deposit). Accounts and names are recognised by shape. ROI is
    worked out as net over first deposit.
    """
    money_re = re.compile(r"^\$?[\d,]+\.\d{2}$")
    acct_re = re.compile(r"^\d{5,8}$")
    name_re = re.compile(r"^[A-Za-z][A-Za-z'\-. ]{3,40}$")
    FURNITURE = ("items per page", "of 1 pages", "run report", "registration date",
                 "cellxpert", "hidden", "go.kudo", "user id")

    money, accts, names, heads = [], [], [], []
    per_line = []          # the money found on each line, to spot the layout
    for raw in lines:
        l = " ".join(str(raw).split())
        if not l:
            continue
        low = l.lower()
        for key, words in (("commission", ("commiss",)),
                           ("deposit", ("first dep",)),
                           ("balance", ("net dep",))):
            if any(w in low for w in words) and key not in heads:
                heads.append(key)
        if any(w in low for w in FURNITURE) or low in ("kudo", "kudo -r...", "dashboard"):
            continue
        toks = l.split()
        line_money = []
        for t in toks:
            t = t.strip("|")
            if money_re.match(t.replace("$", "")):
                v = float(t.replace("$", "").replace(",", ""))
                money.append(v)
                line_money.append(v)
            elif acct_re.match(t) and t not in accts:
                accts.append(t)
        if line_money:
            per_line.append(line_money)
        # a name line: the leftover words after any account number
        words_only = " ".join(w for w in toks if not any(ch.isdigit() for ch in w)).strip()
        BAD_WORDS = ("first", "net", "account", "total", "customer", "items", "page", "mon", "tue",
                     "wed", "thu", "fri", "sat", "sun", "jan", "feb", "mar", "apr", "jun", "jul",
                     "aug", "sep", "oct", "nov", "dec", "home", "female", "secure", "emily",
                     "report", "date", "dashboard", "promote", "update", "clicks")
        if accts and name_re.match(words_only) and len(words_only.split()) >= 2 \
                and not any(w in words_only.lower().split() for w in BAD_WORDS):
            names.append(words_only.rstrip("."))

    if not accts:
        return None
    n = len(accts)

    # split the money into columns, each ending with its own total
    # Two shapes turn up. Row by row, where a line holds several figures for one
    # client; or column by column, where each column's figures run down the
    # screen and end in a Total. Pick by what the lines actually look like.
    if per_line and max(len(v) for v in per_line) >= 2:
        wide = [v for v in per_line if len(v) >= 2]
        if len(wide) > 1:
            width = min(len(v) for v in wide)
            sums = [sum(row[i] for row in wide[:-1]) for i in range(width)]
            last = wide[-1]
            if all(abs(last[i] - sums[i]) < 0.05 for i in range(width)):
                wide = wide[:-1]      # that last line was the Total row
        keys = [h for h in (heads or []) if h in ("commission", "deposit", "balance")]
        if len(keys) < 2:
            keys = ["deposit", "balance"]
        cols = {}
        for j, key in enumerate(keys):
            vals = [row[j] if j < len(row) else None for row in wide]
            if any(v is not None for v in vals):
                cols[key] = vals

        def val_rm(key, i):
            vals = cols.get(key) or []
            return vals[i] if i < len(vals) else None

        out = [["account", "deposit", "trades", "roi", "balance", "commission", "name"]]
        for i, acct in enumerate(accts):
            d, b, cm = val_rm("deposit", i), val_rm("balance", i), val_rm("commission", i)
            roi = round(b / d, 2) if d and b is not None else None
            out.append([acct, "" if d is None else str(d), "",
                        "" if roi is None else str(roi),
                        "" if b is None else str(b),
                        "" if cm is None else str(cm),
                        names[i] if i < len(names) else ""])
        if len(out) > 1:
            return out

    runs, run, total = [], [], 0.0
    for v in money:
        if run and len(run) >= n and abs(v - total) < 0.02:
            runs.append(run[:n])      # v is this column's Total row
            run, total = [], 0.0
            continue
        run.append(v)
        total += v
        if len(run) > n:
            # no Total line for this column: take the first n and start over
            runs.append(run[:n])
            run, total = [v], v
    if run:
        runs.append(run[:n])
    runs = [r for r in runs if r]

    cols = {}
    for i, key in enumerate(heads or ["deposit", "balance"]):
        if i < len(runs):
            cols[key] = runs[i]
    if "deposit" not in cols and runs:
        cols["deposit"] = runs[0]
    if "balance" not in cols and len(runs) > 1:
        cols["balance"] = runs[1]

    def val(key, i):
        vals = cols.get(key) or []
        return vals[i] if i < len(vals) else None

    out = [["account", "deposit", "trades", "roi", "balance", "commission", "name"]]
    for i, acct in enumerate(accts):
        d, b, cm = val("deposit", i), val("balance", i), val("commission", i)
        roi = round(b / d, 2) if d and b is not None else None
        out.append([acct,
                    "" if d is None else str(d), "",
                    "" if roi is None else str(roi),
                    "" if b is None else str(b),
                    "" if cm is None else str(cm),
                    names[i] if i < len(names) else ""])
    return out if len(out) > 1 else None


def read_rows_from_upload(f):
    """Rows from an uploaded report, whether it's CSV or Excel (.xlsx).
    Excel files are zip archives of XML, so the standard library reads them
    fine. Returns a list of rows (lists of strings), or None if unreadable."""
    try:
        blob = f.read()
    except Exception:
        return None
    if not blob:
        return None
    # Excel: starts with the zip magic bytes
    if blob[:2] == b"PK":
        try:
            import zipfile as _zip, io as _io
            import xml.etree.ElementTree as _ET
            z = _zip.ZipFile(_io.BytesIO(blob))
            ns = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
            shared = []
            if "xl/sharedStrings.xml" in z.namelist():
                root = _ET.fromstring(z.read("xl/sharedStrings.xml"))
                for si in root.findall(f"{ns}si"):
                    shared.append("".join(t.text or "" for t in si.iter(f"{ns}t")))
            sheet = next((n for n in ("xl/worksheets/sheet1.xml",)
                          if n in z.namelist()),
                         next((n for n in sorted(z.namelist())
                               if n.startswith("xl/worksheets/") and n.endswith(".xml")), None))
            if not sheet:
                return None
            root = _ET.fromstring(z.read(sheet))
            rows = []
            for r in root.iter(f"{ns}row"):
                cells = {}
                for c in r.findall(f"{ns}c"):
                    ref = c.get("r") or ""
                    col = 0
                    for ch in ref:
                        if ch.isalpha():
                            col = col * 26 + (ord(ch.upper()) - 64)
                    col = max(col - 1, 0)
                    ctype = c.get("t")
                    if ctype == "s":
                        v = c.find(f"{ns}v")
                        idx = int(v.text) if v is not None and v.text else -1
                        cells[col] = shared[idx] if 0 <= idx < len(shared) else ""
                    elif ctype == "inlineStr":
                        cells[col] = "".join(t.text or "" for t in c.iter(f"{ns}t"))
                    else:
                        v = c.find(f"{ns}v")
                        cells[col] = v.text if v is not None and v.text else ""
                width = max(cells) + 1 if cells else 0
                rows.append([cells.get(i, "") for i in range(width)])
            return rows or None
        except Exception:
            return None
    # otherwise treat as CSV
    try:
        import csv as _csv, io as _io
        text = blob.decode("utf-8-sig", errors="replace")
        return list(_csv.reader(_io.StringIO(text))) or None
    except Exception:
        return None


def parse_kudo_block_export(rows):
    """
    The Kudo back office export isn't always a table. Copied or saved from the
    portal it arrives as a vertical block per client: kudotrade id, dates,
    country, a dollar deposit, status, trade count, lots, dollar balance, the
    account number, then the client's name. This reads those blocks. ROI isn't
    a column in that layout, so it's worked out the way the business means it:
    balance divided by deposit. Returns standard rows
    [account, deposit, trades, roi, name], or None if it doesn't look like
    that export.
    """
    lines = []
    for r in rows:
        for cell in r:
            s = str(cell).strip()
            if s:
                lines.append(s)
    if not any(s.lower().startswith("kudotrade-") for s in lines):
        return None
    blocks, block, started = [], [], False
    for s in lines:
        low = s.lower()
        if low.startswith("total") or low.startswith("items per page"):
            break
        if low.startswith("kudotrade-"):
            if started and block:
                blocks.append(block)
            block, started = [], True
            continue
        if started:
            block.append(s)
    if started and block:
        blocks.append(block)

    out = [["account", "deposit", "trades", "roi", "balance", "commission", "name"]]
    for b in blocks:
        money = [float(re.sub(r"[^\d.]", "", x)) for x in b if re.match(r"^\$[\d,]+(\.\d+)?$", x)]
        ints = [x for x in b if re.match(r"^\d+$", x)]
        acct = next((x for x in reversed(ints) if len(x) >= 5), None)
        trades = next((int(x) for x in ints if x != acct and int(x) < 100000), None)
        # The portal's money columns run: commission (what Kudo pays), then
        # first deposit, then net deposit. With only the deposit view copied
        # there are two: first deposit, then net deposit.
        commission = money[0] if len(money) >= 3 else None
        deposit = money[-2] if len(money) >= 2 else (money[0] if money else None)
        balance = money[-1] if money else None
        roi = round(balance / deposit, 2) if deposit and balance is not None else None
        name = next((x for x in reversed(b)
                     if not re.match(r"^[\d$./,\- ]+$", x) and x.lower() not in ("new", "active")), "")
        if acct:
            out.append([acct, "" if deposit is None else str(deposit),
                        "" if trades is None else str(trades),
                        "" if roi is None else str(roi),
                        "" if balance is None else str(balance),
                        "" if commission is None else str(commission), name])
    return out if len(out) > 1 else None


def reconciliation_html():
    """The two lists that keep the report and the site honest with each other:
    accounts in the last Kudo report that aren't on the site, and members on
    the site the report never mentioned."""
    raw = _meta_get("kudo_last_import")
    if not raw:
        return ""
    try:
        data = json.loads(raw)
    except Exception:
        return ""
    bits = ""
    missing = data.get("missing") or []
    absent = data.get("not_in_report") or []
    if missing:
        items = "".join(f'<div style="padding:8px 14px; border:1px solid var(--line); '
                        f'border-radius:8px; margin-bottom:6px; font-size:13.5px;">'
                        f'Account {esc(str(a))}, in the report but not on the site. A lead who '
                        f'never onboarded, or a typo in someone\'s account number.</div>'
                        for a in missing[:15])
        bits += (f'<h2 style="font-size:18px; margin:30px 0 10px;">In the report, not on the site '
                 f'({len(missing)})</h2>{items}')
    if absent:
        items = "".join(f'<div style="padding:8px 14px; border:1px solid var(--line); '
                        f'border-radius:8px; margin-bottom:6px; font-size:13.5px;">'
                        f'<a href="/admin/member/{x["id"]}" class="inline-link">{esc(x["name"] or "Unnamed")}</a>'
                        f' &middot; account {esc(str(x["acct"]))}, on the site but the report never '
                        f'mentioned them. Wrong account number, or they came through another link.</div>'
                        for x in absent[:15])
        bits += (f'<h2 style="font-size:18px; margin:30px 0 10px;">On the site, not in the report '
                 f'({len(absent)})</h2>{items}')
    if bits:
        when = (data.get("at") or "")[:16].replace("T", " ")
        bits = (f'<div style="margin-top:34px;"><span class="eyebrow">Last report: {esc(when)}</span>'
                + bits + '</div>')
    return bits


# Every table that holds member data, for the full reset. Content you built
# stays: events, her_videos, marketers, app settings.
RESET_TABLES = [
    "member_access", "photo_submissions", "verifications", "journal",
    "her_progress", "her_opened", "messages", "submissions", "tg_actions",
    "event_rsvps", "hub_replies", "hub_posts", "bot_state", "bot_contacts",
    "admin_audit", "members",
]


@app.route("/admin/danger/reset", methods=["POST"])
def admin_danger_reset():
    """
    The clean slate. Wipes every member and every trace of them: accounts,
    screenshots, codes, journals, progress, messages, board posts, bot memory
    and pending alerts, so a fresh test run starts from genuinely nothing.
    What you built stays: courses, videos, events, marketers, settings.
    Guarded twice: admin only, and the word RESET typed in full, because
    there is no undo.
    """
    if not session.get("admin"):
        return redirect(url_for("admin"))
    if (request.form.get("confirm") or "").strip() != "RESET":
        return redirect("/admin?err=" + quote("Not reset. Type RESET in the box to confirm, it has no undo."))

    conn = get_db()
    if not conn:
        return redirect("/admin?err=" + quote("No database connection, nothing was touched."))
    cleared = []
    try:
        with conn, conn.cursor() as cur:
            for t in RESET_TABLES:
                try:
                    cur.execute(f"DELETE FROM {t}")
                    cleared.append(t)
                except Exception:
                    pass
    finally:
        conn.close()
    return redirect("/admin?ok=" + quote(
        f"Clean slate. {len(cleared)} tables emptied: every member, screenshot, code, journal, "
        "message and board post is gone. Courses, videos, events and marketers untouched. "
        "Run your test from the very start."))


# Bonus, in POUNDS PER PERSON, and it rises as they grow instead of shrinking.
# One band only: 12 qualified is the £7 band on all 12, not £5 plus £7.
# Capped at £13 so your margin per client never drops below about £174.
# Flat lump per band, NOT per person. You hit one band, you get that amount,
# and it stops at 50. Worked as five pounds a head at the bottom of each band,
# so the cost per client falls the more someone brings.
BONUS_LADDER = [(50, 250), (40, 200), (30, 150), (20, 100), (10, 50), (5, 25)]


PU_INVITE_THRESHOLD = 20


def pu_invite_state(mk, marketers, members, month):
    """
    Two stages, never automatic.

    1. A partner passes 20 qualified clients in a month. You are told, once,
       and a decision appears on your Pay & partners page. She sees nothing.
    2. Only if you say yes does the invitation appear on her hub.

    That way a one off fluke month never invites anyone: you look at it first.
    """
    if is_pu_partner(mk):
        return None                      # already on that side
    mine = [m for m in members if marketer_match(m.get("referred_by"), [mk])]
    qualified = sum(1 for m in mine if member_qualified(m))
    decision = (_meta_get(f"puinvite:{mk['id']}") or "")

    if decision == "sent":
        return {"count": qualified, "show": True, "months": _invite_months(mk)}
    if decision == "no":
        return None                      # you said no, she never sees it

    if qualified >= PU_INVITE_THRESHOLD:
        months = _invite_months(mk, add=month)
        if f"told:{month}" not in decision:
            _meta_set(f"puinvite:{mk['id']}", f"told:{month}")
            notify_admin(
                f"\u2b50 WORTH A LOOK\n\n{mk['name']} has {qualified} qualified clients in "
                f"{month}, which is over the {PU_INVITE_THRESHOLD} mark."
                f"\n\nThis is month {months} she has done it."
                f"\n\nShe has NOT been told anything. Decide on your Pay & partners page: "
                f"{SITE}/admin/marketers")
    return None


def _invite_months(mk, add=None):
    """How many months this partner has passed the mark, so a single fluke is
    obvious from a run of good months."""
    key = f"puinvitemonths:{mk['id']}"
    months = [x for x in (_meta_get(key) or "").split(",") if x]
    if add and add not in months:
        months.append(add)
        _meta_set(key, ",".join(months[-24:]))
    return len(months)


def pu_invite_candidates(marketers, members, month):
    """Partners over the mark this month who you have not decided about yet."""
    out = []
    for k in marketers:
        if k.get("owner") or is_pu_partner(k):
            continue
        decision = (_meta_get(f"puinvite:{k['id']}") or "")
        if decision in ("sent", "no"):
            continue
        n = sum(1 for m in members
                if marketer_match(m.get("referred_by"), [k]) and member_qualified(m))
        if n >= PU_INVITE_THRESHOLD:
            out.append({"mk": k, "count": n, "months": _invite_months(k)})
    return out


def bonus_on_for(marketer_id):
    """Is the bonus structure switched on for this partner? On unless you turn
    it off, so nobody is quietly missed."""
    return (_meta_get(f"bonusoff:{marketer_id}") or "") != "1"


def bonus_band(count):
    """(the band you're in, total pounds) for this month's qualified count.
    One band only, never added together."""
    for floor, amount in BONUS_LADDER:
        if count >= floor:
            return floor, amount
    return 0, 0


def bonus_for(count):
    """Total bonus in pounds."""
    return bonus_band(count)[1]


def plain_gbp(amount):
    """Pounds on their own, for figures that are already in pounds."""
    try:
        return f"&pound;{float(amount):,.0f}"
    except Exception:
        return "&pound;0"


def gbp(amount):
    """Pounds first, dollars beside: bonuses are set and paid in pounds."""
    rate = get_usd_gbp_rate() or 0.75
    return f"&pound;{amount:,.2f} (${amount / rate:,.2f})" if rate else f"&pound;{amount:,.2f}"


