# Everything a partner needs on day one is open straight away. The rest, the
# deeper courses, arrive two a week, because fifty seven lessons on the first
# day is a wall nobody climbs.
COURSE_DRIP_PER_WEEK = int(os.environ.get("PARTNER_DRIP_PER_WEEK", "2"))
OPEN_FROM_DAY_ONE = ("Getting started", "Kudo", "PU Prime", "The mastermind")


def partner_started(mk):
    """The day this partner first logged in, so the drip is counted from their
    own start rather than from whenever the site went live."""
    if not mk:
        return date.today()
    key = f"partnerstart:{mk['id']}"
    raw = _meta_get(key)
    if raw:
        try:
            return date.fromisoformat(raw[:10])
        except Exception:
            pass
    _meta_set(key, date.today().isoformat())
    return date.today()


def lessons_for(mk, ignore_drip=False):
    """The lessons this partner should see: everything general, plus her own
    pay sides only. Returns [(global_index, section, title)]. Admin sees all."""
    if mk and mk.get("owner"):
        return [(i, s, t) for i, (s, _r, t, _b) in enumerate(MARKETER_TRAINING)]
    is_kudo = bool(mk.get("is_kudo")) if mk else True
    is_pu = is_pu_partner(mk) if mk else True
    out, dripped = [], []
    for i, (section, role, title, _body) in enumerate(MARKETER_TRAINING):
        if not (role == "all" or (role == "kudo" and is_kudo) or (role == "pu" and is_pu)):
            continue
        if section in OPEN_FROM_DAY_ONE:
            out.append((i, section, title))
        else:
            dripped.append((i, section, title))

    # Every course still shows in the menu. The pacing happens inside them, so
    # nobody loses sight of what they have coming.
    return out + dripped


def drip_locked(mk, global_index):
    """
    Is this lesson still to come? Everything in the day one sections is always
    open. The deeper courses arrive two a week from the day they joined, so
    there is always something new without a wall of it on the first day.
    """
    if not mk or mk.get("owner") or COURSE_DRIP_PER_WEEK <= 0:
        return False
    try:
        section = MARKETER_TRAINING[global_index][0]
    except Exception:
        return False
    if section in OPEN_FROM_DAY_ONE:
        return False
    order = [i for i, (s, _r, _t, _b) in enumerate(MARKETER_TRAINING)
             if s not in OPEN_FROM_DAY_ONE]
    try:
        place = order.index(global_index)
    except ValueError:
        return False
    weeks = max(0, (date.today() - partner_started(mk)).days) // 7
    return place >= COURSE_DRIP_PER_WEEK * (weeks + 1)


def drip_opens_on(mk, global_index):
    """The date a locked lesson opens, so we can say it rather than just say no."""
    order = [i for i, (s, _r, _t, _b) in enumerate(MARKETER_TRAINING)
             if s not in OPEN_FROM_DAY_ONE]
    try:
        place = order.index(global_index)
    except ValueError:
        return None
    weeks_needed = place // max(1, COURSE_DRIP_PER_WEEK)
    return partner_started(mk) + timedelta(weeks=weeks_needed)


def lessons_still_to_come(mk):
    """How many are still on their way, so the page can say so."""
    if not mk or mk.get("owner"):
        return 0
    return sum(1 for i, _s, _t in lessons_for(mk) if drip_locked(mk, i))



def is_pu_partner(mk):
    """PU Prime side: the tick, or a link if the tick predates it. Marking her
    PU before her link arrives is normal, the link follows."""
    if not mk:
        return False
    if mk.get("owner"):
        return True
    return bool(mk.get("is_pu")) or bool((mk.get("pu_link") or "").strip())


def charlotte_partner():
    """Charlotte's own partner identity, so the owner sees the partner side as
    herself from her admin login. id 0 means direct clients: everyone not
    matched to another partner."""
    return {"id": 0, "name": "Charlotte", "aliases": "", "rate": None,
            "pu_link": PU_CHARLOTTE_LINK or "", "is_kudo": True, "password": "",
            "member_id": None, "owner": True}


def get_partner_videos():
    conn = get_db()
    if not conn:
        return []
    try:
        with conn.cursor() as cur:
            cur.execute("""SELECT id, title, blurb, embed, side FROM partner_videos
                           ORDER BY position ASC, id DESC""")
            return [dict(zip(("id", "title", "blurb", "embed", "side"), r)) for r in cur.fetchall()]
    except Exception:
        return []
    finally:
        conn.close()


def add_partner_video(title, blurb, raw_url, side="all"):
    """Only YouTube and Vimeo links, the same guard as everywhere else."""
    embed = video_embed_url(raw_url)
    if not embed or not (title or "").strip():
        return None
    conn = get_db()
    if not conn:
        return None
    try:
        with conn, conn.cursor() as cur:
            cur.execute("""INSERT INTO partner_videos (title, blurb, embed, side)
                           VALUES (%s,%s,%s,%s) RETURNING id""",
                        (title.strip()[:120], (blurb or "").strip()[:400], embed,
                         side if side in ("all", "kudo", "pu") else "all"))
            got = cur.fetchone()
            return got[0] if got else None
    finally:
        conn.close()


def delete_partner_video(vid):
    conn = get_db()
    if not conn:
        return
    try:
        with conn, conn.cursor() as cur:
            cur.execute("DELETE FROM partner_videos WHERE id=%s", (vid,))
    finally:
        conn.close()


def videos_for(mk):
    """The videos this partner should see: everything general, plus her own
    side. Charlotte sees the lot."""
    vids = get_partner_videos()
    if mk and mk.get("owner"):
        return vids
    is_kudo = bool(mk.get("is_kudo")) if mk else True
    is_pu = is_pu_partner(mk) if mk else True
    return [v for v in vids
            if v.get("side") in (None, "", "all")
            or (v["side"] == "kudo" and is_kudo)
            or (v["side"] == "pu" and is_pu)]


