def listen_widget(target_id="listen-body", label="Listen to this"):
    """
    A speaker button that reads the lesson aloud, using the voice built into
    the phone or laptop. Nothing is uploaded and nothing is downloaded; it just
    speaks. If a device can't do it, the button quietly hides itself.
    """
    return f'''
<div class="listen-bar" style="display:none; align-items:center; gap:10px; flex-wrap:wrap;
     border:1px solid var(--line); border-radius:12px; padding:10px 14px; margin:0 0 22px;">
  <button type="button" class="btn btn-ghost btn-sm listen-play" style="padding:7px 14px;">
    &#128266; {label}</button>
  <button type="button" class="btn btn-ghost btn-sm listen-pause" style="padding:7px 14px; display:none;">
    Pause</button>
  <button type="button" class="btn btn-ghost btn-sm listen-stop" style="padding:7px 14px; display:none;">
    Stop</button>
  <label style="display:flex; align-items:center; gap:6px; font-size:12.5px; color:var(--ink-dim);">
    Speed
    <select class="listen-speed" style="width:auto; padding:5px 8px; font-size:12.5px;">
      <option value="0.9">Slower</option>
      <option value="1" selected>Normal</option>
      <option value="1.25">Faster</option>
      <option value="1.5">Fastest</option>
    </select>
  </label>
  <span class="listen-note" style="font-size:12.5px; color:var(--ink-dim);"></span>
</div>
<script>
(function () {{
  // The lesson text sits BELOW this script, so wait for the page to finish
  // before looking for it, otherwise the button hides itself every time.
  var bar = document.currentScript && document.currentScript.previousElementSibling;
  if (!bar || bar.className !== 'listen-bar') {{
    var all = document.getElementsByClassName('listen-bar');
    bar = all.length ? all[all.length - 1] : null;
  }}
  if (!bar || !('speechSynthesis' in window)) return;

  function start() {{
    var body = document.getElementById('{target_id}');
    if (!body) return;
    bar.style.display = 'flex';
    wire(bar, body);
  }}
  if (document.readyState === 'loading') {{
    document.addEventListener('DOMContentLoaded', start);
  }} else {{
    start();
  }}

  function wire(bar, body) {{
  var playBtn = bar.querySelector('.listen-play');
  var pauseBtn = bar.querySelector('.listen-pause');
  var stopBtn = bar.querySelector('.listen-stop');
  var speedSel = bar.querySelector('.listen-speed');
  var note = bar.querySelector('.listen-note');
  var chunks = [], at = 0, speaking = false;

  function build() {{
    var text = (body.innerText || body.textContent || '').replace(/[ \\t\\n\\r]+/g, ' ').trim();
    chunks = [];
    // Phones stop long speeches, so feed it a few sentences at a time.
    var sentences = text.match(/[^.!?]+[.!?]*/g) || [text];
    var buf = '';
    sentences.forEach(function (s) {{
      if ((buf + s).length > 220) {{ chunks.push(buf.trim()); buf = ''; }}
      buf += s;
    }});
    if (buf.trim()) chunks.push(buf.trim());
  }}

  function speakFrom(i) {{
    if (i >= chunks.length) {{ reset(); note.textContent = 'Finished'; return; }}
    at = i;
    var u = new SpeechSynthesisUtterance(chunks[i]);
    u.rate = parseFloat(speedSel.value || '1');
    u.onend = function () {{ if (speaking) speakFrom(i + 1); }};
    u.onerror = function () {{ reset(); note.textContent = 'That stopped unexpectedly, try again.'; }};
    window.speechSynthesis.speak(u);
    note.textContent = 'Part ' + (i + 1) + ' of ' + chunks.length;
  }}

  function reset() {{
    speaking = false;
    window.speechSynthesis.cancel();
    playBtn.style.display = 'inline-flex';
    playBtn.innerHTML = '&#128266; {label}';
    pauseBtn.style.display = 'none';
    stopBtn.style.display = 'none';
  }}

  playBtn.addEventListener('click', function () {{
    if (!chunks.length) build();
    window.speechSynthesis.cancel();
    speaking = true;
    playBtn.style.display = 'none';
    pauseBtn.style.display = 'inline-flex';
    pauseBtn.textContent = 'Pause';
    stopBtn.style.display = 'inline-flex';
    speakFrom(0);
  }});

  pauseBtn.addEventListener('click', function () {{
    if (window.speechSynthesis.paused) {{
      window.speechSynthesis.resume();
      pauseBtn.textContent = 'Pause';
    }} else {{
      window.speechSynthesis.pause();
      pauseBtn.textContent = 'Carry on';
    }}
  }});

  stopBtn.addEventListener('click', function () {{ reset(); note.textContent = ''; }});
  speedSel.addEventListener('change', function () {{
    if (speaking) {{ window.speechSynthesis.cancel(); speakFrom(at); }}
  }});
  window.addEventListener('beforeunload', function () {{ window.speechSynthesis.cancel(); }});
  }}
}})();
</script>'''


def fav_owner():
    """Who is starring: a partner in their hub, or a member on the site."""
    if session.get("marketer_id"):
        return "partner", session["marketer_id"]
    if session.get("admin"):
        return "partner", 0
    if session.get("member_id"):
        return "member", session["member_id"]
    return None, None


def get_favourites(item_kind=None):
    kind, oid = fav_owner()
    if kind is None:
        return []
    conn = get_db()
    if not conn:
        return []
    try:
        with conn.cursor() as cur:
            if item_kind:
                cur.execute("""SELECT item_kind, item_ref, label FROM favourites
                               WHERE owner_kind=%s AND owner_id=%s AND item_kind=%s
                               ORDER BY created_at DESC""", (kind, oid, item_kind))
            else:
                cur.execute("""SELECT item_kind, item_ref, label FROM favourites
                               WHERE owner_kind=%s AND owner_id=%s
                               ORDER BY created_at DESC""", (kind, oid))
            return [{"item_kind": r[0], "item_ref": r[1], "label": r[2]} for r in cur.fetchall()]
    except Exception:
        return []
    finally:
        conn.close()


def is_favourite(item_kind, item_ref):
    return any(f["item_ref"] == str(item_ref) and f["item_kind"] == item_kind
               for f in get_favourites(item_kind))


def star_button(item_kind, item_ref, label, back):
    """The star itself. Gold and filled when it's saved, outline when it isn't."""
    kind, _oid = fav_owner()
    if kind is None:
        return ""
    on = is_favourite(item_kind, item_ref)
    return (f'<form method="POST" action="/favourite" style="display:inline;">'
            f'<input type="hidden" name="item_kind" value="{esc(item_kind)}">'
            f'<input type="hidden" name="item_ref" value="{esc(str(item_ref))}">'
            f'<input type="hidden" name="label" value="{esc(label)}">'
            f'<input type="hidden" name="back" value="{esc(back)}">'
            f'<button type="submit" title="{"Saved to your favourites" if on else "Save to favourites"}" '
            f'style="background:none; border:0; cursor:pointer; font-size:19px; padding:0 4px; '
            f'color:{"var(--gold-bright)" if on else "var(--ink-dim)"};">'
            f'{"&#9733;" if on else "&#9734;"}</button></form>')


PROSPECT_STAGES = ["to follow", "following", "follow up now", "talking", "sent the info",
                   "thinking about it", "ready to start", "onboarding", "not for now"]


@app.route("/partners/account", methods=["GET", "POST"])
def partner_account():
    """
    Her own details in one place: partner login, member access code, and a way
    to change her password herself so it's private to her.
    """
    mk = current_marketer()
    if not mk or mk.get("owner"):
        return redirect("/partners")
    msg = ""

    if request.method == "POST" and request.form.get("what") == "ask":
        wanted = request.form.get("for") or ""
        label = {"her": "Female Wealth", "signals": "the extra signals"}.get(wanted, wanted)
        notify_admin(f"\U0001F64B ACCESS REQUEST\n\n{mk['name']} would like {label}."
                     + (f"\n\nOpen her: {SITE}/admin/member/{mk['member_id']}"
                        if mk.get("member_id") else "\n\nShe has no member account linked yet."))
