    if request.method == "POST" and request.form.get("what") == "password":
        new = (request.form.get("new_password") or "").strip()[:120]
        again = (request.form.get("again") or "").strip()[:120]
        if len(new) < 4:
            msg = ('<p style="color:var(--rose, #C4707F);">Pick something at least four '
                   'characters long.</p>')
        elif new != again:
            msg = '<p style="color:var(--rose, #C4707F);">Those two didn\'t match, try again.</p>'
        else:
            conn = get_db()
            if conn:
                try:
                    with conn, conn.cursor() as cur:
                        cur.execute("UPDATE marketers SET password=%s WHERE id=%s", (new, mk["id"]))
                finally:
                    conn.close()
            notify_admin(f"\U0001F511 {mk['name']} changed her own partner password.")
            return redirect("/partners/account?changed=1")

    member = get_member_by_id(mk["member_id"]) if mk.get("member_id") else None
