@app.route("/partners/prospects", methods=["GET", "POST"])
def partner_prospects():
    """
    Her own list of people: who to follow, who she's talking to, where each one
    is up to. Private to her, and nobody is chased from here, it's just so
    nobody gets forgotten.
    """
    mk = current_marketer()
    if not mk:
        return redirect("/partners")
    mkid = mk["id"]

    if request.method == "POST":
        action = request.form.get("action") or "add"
        conn = get_db()
        if conn:
            try:
                with conn, conn.cursor() as cur:
                    this_month = date.today().strftime("%Y-%m")
                    if action == "add":
                        name = (request.form.get("name") or "").strip()[:80]
                        if name:
                            cur.execute("""INSERT INTO partner_prospects
                                           (marketer_id, name, instagram, tiktok, phone, stage,
                                            notes, month)
                                           VALUES (%s,%s,%s,%s,%s,%s,%s,%s)""",
                                        (mkid, name,
                                         (request.form.get("instagram") or "").strip()[:60],
                                         (request.form.get("tiktok") or "").strip()[:60],
                                         (request.form.get("phone") or "").strip()[:40],
                                         (request.form.get("stage") or "to follow")[:40],
                                         (request.form.get("notes") or "").strip()[:400],
                                         this_month))
                    elif action == "update":
                        pid = int(request.form.get("pid") or 0)
                        # "remind me in N days": nothing typed means leave it alone
                        follow = None
                        set_follow = False
                        raw_days = (request.form.get("days") or "").strip()
                        if request.form.get("remind"):
                            try:
                                follow = date.today() + timedelta(days=max(1, min(90, int(raw_days or 3))))
                                set_follow = True
                            except Exception:
                                set_follow = False
                        elif request.form.get("remind_off"):
                            follow, set_follow = None, True
                        onboarded = bool(request.form.get("onboarded"))
                        if set_follow or onboarded:
                            cur.execute("""UPDATE partner_prospects SET stage=%s, onboarded=%s,
                                           notes=%s, follow_up_on=%s, updated_at=NOW()
                                           WHERE id=%s AND marketer_id=%s""",
                                        ((request.form.get("stage") or "to follow")[:40],
                                         onboarded,
                                         (request.form.get("notes") or "").strip()[:400],
                                         None if onboarded else follow, pid, mkid))
                        else:
                            cur.execute("""UPDATE partner_prospects SET stage=%s, onboarded=%s,
                                           notes=%s, updated_at=NOW()
                                           WHERE id=%s AND marketer_id=%s""",
                                        ((request.form.get("stage") or "to follow")[:40],
                                         onboarded,
                                         (request.form.get("notes") or "").strip()[:400], pid, mkid))
                    elif action == "carry":
                        pid = int(request.form.get("pid") or 0)
                        cur.execute("""UPDATE partner_prospects SET month=%s, updated_at=NOW()
                                       WHERE id=%s AND marketer_id=%s""",
                                    (this_month, pid, mkid))
                    elif action == "park":
                        pid = int(request.form.get("pid") or 0)
                        cur.execute("""UPDATE partner_prospects SET stage='not for now',
                                       follow_up_on=NULL, month='parked', updated_at=NOW()
                                       WHERE id=%s AND marketer_id=%s""", (pid, mkid))
                    elif action == "delete":
                        pid = int(request.form.get("pid") or 0)
                        cur.execute("DELETE FROM partner_prospects WHERE id=%s AND marketer_id=%s",
                                    (pid, mkid))
            except Exception:
                pass
            finally:
                conn.close()
        return redirect("/partners/prospects")

    rows, carried = [], []
    conn = get_db()
    if conn:
        try:
            this_month = date.today().strftime("%Y-%m")
            with conn.cursor() as cur:
                cur.execute("""SELECT id, name, instagram, tiktok, phone, stage, onboarded, notes,
                                      follow_up_on, month
                               FROM partner_prospects WHERE marketer_id=%s
                                 AND (month = %s OR month IS NULL OR month = '')
                               ORDER BY onboarded ASC, updated_at DESC""", (mkid, this_month))
                rows = cur.fetchall() or []
                cur.execute("""SELECT id, name, instagram, tiktok, stage, notes, month
                               FROM partner_prospects WHERE marketer_id=%s
                                 AND onboarded = FALSE AND month <> %s AND month <> 'parked'
                                 AND month <> '' AND month IS NOT NULL
                               ORDER BY updated_at DESC LIMIT 60""", (mkid, this_month))
                carried = cur.fetchall() or []
        except Exception:
            rows, carried = rows or [], carried or []
        finally:
            conn.close()

    def stage_select(name, current):
        opts = "".join(f'<option value="{esc(s)}"{" selected" if s == current else ""}>{esc(s)}</option>'
                       for s in PROSPECT_STAGES)
        return (f'<select name="{name}" style="width:auto; padding:6px 10px; font-size:12.5px;">'
                f'{opts}</select>')

    cards = ""
    for pid, name, ig, tt, phone, stage, onboarded, notes, follow_on, _mth in rows:
        handles = " &middot; ".join(filter(None, [
            f'IG {esc(ig)}' if ig else "", f'TikTok {esc(tt)}' if tt else "",
            esc(phone) if phone else ""]))
        cards += (
            f'<div style="border:1px solid var(--line); border-radius:12px; padding:14px 16px; '
            f'margin-bottom:10px;{" opacity:.62;" if onboarded else ""}">'
            f'<div style="display:flex; justify-content:space-between; gap:10px; align-items:center;">'
            f'<strong style="font-size:15.5px;">{esc(name)}</strong>'
            + ('<span style="color:var(--gold-bright); font-size:12.5px; font-weight:700;">'
               'ONBOARDED</span>' if onboarded else
               f'<span style="color:var(--ink-dim); font-size:12.5px;">{esc(stage)}</span>')
            + '</div>'
            + (f'<div style="color:var(--ink-dim); font-size:13px; margin-top:4px;">{handles}</div>'
               if handles else "")
            + f'<form method="POST" style="display:flex; gap:8px; flex-wrap:wrap; align-items:center; '
              f'margin-top:10px;">'
              f'<input type="hidden" name="action" value="update">'
              f'<input type="hidden" name="pid" value="{pid}">'
              f'{stage_select("stage", stage)}'
              f'<label style="display:flex; gap:6px; align-items:center; font-size:12.5px; '
              f'color:var(--ink-dim);"><input type="checkbox" name="onboarded" value="1" '
              f'style="width:auto;"{" checked" if onboarded else ""}> Onboarded</label>'
              f'<input name="notes" value="{esc(notes or "")}" placeholder="Where are they up to?" '
              f'style="flex:1; min-width:180px; padding:6px 10px; font-size:12.5px;">'
              + f'<button class="btn btn-ghost btn-sm" style="padding:5px 12px; font-size:11.5px;">'
              f'Save</button></form>'
              + ("" if onboarded else
                 f'<form method="POST" style="display:flex; gap:6px; flex-wrap:wrap; '
                 f'align-items:center; margin-top:8px; font-size:12.5px; color:var(--ink-dim);">'
                 f'<input type="hidden" name="action" value="update">'
                 f'<input type="hidden" name="pid" value="{pid}">'
                 f'<input type="hidden" name="stage" value="{esc(stage)}">'
                 f'<input type="hidden" name="notes" value="{esc(notes or "")}">'
                 f'<input type="hidden" name="remind" value="1">'
                 f'<span>&#9200; Follow up with {esc(name.split(" ")[0])} in</span>'
                 f'<input name="days" value="5" style="width:52px; padding:5px 8px; '
                 f'font-size:12.5px;">'
                 f'<span>days</span>'
                 f'<button class="btn btn-ghost btn-sm" style="padding:4px 10px; font-size:11px;">'
                 f'Set reminder</button></form>')
              + (f'<div style="font-size:12.5px; color:var(--gold-bright); margin-top:6px;">'
                 f'&#9200; Reminder set for {esc(fmt_date(follow_on))}'
                 f'<form method="POST" style="display:inline; margin-left:8px;">'
                 f'<input type="hidden" name="action" value="update">'
                 f'<input type="hidden" name="pid" value="{pid}">'
                 f'<input type="hidden" name="stage" value="{esc(stage)}">'
                 f'<input type="hidden" name="notes" value="{esc(notes or "")}">'
                 f'<input type="hidden" name="remind_off" value="1">'
                 f'<button class="btn btn-ghost btn-sm" style="padding:3px 8px; font-size:10.5px;">'
                 f'Turn off</button></form></div>'
                 if follow_on and not onboarded else "")
            + f'<form method="POST" style="margin-top:6px;">' 
              f'<input type="hidden" name="action" value="delete">'
              f'<input type="hidden" name="pid" value="{pid}">'
              f'<button class="btn btn-ghost btn-sm" style="padding:4px 10px; font-size:11px;">'
              f'Remove</button></form>'
            + '</div>')
    if not cards:
        cards = ('<p style="color:var(--ink-dim); font-size:15px;">Nobody on your list yet. Add the '
                 'first person below: someone whose content you want to follow, or anyone who has '
                 'already asked you a question.</p>')

    live = sum(1 for r in rows if not r[6])
    done = sum(1 for r in rows if r[6])

    due_html = ""
    due_rows = [r for r in rows if not r[6] and r[8] and r[8] <= date.today()]
    if due_rows:
        items = "".join(
            f'<div style="display:flex; gap:10px; flex-wrap:wrap; align-items:center; '
            f'padding:10px 14px; border-bottom:1px solid var(--line); font-size:14px;">'
            f'<span style="flex:1; min-width:150px;"><strong>Follow up with {esc(r[1])}</strong>'
            + (f'<span style="color:var(--ink-dim); font-size:12.5px;"> &middot; {esc(r[7])}</span>'
               if r[7] else "")
            + '</span>'
            f'<form method="POST" style="display:inline;">'
            f'<input type="hidden" name="action" value="update">'
            f'<input type="hidden" name="pid" value="{r[0]}">'
            f'<input type="hidden" name="stage" value="{esc(r[5])}">'
            f'<input type="hidden" name="notes" value="{esc(r[7] or "")}">'
            f'<input type="hidden" name="remind" value="1">'
            f'<input type="hidden" name="days" value="3">'
            f'<button class="btn btn-ghost btn-sm" style="padding:4px 10px; font-size:11px;">'
            f'Done, remind me again in 3 days</button></form>'
            f'<form method="POST" style="display:inline;">'
            f'<input type="hidden" name="action" value="update">'
            f'<input type="hidden" name="pid" value="{r[0]}">'
            f'<input type="hidden" name="stage" value="{esc(r[5])}">'
            f'<input type="hidden" name="notes" value="{esc(r[7] or "")}">'
            f'<input type="hidden" name="remind_off" value="1">'
            f'<button class="btn btn-ghost btn-sm" style="padding:4px 10px; font-size:11px;">'
            f'Clear</button></form></div>' for r in due_rows)
        due_html = (f'<div style="border:1px solid var(--gold, #8A6D3B); border-radius:12px; '
                    f'overflow:hidden; margin:18px 0 26px;">'
                    f'<div style="padding:12px 14px 8px;"><strong>Due today</strong>'
                    f'<span style="color:var(--ink-dim); font-size:12.5px;"> &middot; the bot has '
                    f'messaged you about these</span></div>{items}</div>')

    carry_html = ""
    if carried:
        rows_c = ""
        for cid, cname, cig, ctt, cstage, cnotes, cmonth in carried:
            rows_c += (
                f'<div style="display:flex; gap:10px; flex-wrap:wrap; align-items:center; '
                f'padding:11px 14px; border-bottom:1px solid var(--line); font-size:14px;">'
                f'<span style="flex:1; min-width:160px;"><strong>{esc(cname)}</strong>'
                f'<span style="color:var(--ink-dim); font-size:12.5px;"> &middot; {esc(cstage)}'
                + (f' &middot; {esc(cig)}' if cig else "")
                + f' &middot; from {esc(cmonth)}</span></span>'
                f'<form method="POST" style="display:inline;">'
                f'<input type="hidden" name="action" value="carry">'
                f'<input type="hidden" name="pid" value="{cid}">'
                f'<button class="btn btn-ghost btn-sm" style="padding:5px 12px; font-size:11.5px;">'
                f'Bring into this month</button></form>'
                f'<form method="POST" style="display:inline;">'
                f'<input type="hidden" name="action" value="park">'
                f'<input type="hidden" name="pid" value="{cid}">'
                f'<button class="btn btn-ghost btn-sm" style="padding:5px 10px; font-size:11px;">'
                f'Leave for now</button></form></div>')
        carry_html = (
            f'<h2 style="font-size:20px; margin:34px 0 8px;">Still open from before</h2>'
            f'<p style="color:var(--ink-dim); font-size:13.5px; margin:0 0 12px;">Your list starts '
            f'fresh each month, so nothing piles up. Anyone who didn\'t onboard waits here: bring '
            f'them into this month if you\'re still working on them, or leave them for now and '
            f'they will sit quietly until you want them.</p>'
            f'<div style="border:1px solid var(--line); border-radius:12px; overflow:hidden;">'
            f'{rows_c}</div>')
    content = f"""
<section style="padding: 48px 0 80px;">
  <div class="wrap" style="max-width: 760px;">
    <a href="/partners" class="inline-link" style="font-size:13px;">&#8592; Partner home</a>
    <span class="eyebrow" style="display:block; margin-top:18px;">Private to you</span>
    <h1 style="font-size: 32px; margin: 10px 0 8px;">Your people</h1>
    <p style="color:var(--ink-dim); font-size:15px; line-height:1.9;">Everyone you're following,
      talking to, or looking after. Nobody gets chased from here, it's simply so nobody gets
      forgotten, which is where most partners quietly lose income.</p>
    <p style="color:var(--ink-dim); font-size:13.5px;">{date.today().strftime("%B")} &middot;
      {live} in progress &middot; {done} onboarded</p>
    <p style="color:var(--ink-dim); font-size:13px;">Set a follow up on anyone and the bot messages
      <strong>you</strong> on the day, never them, with their name and your note. Mark them
      onboarded and it stops on its own.</p>
    {due_html}

    <h2 style="font-size:20px; margin:30px 0 10px;">Add someone</h2>
    <form method="POST" style="display:grid; gap:10px; margin-bottom:30px;">
      <input type="hidden" name="action" value="add">
      <input name="name" placeholder="Their name" required>
      <input name="instagram" placeholder="Instagram handle, e.g. @sarah">
      <input name="tiktok" placeholder="TikTok handle">
      <input name="phone" placeholder="Phone number, if you have it">
      {stage_select("stage", "to follow")}
      <input name="notes" placeholder="Where are they at? Anything worth remembering">
      <button type="submit" class="btn btn-primary" style="justify-self:start;">Add to my list</button>
    </form>
    {cards}
    {carry_html}
  </div>
</section>"""
    return render_template_string(base_layout("Your people", content, "partnerprospects",
                                              theme="jade"))


