def modules_for(course, lessons):
    """The modules inside one course, in order, each with its lessons."""
    out, seen = [], {}
    for gi, sec, title in lessons:
        if sec != course:
            continue
        mod = LESSON_MODULE.get(title, "Lessons")
        if mod not in seen:
            seen[mod] = []
            out.append((mod, seen[mod]))
        seen[mod].append((gi, sec, title))
    return out


def slugify_section(name):
    """Course names into tidy web addresses: 'Social media: basics' becomes
    social-media-basics."""
    out = "".join(c.lower() if c.isalnum() else "-" for c in name)
    while "--" in out:
        out = out.replace("--", "-")
    return out.strip("-")


def workbook_page_for(day):
    """One prompt a day, rotating. Some days a question, some days a quote to
    sit with, some days a blank page for whatever's on your mind."""
    return WORKBOOK_PAGES[day.toordinal() % len(WORKBOOK_PAGES)]


