@app.route("/favourite", methods=["POST"])
def toggle_favourite():
    """Star or unstar. Same button either way."""
    kind, oid = fav_owner()
    back = request.form.get("back") or "/"
    if kind is None:
        return redirect(back if back.startswith("/") else "/")
    item_kind = (request.form.get("item_kind") or "")[:40]
    item_ref = (request.form.get("item_ref") or "")[:80]
    label = (request.form.get("label") or "")[:160]
    if item_kind and item_ref:
        conn = get_db()
        if conn:
            try:
                with conn, conn.cursor() as cur:
                    cur.execute("""DELETE FROM favourites WHERE owner_kind=%s AND owner_id=%s
                                   AND item_kind=%s AND item_ref=%s""",
                                (kind, oid, item_kind, item_ref))
                    if cur.rowcount == 0:
                        cur.execute("""INSERT INTO favourites
                                       (owner_kind, owner_id, item_kind, item_ref, label)
                                       VALUES (%s,%s,%s,%s,%s)
                                       ON CONFLICT DO NOTHING""",
                                    (kind, oid, item_kind, item_ref, label))
            finally:
                conn.close()
    return redirect(back if back.startswith("/") else "/")


def current_marketer():
    mkid = session.get("marketer_id")
    if mkid:
        return next((m for m in get_marketers() if m["id"] == mkid), None)
    if session.get("admin"):
        # the owner, on her own partner side
        return charlotte_partner()
    return None


def find_member_for_partner(phone="", email="", name=""):
    """Match a partner to her own member account. Phone first because it's the
    thing we tie everything else by, then email, then an exact name."""
    conn = get_db()
    if not conn:
        return None
    try:
        norm = normalize_phone(phone or "")
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            if norm:
                cur.execute("""SELECT * FROM members WHERE phone_normalized=%s
                               AND merged_into IS NULL ORDER BY id LIMIT 1""", (norm,))
                hit = cur.fetchone()
                if hit:
                    return hit
            if (email or "").strip():
                cur.execute("""SELECT * FROM members WHERE LOWER(COALESCE(email,''))=LOWER(%s)
                               AND merged_into IS NULL ORDER BY id LIMIT 1""", (email.strip(),))
                hit = cur.fetchone()
                if hit:
                    return hit
            if (name or "").strip():
                cur.execute("""SELECT * FROM members WHERE LOWER(TRIM(COALESCE(name,'')))=LOWER(TRIM(%s))
                               AND merged_into IS NULL ORDER BY id LIMIT 1""", (name.strip(),))
                return cur.fetchone()
    except Exception:
        return None
    finally:
        conn.close()
    return None


def partner_applications(status="pending"):
    conn = get_db()
    if not conn:
        return []
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("""SELECT * FROM partner_applications WHERE status=%s
                           ORDER BY created_at DESC LIMIT 100""", (status,))
            return cur.fetchall() or []
    except Exception:
        return []
    finally:
        conn.close()


@app.route("/become-a-partner/apply", methods=["POST"])
def become_a_partner_apply():
    """Their application. Nothing is created until Charlotte approves it."""
    name = (request.form.get("name") or "").strip()[:80]
    phone = (request.form.get("phone") or "").strip()[:40]
    if not name or not normalize_phone(phone):
        return redirect("/become-a-partner?err=" + quote(
            "Please give your name and a real phone number so we can find your account."))
    email = (request.form.get("email") or "").strip()[:120]
    socials = (request.form.get("socials") or "").strip()[:200]
    note = (request.form.get("note") or "").strip()[:1000]
    hit = find_member_for_partner(phone, email, name)
    conn = get_db()
    if conn:
        try:
            with conn, conn.cursor() as cur:
                cur.execute("""INSERT INTO partner_applications
                               (name, phone, phone_normalized, email, socials, note, member_id)
                               VALUES (%s,%s,%s,%s,%s,%s,%s)""",
                            (name, phone, normalize_phone(phone), clean_email(email),
                             socials, note, hit["id"] if hit else None))
        finally:
            conn.close()
    notify_admin(f"\U0001F91D PARTNER APPLICATION\n\n{name}\n{phone}\n{socials}\n\n"
                 + (f"Matched to member #{hit['id']} ({hit.get('name') or ''}), ready to "
                    f"approve in one tap." if hit else
                    "No member account matched yet, they may not have onboarded.")
                 + f"\n\nApprove: {SITE}/admin/marketers")
    return redirect("/become-a-partner?sent=1")


