def partners_home(slug=None, module=None):
    """
    The marketers' own back door. Separate from admin and from the member site:
    each partner logs in with her name and the password Charlotte set, sees her
    own month log (read only, the ticks are Charlotte's alone) and the full
    partner training. Admin can look in with ?as=<id>; a partner can never see
    admin.
    """
    if request.method == "POST":
        name = (request.form.get("name") or "").strip().lower()
        pw = request.form.get("password") or ""
        mk = next((m for m in get_marketers()
                   if m["name"].strip().lower() == name and (m.get("password") or "") and
                   m.get("password") == pw), None)
        if mk:
            session["marketer_id"] = mk["id"]
            session.permanent = True
            if not mk.get("member_id"):
                # never linked by hand: find her member account by name and
                # link it now, so one login opens both sides. Never let this
                # get in the way of her logging in.
                try:
                    hit = find_member_for_partner("", "", mk["name"])
                    hit = hit if isinstance(hit, dict) and hit.get("id") else None
                except Exception:
                    hit = None
                if hit:
                    conn2 = get_db()
                    if conn2:
                        try:
                            with conn2, conn2.cursor() as cur2:
                                cur2.execute("UPDATE marketers SET member_id=%s WHERE id=%s",
                                             (hit["id"], mk["id"]))
                        finally:
                            conn2.close()
                    mk = dict(mk, member_id=hit["id"])
            if mk.get("member_id"):
                # her partner login opens her member account too: signals,
                # courses, everything she has access to as a member
                session["member_id"] = mk["member_id"]
            return redirect("/partners")
        return redirect("/partners?err=" + quote("That name and password don't match."))

