@app.route("/partners/lesson/<int:idx>")
def partners_lesson(idx):
    mk = current_marketer()
    if not mk and not session.get("admin"):
        return redirect("/partners")
    if not (0 <= idx < len(MARKETER_TRAINING)):
        return redirect("/partners")
    allowed = [gi for gi, _s, _t in lessons_for(mk or {})]
    if idx not in allowed:
        return redirect("/partners")
    if mk and drip_locked(mk, idx):
        _when = drip_opens_on(mk, idx)
        return redirect("/partners/courses?err=" + quote(
            "That one opens " + (fmt_date(_when) if _when else "soon")
            + ". Two new lessons open every week, so there is always something next."))
    section, _role, title, body = MARKETER_TRAINING[idx]
    # Long lessons are hard to face on a phone, so break them into cards: a
    # shouted heading starts a new card, single lines inside become spaced
    # points rather than one wall of text.
    def render_lesson(text):
        blocks, cur = [], {"head": "", "lines": []}
        for para in text.split("\n\n"):
            lines = [l for l in para.split("\n") if l.strip()]
            if not lines:
                continue
            first = lines[0].strip()
            is_head = (first.isupper() and len(first) > 3 and len(first) < 90)
            if is_head:
                if cur["head"] or cur["lines"]:
                    blocks.append(cur)
                cur = {"head": first, "lines": lines[1:]}
            else:
                cur["lines"].append("")
                cur["lines"].extend(lines)
        if cur["head"] or cur["lines"]:
            blocks.append(cur)

        SCRIPT_HEADS = ("FOR WOMEN", "FOR MEN", "SEND THIS", "WORD FOR WORD", "SCRIPT",
                        "COPY THIS", "SAY THIS", "WHEN THEY SAY YES", "THE VOICE NOTE",
                        "THE FOLLOW UP")
        out = ""
        for b in blocks:
            head = b["head"]
            is_script = any(k in head.upper() for k in SCRIPT_HEADS)
            inner = ""
            for line in b["lines"]:
                if not line.strip():
                    continue
                s = line.strip()
                if is_script:
                    # A script is read out loud or copied, so it stays as
                    # written: no bullets, no reformatting.
                    inner += f'<p class="lp-script">{esc(s)}</p>'
                    continue
                short_point = (len(s) < 190 and not s.endswith(":") and
                               (s[0].isdigit() or s.startswith('"') or s.count(".") <= 2))
                if short_point and len(b["lines"]) > 2:
                    inner += (f'<p class="lp-point">{esc(s)}</p>')
                else:
                    inner += f'<p class="lp-para">{esc(s)}</p>'
            out += (f'<div class="lesson-card{" script" if is_script else ""}">'
                    + (f'<h2 class="lp-head">{esc(head.title())}</h2>' if head else "")
                    + inner + '</div>')
        return out

    paras = render_lesson(body)

    # Your own recording for this lesson, if you have added one. A real voice
    # beats a device voice every time, especially for the scripts.
    # Your own recording for this lesson: either one you uploaded here, or a
    # link you pasted in. Uploaded wins, because it never breaks.
    uploaded_here = has_lesson_audio(idx)
    own_url = (f"/lesson-audio/{idx}" if uploaded_here
               else (_meta_get(f"lessonaudio:{idx}") or "").strip())
    own_audio = ""
    if own_url:
        own_audio = (
            f'<div style="border:1px solid var(--gold, #8A6D3B); border-radius:12px; '
            f'padding:14px 16px; margin:0 0 18px;">'
            f'<strong style="font-size:14.5px;">&#127908; Hear it from admin</strong>'
            f'<div style="color:var(--ink-dim); font-size:13px; margin:2px 0 10px;">The real '
            f'thing, in her own voice. Copy the tone, not just the words.</div>'
            f'<audio controls preload="none" style="width:100%;" src="{esc(own_url)}"></audio>'
            f'</div>')
    audio_admin = ""
    if session.get("admin"):
        audio_admin = (
            f'<div style="border:1px dashed var(--line); border-radius:12px; padding:14px 16px; '
            f'margin:0 0 18px;">'
            f'<strong style="font-size:14px;">Your own recording, admin only</strong>'
            f'<div style="color:var(--ink-dim); font-size:12.5px; line-height:1.7; margin:4px 0 '
            f'10px;">Record a voice note on your phone, then upload the file straight here. '
            f'Nothing to host, nothing to link. Partners see a player at the top of this '
            f'lesson.</div>'
            f'<form method="POST" action="/admin/lesson-audio/upload" '
            f'enctype="multipart/form-data" style="display:flex; gap:8px; flex-wrap:wrap; '
            f'align-items:center;">'
            f'<input type="hidden" name="idx" value="{idx}">'
            f'<input type="hidden" name="back" value="/partners/lesson/{idx}">'
            f'<input type="file" name="audio" accept="audio/*" required '
            f'style="flex:1; min-width:200px; font-size:12.5px;">'
            f'<button class="btn btn-primary btn-sm" style="padding:6px 14px; font-size:12px;">'
            + ("Replace it" if uploaded_here else "Upload it")
            + '</button></form>'
            + (f'<form method="POST" action="/admin/lesson-audio/{idx}/delete" '
               f'style="margin-top:8px;">'
               f'<input type="hidden" name="back" value="/partners/lesson/{idx}">'
               f'<button class="btn btn-ghost btn-sm" style="padding:5px 12px; font-size:11.5px;">'
               f'Remove the recording</button></form>' if uploaded_here else "")
            + '</div>')
    nav = ""
    if idx > 0:
        nav += f'<a href="/partners/lesson/{idx - 1}" class="inline-link">&#8592; Previous</a>'
    if idx < len(MARKETER_TRAINING) - 1:
        nav += f'<a href="/partners/lesson/{idx + 1}" class="inline-link" style="float:right;">Next &#8594;</a>'
    content = f"""
<section style="padding: 48px 0 80px;">
  <div class="wrap" style="max-width: 680px;">
    <a href="/partners" class="inline-link" style="font-size:13px;">&#8592; Partner hub</a>
    <span class="eyebrow" style="display:block; margin-top:20px;">{esc(section)}</span>
    <div style="display:flex; align-items:flex-start; gap:10px; margin: 10px 0 20px;">
      <h1 style="font-size: 28px; margin:0; flex:1;">{esc(title)}</h1>
      {star_button("partner_lesson", idx, title, f"/partners/lesson/{idx}")}
    </div>
    <style>
      .lesson-card {{
        background: transparent; color: #2A2318; border-radius: 0;
        padding: 0 0 6px; margin: 0 0 22px;
        border-bottom: 1px solid rgba(42,35,24,.10);
      }}
      .lesson-card:last-of-type {{ border-bottom: 0; margin-bottom: 0; }}
      .lp-head {{
        font-family: 'Fraunces', Georgia, serif; font-size: 19px; line-height: 1.35;
        margin: 0 0 12px; color: #2A2318; letter-spacing: .01em;
      }}
      /* The page theme colours paragraphs light, which is right on the dark
         page and wrong inside a cream card, so these win explicitly. */
      .lesson-card, .lesson-card p, .lesson-card li, .lesson-card strong,
      .jade .lesson-card p, .jade .lesson-card li, .plum .lesson-card p,
      body .lesson-card p {{ color: #3A3227 !important; }}
      .lesson-card h2, .jade .lesson-card h2 {{ color: #2A2318 !important; }}
      .lp-para {{ font-size: 15.5px; line-height: 1.95; margin: 0 0 14px; }}
      .lp-point {{
        font-size: 15.5px; line-height: 1.85; margin: 0 0 12px;
        padding-left: 16px; position: relative;
      }}
      .lp-point::before {{
        content: ""; position: absolute; left: 0; top: 11px;
        width: 6px; height: 6px; border-radius: 50%; background: #C9A227;
      }}
      .lesson-card.script {{
        background: #FFFBEF; border-left: 4px solid #C9A227; border-bottom: 0;
        padding: 16px 18px; border-radius: 0 8px 8px 0;
      }}
      .lp-script {{
        font-size: 15.5px; line-height: 1.9; margin: 0 0 10px;
        white-space: pre-wrap;
      }}
      .lesson-card p:last-child {{ margin-bottom: 0; }}
      @media (max-width: 560px) {{ .lesson-card {{ padding: 18px 18px; }} }}
    </style>
    {own_audio}{audio_admin}
    {listen_widget("listen-body", "Listen to this lesson")}
    {BOOK_CSS}
    <div class="book-page"><div class="course-content" id="listen-body"
         style="font-size:15.5px; line-height:1.9;">{paras}</div></div>
    <div style="margin-top: 34px; overflow:auto;">{nav}</div>
  </div>
</section>"""
    return render_template_string(base_layout(title, content, "", theme="jade"))


