@app.route("/admin/marketers/import", methods=["POST"])
def admin_marketers_import():
    """
    The bridge to the Kudo back office: export the report there, drop the CSV
    here. Column names are found by keyword so the exact export format doesn't
    matter much: something like account or login, deposit, trades or closed,
    roi or return. Numbers land on the matching member by account number, and
    the three ticks set themselves only when a number clearly clears the bar.
    Unmatched rows are reported back, never guessed at, because this decides
    who gets paid.
    """
    if not session.get("admin"):
        return redirect(url_for("admin"))
    month = request.args.get("month") or date.today().strftime("%Y-%m")
    f = request.files.get("report")
    pasted = (request.form.get("pasted") or "").strip()
    rows = []
    if f and (f.filename or "").strip():
        looks_like_photo = (f.mimetype or "").startswith("image/") or \
            (f.filename or "").lower().endswith((".jpg", ".jpeg", ".png", ".heic", ".heif"))
        if looks_like_photo:
            try:
                blob = f.read()
            except Exception:
                blob = b""
            text = ocr_image_bytes(blob) if blob else None
            if text:
                rows = rows_from_text(text)
            if not rows:
                return redirect(f"/admin/marketers?month={month}&err=" + quote(
                    "That's a photo, and this server can't read pictures. On the page, choose the "
                    "photo and press Read this photo, or open it in Photos, tap the text icon, "
                    "Select All, Copy, and paste it into the box."))
        else:
            rows = read_rows_from_upload(f)
    elif pasted:
        # text: either a copied table, or what the browser read from a
        # screenshot. Same parsers either way.
        rows = rows_from_text(pasted)
    if not rows:
        return redirect(f"/admin/marketers?month={month}&err=" +
                        quote("Nothing readable arrived. Upload the CSV or Excel export, paste "
                              "the report text, or pick the screenshot and let it read itself."))

    header = [h.strip().lower() for h in rows[0]]

    def col(*keys):
        for i, h in enumerate(header):
            if any(k in h for k in keys):
                return i
        return None

    c_acct = col("account", "login", "mt5", "mt4")
    c_dep = col("net deposit", "deposit", "funded")
    c_trades = col("closed trades", "trades", "deals", "positions", "lots")
    c_roi = col("roi", "return", "profit factor")
    c_bal = col("balance", "equity", "net dep")
    c_comm = col("commission")
    c_name = col("customer", "name")
    if c_acct is None:
        # not a table: try the portal's block-per-client layout
        block_rows = parse_kudo_block_export(rows)
        if block_rows:
            rows = block_rows
            header = [h.lower() for h in rows[0]]
            c_acct, c_dep, c_trades, c_roi, c_bal, c_comm, c_name = 0, 1, 2, 3, 4, 5, 6
        else:
            return redirect(f"/admin/marketers?month={month}&err=" +
                            quote("Couldn't find an account column in that file. "
                                  "The header needs something like Account or Login."))

    def num(row, i):
        if i is None or i >= len(row):
            return None
        raw = "".join(ch for ch in str(row[i]) if ch.isdigit() or ch in ".-")
        try:
            return float(raw) if raw not in ("", "-", ".") else None
        except Exception:
            return None

    matched, ticked, created = 0, 0, 0
    missing = []
    conn = get_db()
    for row in rows[1:]:
        if c_acct >= len(row):
            continue
        acct = "".join(ch for ch in str(row[c_acct]) if ch.isdigit())
        if not acct:
            continue
        dep, trades, roi = num(row, c_dep), num(row, c_trades), num(row, c_roi)
        row_name = str(row[c_name]).strip() if (c_name is not None and c_name < len(row)) else ""
        label = f"{acct} ({row_name})" if row_name else acct
        if not conn:
            missing.append(label)
            continue
        try:
            with conn.cursor() as cur:
                cur.execute("""SELECT id FROM members
                               WHERE regexp_replace(COALESCE(account_number,''), '\\D', '', 'g') = %s
                                 AND merged_into IS NULL LIMIT 1""", (acct,))
                hit = cur.fetchone()
            if not hit:
                if request.args.get("create") == "1":
                    with conn, conn.cursor() as cur:
                        cur.execute("""INSERT INTO members (tier, title, name, account_number,
                                       deposit_amount, phone, status, referred_by, kudo_month,
                                       created_at, updated_at)
                                       VALUES ('gold', '', %s, %s, %s, '', 'approved', '', %s,
                                       NOW(), NOW()) RETURNING id""",
                                    (row_name or f"Kudo client {acct}", acct,
                                     "" if dep is None else str(dep), month))
                        hit = cur.fetchone()
                    audit(hit[0], "created from Kudo report",
                          f"account {acct}, counted in {month}")
                    created += 1
                else:
                    missing.append(label)
                    continue
            mid = hit[0]
            matched += 1
            sets, params = ["kudo_report_at=NOW()", "updated_at=NOW()"], []
            if dep is not None:
                sets.append("kudo_deposit=%s"); params.append(dep)
            if trades is not None:
                sets.append("kudo_trades=%s"); params.append(int(trades))
            if roi is not None:
                sets.append("kudo_roi=%s"); params.append(roi)
                ticked += 1
            bal = num(row, c_bal)
            if bal is not None:
                sets.append("kudo_balance=%s"); params.append(bal)
            comm = num(row, c_comm)
            if comm is not None:
                sets.append("kudo_commission=%s"); params.append(comm)
            sets.append("kudo_month=COALESCE(kudo_month, %s)"); params.append(month)
            if roi is None and bal is not None and dep:
                # the report gives deposit and balance rather than an ROI
                # column, so the ROI is worked out right here: balance over
                # deposit, the way the business means it
                sets.append("kudo_roi=%s"); params.append(round(bal / dep, 2))
                ticked += 1
            with conn, conn.cursor() as cur:
                cur.execute(f"UPDATE members SET {', '.join(sets)} WHERE id=%s", (*params, mid))
        except Exception:
            missing.append(label)
    if conn:
        conn.close()

    # the other direction: members with accounts the report never mentioned
    report_accts = set()
    for row in rows[1:]:
        if c_acct < len(row):
            a = "".join(ch for ch in str(row[c_acct]) if ch.isdigit())
            if a:
                report_accts.add(a)
    absent = []
    conn2 = get_db()
    if conn2:
        try:
            with conn2.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                cur.execute("""SELECT id, name, account_number FROM members
                               WHERE merged_into IS NULL AND COALESCE(account_number,'') <> ''""")
                for m in cur.fetchall():
                    a = "".join(ch for ch in str(m["account_number"]) if ch.isdigit())
                    if a and a not in report_accts:
                        absent.append({"id": m["id"], "name": m["name"], "acct": a})
        except Exception:
            pass
        finally:
            conn2.close()
    _meta_set("kudo_last_import", json.dumps({
        "at": datetime.utcnow().isoformat(), "matched": matched,
        "missing": missing[:50], "not_in_report": absent[:50]}))

    msg = f"Report in: {matched} member{'s' if matched != 1 else ''} matched, numbers and ROI updated on {ticked}."
    if created:
        msg += (f" {created} new record{'s' if created != 1 else ''} created from the report and "
                f"counted in {month}; they'll link automatically when each person onboards with "
                "the same account number.")
    if missing or absent:
        msg += f" Reconciliation below: {len(missing)} unknown to the site, {len(absent)} not in the report."
    return redirect(f"/admin/marketers?month={month}&ok=" + quote(msg))


@app.route("/admin/marketers/import-pu", methods=["POST"])
def admin_marketers_import_pu():
    """Charlotte's own PU Prime export: who's trading on her account and who
    isn't. Matches by PU account number, stores each client's trade count,
    and the chart on the PU tab recalculates the moment it lands."""
    if not session.get("admin"):
        return redirect(url_for("admin"))
    month = request.args.get("month") or date.today().strftime("%Y-%m")
    back = f"/admin/marketers?side=pu&month={month}"
    f = request.files.get("report")
    if not f:
        return redirect(back + "&err=" + quote("No file arrived."))
    rows = read_rows_from_upload(f)
    if not rows:
        return redirect(back + "&err=" + quote("Couldn't read that file. Export it as CSV or Excel and try again."))
    header = [h.strip().lower() for h in rows[0]]

    def col(*keys):
        for i, h in enumerate(header):
            if any(k in h for k in keys):
                return i
        return None

    c_acct = col("account", "login", "mt5", "mt4")
    c_trades = col("closed trades", "trades", "deals", "positions", "orders", "lots", "volume")
    c_balance = col("balance", "equity", "funds")
    c_comm = col("commiss", "rebate", "earned", "payout")
    if c_acct is None:
        return redirect(back + "&err=" + quote("Couldn't find an account column in that file."))

    matched, missing = 0, []
    conn = get_db()
    for row in rows[1:]:
        if c_acct >= len(row):
            continue
        acct = "".join(ch for ch in str(row[c_acct]) if ch.isdigit())
        if not acct:
            continue
        trades = 0
        if c_trades is not None and c_trades < len(row):
            digits = "".join(ch for ch in str(row[c_trades]) if ch.isdigit() or ch == ".")
            try:
                trades = int(float(digits)) if digits else 0
            except Exception:
                trades = 0
        commission = None
        if c_comm is not None and c_comm < len(row):
            digits = "".join(ch for ch in str(row[c_comm]) if ch.isdigit() or ch == ".")
            try:
                commission = float(digits) if digits else None
            except Exception:
                commission = None
        balance = None
        if c_balance is not None and c_balance < len(row):
            digits = "".join(ch for ch in str(row[c_balance]) if ch.isdigit() or ch == ".")
            try:
                balance = float(digits) if digits else None
            except Exception:
                balance = None
        if not conn:
            missing.append(acct)
            continue
        try:
            with conn.cursor() as cur:
                cur.execute("""SELECT id FROM members
                               WHERE regexp_replace(COALESCE(currency_account_number,''), '\\D', '', 'g') = %s
                                 AND merged_into IS NULL LIMIT 1""", (acct,))
                hit = cur.fetchone()
            if not hit:
                missing.append(acct)
                continue
            with conn, conn.cursor() as cur:
                cur.execute("""UPDATE members
                               SET pu_trades=%s,
                                   pu_balance=COALESCE(%s, pu_balance),
                                   pu_commission=COALESCE(%s, pu_commission),
                                   pu_report_at=NOW(), updated_at=NOW()
                               WHERE id=%s""", (trades, balance, commission, hit[0]))
                # And keep the history. Re-uploading the same day corrects that
                # day rather than adding a second row for it.
                cur.execute("""INSERT INTO pu_reports (member_id, trades)
                               VALUES (%s,%s)
                               ON CONFLICT (member_id, reported_on)
                               DO UPDATE SET trades = EXCLUDED.trades""", (hit[0], trades))
            matched += 1
        except Exception:
            missing.append(acct)
    if conn:
        conn.close()
    msg = f"PU report in: {matched} client{'s' if matched != 1 else ''} matched, chart updated."
    if missing:
        shown = ", ".join(missing[:8]) + ("..." if len(missing) > 8 else "")
        msg += f" {len(missing)} account{'s' if len(missing) != 1 else ''} not found here: {shown}"
    return redirect(back + "&ok=" + quote(msg))


