def launch_checklist():
    """
    The things that must be set before a door is opened to real people.
    Worked out from what's actually configured, not from a list I keep by hand,
    so it cannot quietly go stale.
    """
    items = []
    marketers = get_marketers()

    # PU Prime: every PU partner needs their own link, and so does the house
    pu_missing = [k["name"] for k in marketers
                  if is_pu_partner(k) and not (k.get("pu_link") or "").strip()]
    house_link = (PU_CHARLOTTE_LINK or "").strip()
    if pu_missing or not house_link:
        bits = []
        if pu_missing:
            bits.append("no link yet for " + ", ".join(esc(n) for n in pu_missing[:6])
                        + (f" and {len(pu_missing) - 6} more" if len(pu_missing) > 6 else ""))
        if not house_link:
            bits.append("PU_CHARLOTTE_LINK is not set on Render")
        items.append(("PU Prime links", "; ".join(bits),
                      "Until these are in, anyone sent to PU Prime lands nowhere or lands under "
                      "the wrong person, and the broker cannot be corrected afterwards.",
                      "/admin/marketers?side=pu"))
    if not pu_signals_open():
        items.append(("Extra signals are closed", "the page shows coming soon to everyone",
                      "Open them with the button on the PU Prime tab of Pay & partners, once "
                      "every link is in. No deploy needed.",
                      "/admin/marketers?side=pu"))

    # Advanced course payments: still marked off by hand
    items.append(("Course pay connection", "Advanced payments are confirmed by hand",
                  "Members pay you directly and you tick them off on their card. There is no "
                  "payment link wired in yet, so nothing is taken automatically.",
                  "/admin/photos"))
    return items


