@app.route("/admin/results/upload", methods=["POST"])
def admin_results_upload():
    """Upload result screenshots straight from your phone. They go into the
    database, so they are still there after the app file is replaced."""
    if not session.get("admin"):
        return redirect(url_for("admin"))
    files = request.files.getlist("shots")
    caption = (request.form.get("caption") or "").strip()[:160]
    saved = 0
    conn = get_db()
    if conn:
        try:
            with conn, conn.cursor() as cur:
                for f in files:
                    raw = f.read()
                    if not raw or len(raw) > 8 * 1024 * 1024:
                        continue
                    mime = f.mimetype or "image/jpeg"
                    if not mime.startswith("image/"):
                        continue
                    cur.execute("""INSERT INTO result_images (caption, mime, data)
                                   VALUES (%s,%s,%s)""",
                                (caption, mime, psycopg2.Binary(raw)))
                    saved += 1
        except Exception:
            pass
        finally:
            conn.close()
    msg = (f"{saved} screenshot{'s' if saved != 1 else ''} added to the results page."
           if saved else "Nothing was added, check the file is an image under 8MB.")
    return redirect("/admin/results?" + ("ok=" if saved else "err=") + quote(msg))


