@app.route("/admin/lesson-audio/upload", methods=["POST"])
def admin_lesson_audio_upload():
    """Record on your phone, upload it here. No hosting, no links."""
    if not session.get("admin"):
        return redirect(url_for("admin"))
    try:
        idx = int(request.form.get("idx") or -1)
    except Exception:
        idx = -1
    back = request.form.get("back") or "/partners/training"
    f = request.files.get("audio")
    if idx >= 0 and f:
        raw = f.read()
        mime = f.mimetype or "audio/mpeg"
