@app.route("/admin/partner-applications/<int:app_id>/approve", methods=["POST"])
def admin_partner_app_approve(app_id):
    """One tap: creates the partner, links her to her own member account if we
    can find it, and sets her hub password."""
    if not session.get("admin"):
        return redirect(url_for("admin"))
    conn = get_db()
    row = None
    if conn:
        try:
            with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                cur.execute("SELECT * FROM partner_applications WHERE id=%s", (app_id,))
                row = cur.fetchone()
        finally:
            conn.close()
    if not row:
        return redirect("/admin/marketers")

    pw = (request.form.get("password") or "").strip()[:120]
    if not pw:
        pw = secrets.token_urlsafe(6)
    try:
        rate = float((request.form.get("rate") or "0").replace("$", "").strip() or 0)
    except Exception:
        rate = 0
    hit = find_member_for_partner(row.get("phone") or "", row.get("email") or "", row["name"])
    add_marketer(row["name"], aliases=(row.get("socials") or ""), rate=rate,
                 pu_link="", is_kudo=True, password=pw)
    conn = get_db()
    new_id = None
    if conn:
        try:
            with conn, conn.cursor() as cur:
                cur.execute("SELECT id FROM marketers WHERE name=%s ORDER BY id DESC LIMIT 1",
                            (row["name"].strip()[:80],))
                got = cur.fetchone()
                new_id = got[0] if got else None
                if new_id and hit:
                    cur.execute("UPDATE marketers SET member_id=%s WHERE id=%s", (hit["id"], new_id))
                cur.execute("""UPDATE partner_applications SET status='approved', member_id=%s
                               WHERE id=%s""", (hit["id"] if hit else None, app_id))
        finally:
            conn.close()
    notify_admin(f"\u2705 PARTNER SET UP\n\n{row['name']}\nHub password: {pw}\n"
                 + (f"Linked to member #{hit['id']}, so her login opens the member site too."
                    if hit else
                    "No member account matched yet: link her by hand once she's onboarded.")
                 + f"\n\nSend her: {SITE}/partners")
    return redirect(f"/admin/marketers/{new_id}?month={date.today().strftime('%Y-%m')}"
                    if new_id else "/admin/marketers")


