@app.route("/admin/member/<int:member_id>/assign", methods=["POST"])
def admin_member_assign(member_id):
    """
    Appoint someone in holding to a partner, or keep them as Inner Circle.
    They get a message either way telling them exactly what to type if they
    want the extra signals later.
    """
    if not session.get("admin"):
        return redirect(url_for("admin"))
    raw = (request.form.get("to") or "").strip()
    marketers = get_marketers()

    # Put them back in the queue: clears the decision without guessing a new one
    if raw == "hold":
        conn = get_db()
        if conn:
            try:
                with conn, conn.cursor() as cur:
                    cur.execute("""UPDATE members SET referred_by='', attribution_set=FALSE,
                                   updated_at=NOW() WHERE id=%s""", (member_id,))
            finally:
                conn.close()
        audit(member_id, "assignment cleared", "back in the holding list")
        return redirect(request.referrer or "/admin/marketers")

    mk = next((m for m in marketers if str(m["id"]) == raw), None)
    who = mk["name"] if mk else "Inner Circle"
    conn = get_db()
    if conn:
        try:
            with conn, conn.cursor() as cur:
                cur.execute("""UPDATE members SET referred_by=%s, attribution_set=TRUE,
                               updated_at=NOW() WHERE id=%s""", (who, member_id))
        finally:
            conn.close()
    conn = get_db()
    if conn:
        try:
            with conn, conn.cursor() as cur:
                _mm = get_member_by_id(member_id)
                _mph = _mm.get("phone") if isinstance(_mm, dict) else ""
                cur.execute("""UPDATE partner_claims SET status='assigned'
                               WHERE status='open' AND (member_id=%s OR phone_normalized=%s)""",
                            (member_id, normalize_phone(_mph or "")))
        except Exception:
            pass
        finally:
            conn.close()
    audit(member_id, "assigned", f"counted to {who}")
    _pending = _meta_get(f"assignnote:{member_id}") or ""
    if _pending and "|" in _pending:
        _due, _old_who, _chat = (_pending.split("|") + ["", ""])[:3]
        if _old_who != who:
            _meta_set(f"assignnote:{member_id}", f"{_due}|{who}|{_chat}")

    m = get_member_by_id(member_id)
    if not isinstance(m, dict):
        m = None            # missing or an unexpected row shape: never crash on it
    already_told = bool(m and m.get("attribution_set"))
    # The message waits 24 hours rather than going straight out, so if the PU
    # side needs correcting, or you move them, they only ever hear once and
    # they hear the right thing.
    if m and m.get("chat_id") and not already_told:
        _meta_set(f"assignnote:{member_id}",
                  f"{(datetime.utcnow() + timedelta(hours=24)).isoformat()}|{who}|{m['chat_id']}")
    if False:
        send_telegram_message(int(m["chat_id"]),
            "You're all set \u2728\n\n"
            "Everything's active on your account, and you're looked after by "
            + (f"{who}." if mk else "the Inner Circle team.")
            + "\n\nIf you'd like the extra signals as well, head to "
            + f"{SITE}/signals and simply type "
            + (f"{who}" if mk else "Inner Circle")
            + " in the referred by box, so it lands in the right place.")
    return redirect(request.referrer or "/admin/marketers")


@app.route("/admin/member/<int:member_id>/ask-referral", methods=["POST"])
def admin_member_ask_referral(member_id):
    """Ask them on Telegram who sent them, before you approve."""
