@app.route("/admin/member/<int:member_id>/make-partner", methods=["POST"])
def admin_member_make_partner(member_id):
    """Turn an existing member into a partner: creates her hub, linked to this
    member account, so one login opens both sides."""
    if not session.get("admin"):
        return redirect(url_for("admin"))
    conn = get_db()
    row = None
    if conn:
        try:
            with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                cur.execute("SELECT id, name FROM members WHERE id=%s", (member_id,))
                row = cur.fetchone()
        finally:
            conn.close()
    if not row:
        return redirect("/admin")
    pw = (request.form.get("password") or "").strip()[:120] or secrets.token_urlsafe(6)
    try:
        rate = float((request.form.get("rate") or "0").replace("$", "").strip() or 0)
    except Exception:
        rate = 0
    name = (row.get("name") or f"Partner {member_id}").strip()[:80]
    add_marketer(name, aliases="", rate=rate, pu_link="",
                 is_kudo=bool(request.form.get("is_kudo")), password=pw)
    new_id = None
    conn = get_db()
    if conn:
        try:
            with conn, conn.cursor() as cur:
                cur.execute("SELECT id FROM marketers WHERE name=%s ORDER BY id DESC LIMIT 1", (name,))
                got = cur.fetchone()
                new_id = got[0] if got else None
                if new_id:
                    cur.execute("""UPDATE marketers SET member_id=%s, is_pu=%s WHERE id=%s""",
                                (member_id, bool(request.form.get("is_pu")), new_id))
        finally:
            conn.close()
    audit(member_id, "made a partner", f"partner hub created, password {pw}")
    notify_admin(f"\U0001F91D PARTNER SET UP\n\n{name}\nHub password: {pw}\n"
                 f"Linked to member #{member_id}, so one login opens both.\n\n"
                 f"Send her: {SITE}/partners")
    return redirect(f"/admin/marketers/{new_id}" if new_id else "/admin")


