@app.route("/admin/marketers/<int:mkid>/link", methods=["POST"])
def admin_marketer_link(mkid):
    """Connect a partner to her own member account, and set which sides she's
    on. Both boxes ticked means she sees Kudo and PU Prime everywhere."""
    if not session.get("admin"):
        return redirect(url_for("admin"))
    month = (request.args.get("month") or date.today().strftime("%Y-%m"))[:7]
    raw = (request.form.get("member_id") or "").strip()
    pu_link = (request.form.get("pu_link") or "").strip()[:300]
    if not request.form.get("is_pu"):
        pu_link = ""   # unticking PU clears the link with it
    conn = get_db()
    if conn:
        try:
            with conn, conn.cursor() as cur:
                sets = ["member_id=%s", "is_kudo=%s", "is_pu=%s", "pu_link=%s"]
                params = [int(raw) if raw.isdigit() else None,
                          bool(request.form.get("is_kudo")),
                          bool(request.form.get("is_pu")), pu_link]
                rate_raw = (request.form.get("rate") or "").replace("$", "").strip()
                if rate_raw:
                    try:
                        sets.append("rate=%s"); params.append(float(rate_raw))
                    except Exception:
                        pass
                # The password box lives in this panel too, so save it here as
                # well. Blank means leave the existing one alone.
                pw = (request.form.get("password") or "").strip()[:120]
                if pw:
                    sets.append("password=%s"); params.append(pw)
                cur.execute(f"UPDATE marketers SET {', '.join(sets)} WHERE id=%s",
                            (*params, mkid))
        finally:
            conn.close()
    return redirect(f"/admin/marketers/{mkid}?month={month}")


