def telegram_chat_name(chat_id):
    """
    Ask Telegram who a chat belongs to. Used for people who spoke to the bot
    before we started storing names, so the connect list never shows a bare
    number that means nothing to anyone.
    """
    if not TELEGRAM_API or not chat_id:
        return "", ""
    try:
        r = requests.post(f"{TELEGRAM_API}/getChat", json={"chat_id": int(chat_id)}, timeout=6)
        res = (r.json() or {}).get("result") or {}
        name = " ".join(x for x in (res.get("first_name"), res.get("last_name")) if x).strip()
        return name, (res.get("username") or "")
    except Exception:
        return "", ""


def recent_bot_contacts(limit=40):
    """
    Everyone who has spoken to the bot, with their name, their @username and
    the number they gave, so two people with the same first name can still be
    told apart. Built from three places so nobody is missing, and merged so
    nobody is listed twice.
    """
    conn = get_db()
    if not conn:
        return []
    by_chat = {}

    def note(chat_id, name="", username="", phone="", seen=None):
        if not chat_id or is_admin_chat(chat_id):
            return
        row = by_chat.setdefault(chat_id, {"chat_id": chat_id, "name": "", "username": "",
                                           "phone": "", "seen": None})
        if name and not row["name"]:
            row["name"] = name.strip()[:40]
        if username and not row["username"]:
            row["username"] = username.lstrip("@").strip()[:40]
        if phone and not row["phone"]:
            row["phone"] = phone
        if seen and (row["seen"] is None or seen > row["seen"]):
            row["seen"] = seen

    try:
        with conn.cursor() as cur:
            cur.execute("""SELECT username, chat_id, last_seen FROM bot_contacts
                           ORDER BY last_seen DESC LIMIT %s""", (limit * 2,))
            for username, chat_id, seen in cur.fetchall() or []:
                uname = (username or "")
                # older rows stored a display name here when there was no handle
                if " " in uname or "no username" in uname or uname.startswith("chat "):
                    note(chat_id, name=uname.replace("(no username)", "").strip(), seen=seen)
                else:
                    note(chat_id, username=uname, seen=seen)

            cur.execute("""SELECT DISTINCT ON (chat_id) chat_id, username, first_name,
                                  COALESCE(phone,''), created_at
                           FROM photo_submissions
                           WHERE chat_id IS NOT NULL
                           ORDER BY chat_id, created_at DESC LIMIT %s""", (limit * 2,))
            for chat_id, username, first_name, phone, created in cur.fetchall() or []:
                note(chat_id, name=first_name or "", username=username or "", phone=phone or "",
                     seen=created)

            cur.execute("""SELECT chat_id, COALESCE(who,''), COALESCE(phone,''), updated_at
                           FROM bot_state WHERE chat_id IS NOT NULL
                           ORDER BY updated_at DESC LIMIT %s""", (limit * 2,))
            for chat_id, who, phone, seen in cur.fetchall() or []:
                note(chat_id, name=who or "", phone=phone or "", seen=seen)
    except Exception:
        return []
    finally:
        conn.close()

    # Drop anyone already tied to an account. They are settled, so listing them
    # only makes it harder to find the person you are actually looking for.
    try:
        conn2 = get_db()
        if conn2:
            try:
                with conn2.cursor() as cur:
                    cur.execute("""SELECT chat_id FROM members
                                   WHERE chat_id IS NOT NULL AND merged_into IS NULL""")
                    for (taken,) in cur.fetchall() or []:
                        by_chat.pop(taken, None)
            finally:
                conn2.close()
    except Exception:
        pass

    # Anyone we have no name for: ask Telegram once, then keep it, so the list
    # is people rather than numbers. Capped so a long list stays quick.
    _nameless = [r for r in by_chat.values() if not r["name"] and not r["username"]][:8]
    if _nameless:
        for row in _nameless:
            nm, un = telegram_chat_name(row["chat_id"])
            if nm or un:
                row["name"] = nm or row["name"]
                row["username"] = un or row["username"]
                try:
                    _c4 = get_db()
                    if _c4:
                        try:
                            with _c4, _c4.cursor() as _cu4:
                                _cu4.execute("""INSERT INTO bot_state (chat_id, who)
                                                VALUES (%s,%s)
                                                ON CONFLICT (chat_id)
                                                DO UPDATE SET who=EXCLUDED.who""",
                                             (row["chat_id"], (nm or un)[:60]))
                        finally:
                            _c4.close()
                except Exception:
                    pass

    out = list(by_chat.values())
    for row in out:
        bits = [row["name"]] if row["name"] else []
        if row["username"]:
            bits.append(f"@{row['username']}")
        if not bits:
            bits.append(f"chat {row['chat_id']}")
        if row["phone"]:
            bits.append(pretty_phone(row["phone"]))
        row["label"] = " \u00b7 ".join(bits)
        row["username"] = row["username"] or row["name"]      # older callers
    out.sort(key=lambda c: (c.get("seen") is not None, c.get("seen")), reverse=True)
    return out[:limit]


@app.route("/admin/member/<int:member_id>/send-everything", methods=["POST"])
def admin_member_send_everything(member_id):
    """Send their code and every group link they have, right now."""
    if not session.get("admin"):
        return redirect(url_for("admin"))
    m = get_member_by_id(member_id)
    if not m or not m.get("chat_id"):
        return redirect(f"/admin/member/{member_id}?err=" + quote(
            "No Telegram connected, so there is nowhere to send it."))
    have = get_member_sections(member_id)
    if not have:
        return redirect(f"/admin/member/{member_id}?err=" + quote(
            "They have nothing unlocked yet, so there are no links to send."))
    summary = deliver_sections(member_id, set(have), note="sent again by admin")
    return redirect(f"/admin/member/{member_id}?ok=" + quote(f"Sent. {summary}"))


@app.route("/admin/member/<int:member_id>/connect-by-phone", methods=["POST"])
def admin_member_connect_by_phone(member_id):
    """
    Find this person's chat from the phone number on their account. Works
    whenever they have spoken to the bot and given it their number, which is
    everyone who has sent screenshots.
    """
    if not session.get("admin"):
        return redirect(url_for("admin"))
    m = get_member_by_id(member_id)
    found = find_chat_for_member(m) if m else None
    if not found:
        return redirect(f"/admin/member/{member_id}?err=" + quote(
            "No chat found on that number. They need to message the bot once, or send them their "
            "one tap connect link."))
    connect_member_chat(member_id, found["chat_id"], found.get("username") or "",
                        why="found by phone number from admin")
    return redirect(f"/admin/member/{member_id}?ok=" + quote(
        "Connected by phone number. Anything they were owed has been sent."))


@app.route("/admin/member/<int:member_id>/connect-telegram", methods=["POST"])
def admin_member_connect_telegram(member_id):
    """Connect a member to their own Telegram by hand, then send what they are
    owed straight away."""
    if not session.get("admin"):
        return redirect(url_for("admin"))
    try:
        chat_id = int(request.form.get("chat_id") or 0)
    except Exception:
        chat_id = 0
    username = (request.form.get("username") or "").strip()
    if not chat_id:
        return redirect(f"/admin/member/{member_id}?err=" + quote("Pick a Telegram first."))
    if is_admin_chat(chat_id):
        return redirect(f"/admin/member/{member_id}?err=" + quote(
            "That is admin's own Telegram. Their code would come to you, not to them."))
    connect_member_chat(member_id, chat_id, username, why="connected by admin")
    return redirect(f"/admin/member/{member_id}?ok=" + quote(
        "Connected. Anything they were owed has been sent to them now."))


@app.route("/admin/member/<int:member_id>/unlink-telegram", methods=["POST"])
def admin_member_unlink_telegram(member_id):
    """
    Take a Telegram off a member. Needed when the wrong chat got attached, for
    example when a number was typed into the admin chat while looking someone
    up. Their next message to the bot relinks them to their own chat.
    """
    if not session.get("admin"):
        return redirect(url_for("admin"))
    conn = get_db()
    if conn:
        try:
            with conn, conn.cursor() as cur:
                cur.execute("""UPDATE members SET chat_id=NULL, telegram_username='',
                               updated_at=NOW() WHERE id=%s""", (member_id,))
        finally:
            conn.close()
    audit(member_id, "Telegram unlinked", "by admin")
    return redirect(f"/admin/member/{member_id}?ok=" + quote(
        "Telegram unlinked. When they message the bot from their own phone it links to them, "
        "and anything they are owed sends automatically."))


@app.route("/admin/member/<int:member_id>/access", methods=["POST"])
def admin_member_access(member_id):
    if not session.get("admin"):
        return redirect(url_for("admin"))

    wanted = set(request.form.getlist("sections"))
    granted, revoked = set_member_sections(member_id, wanted, actor="admin")

    # Giving someone access should also give them the means to use it. If they
    # have no code yet, mint one and approve them, the way Mark Paid does,
    # so nobody is left with access they can't log in to reach.
    code_note = ""
    if granted and request.form.get("notify"):
        code_note = " " + deliver_sections(member_id, set(granted))

    if not granted and not revoked:
        return redirect(f"/admin/member/{member_id}?ok=Nothing+changed")

    if revoked and request.form.get("notify"):
        member = get_member_by_id(member_id)
        if member and member.get("chat_id"):
            send_telegram_message(
                member["chat_id"],
                "Your Inner Circle access has been updated.\n\nAccess removed for: "
                + ", ".join(SECTION_LABELS[s] for s in revoked))

    bits = []
    if granted:
        bits.append("added " + ", ".join(SECTION_LABELS[s] for s in granted))
    if revoked:
        bits.append("removed " + ", ".join(SECTION_LABELS[s] for s in revoked))
    return redirect(f"/admin/member/{member_id}?ok=" + quote("Access saved: " + "; ".join(bits) + code_note))


@app.route("/admin/member/<int:member_id>/update", methods=["POST"])
def admin_member_update(member_id):
    if not session.get("admin"):
        return redirect(url_for("admin"))

    raw_phone = request.form.get("phone", "").strip()
    if raw_phone and not normalize_phone(raw_phone):
        return redirect(f"/admin/member/{member_id}?err=" +
                        quote("That phone number doesn't look complete, so nothing was saved."))

    update_member_details(member_id, request.form.to_dict())
    return redirect(f"/admin/member/{member_id}?ok=" + quote("Details saved"))


@app.route("/admin/duplicates")
def admin_duplicates():
    if not session.get("admin"):
        return redirect(url_for("admin"))

    groups = find_all_duplicate_groups()
    leftover = 0
    conn = get_db()
    if conn:
        try:
            with conn.cursor() as cur:
                cur.execute("SELECT COUNT(*) FROM members WHERE merged_into IS NOT NULL")
                _lr = cur.fetchone()
                leftover = int(_lr[0]) if _lr else 0
        except Exception:
            leftover = 0
        finally:
            conn.close()

    cleanup = ""
    if leftover:
        cleanup = f"""
      <div class="adm-panel" style="border-color: var(--red);">
        <h3>Leftover merged records ({leftover})</h3>
        <p class="hint">Empty shells left behind by merging. Everything they held is already on the profiles they were folded into, so these can go.</p>
        <form method="POST" action="/admin/clear-merged"
              onsubmit="return confirm('Delete all {leftover} leftover records for good?');">
          <button type="submit" class="btn btn-danger">Delete all {leftover} leftover records</button>
        </form>
      </div>"""

    if not groups:
        body = cleanup + """
      <div class="adm-panel">
        <h3>All clear</h3>
        <p class="hint" style="margin: 0;">Every phone number on the books belongs to exactly one account.</p>
      </div>"""
    else:
        blocks = []
        for grp in groups:
            rows, options = [], []
            for i, m in enumerate(grp["members"]):
                sections = get_member_sections(m["id"])
                pills = "".join(f'<span class="pill on">{SECTION_LABELS[s]}</span>'
                                for s in SECTION_KEYS if s in sections) or '<span class="pill">no access yet</span>'
                rows.append(
                    f'<div class="dupe-row"><div class="grow">'
                    f'<a href="/admin/member/{m["id"]}" class="inline-link"><strong>#{m["id"]} {esc(m.get("name") or "unnamed")}</strong></a>'
                    f'<div class="adm-meta">{esc(m.get("tier") or "")} · {esc(m.get("status") or "")} · '
                    f'code {esc(m.get("access_code") or "none")} · created {fmt_date(m.get("created_at"))}</div>'
                    f'<div>{pills}</div></div>'
                    f'<label style="font-size:13px; display:flex; gap:7px; align-items:center;">'
                    f'<input type="checkbox" name="duplicate_ids" value="{m["id"]}" checked '
                    f'style="width:17px;height:17px;accent-color:var(--red);"> merge in</label>'
                    f'</div>'
                )
                options.append(
                    f'<option value="{m["id"]}" {"selected" if i == 0 else ""}>'
                    f'#{m["id"]} {esc(m.get("name") or "unnamed")} · {esc(m.get("status") or "")} · '
                    f'code {esc(m.get("access_code") or "none")}</option>'
                )
            blocks.append(f"""
      <div class="adm-panel">
        <h3>{esc(grp['phone'])}</h3>
        <p class="hint">{len(grp['members'])} accounts share this number.</p>
        <form method="POST" action="/admin/merge">
          {''.join(rows)}
          <div class="adm-edit" style="margin-top: 16px;">
            <label>Keep this profile</label>
            <select name="primary_id">{''.join(options)}</select>
          </div>
          <p class="hint" style="margin: 12px 0 0;">The profile you keep gets every unlocked section, the full message history, and its own access code. The others are hidden but kept, so this can be undone.</p>
          <button type="submit" style="margin-top: 12px;">Merge selected into kept profile</button>
        </form>
      </div>""")
        body = cleanup + "".join(blocks)

    if groups:
        total = sum(len(g["members"]) - 1 for g in groups)
        merge_all_button = f"""
    <div class="adm-panel" style="border-color: var(--gold);">
      <h3>Merge everything in one go</h3>
      <p class="hint">Folds all {len(groups)} groups at once, {total} duplicate record{'' if total == 1 else 's'} in total.
      Each person keeps their oldest approved record, with all access and messages combined. Reversible.</p>
      <form method="POST" action="/admin/merge-all"
            onsubmit="return confirm('Merge all {total} duplicate records now?');">
        <button type="submit">Merge all duplicates</button>
      </form>
    </div>"""
    else:
        merge_all_button = ""

    content = f"""
<section style="padding: 48px 0 70px;">
  <div class="wrap">
    <a href="/admin" class="inline-link" style="font-size: 13px;">← Back to members</a>
    <h1 style="font-size: 30px; margin: 16px 0 8px;">Duplicate accounts</h1>
    <p style="color: var(--ink-dim); margin-bottom: 20px;">Grouped by phone number, since that's what identifies a member.</p>
    {flash_banner()}
    {merge_all_button}
    {body}
  </div>
</section>
"""
    return render_template_string(admin_layout("Duplicates", content, "duplicates"))


@app.route("/admin/merge-all", methods=["POST"])
def admin_merge_all():
    """
    Fold every duplicate group in one go. Each group keeps its oldest approved
    record, or its oldest record if none are approved. Reversible, same as any
    other merge.
    """
    if not session.get("admin"):
        return redirect(url_for("admin"))

    groups = find_all_duplicate_groups()
    merged_people, merged_records = 0, 0
    for grp in groups:
        ids = [m["id"] for m in grp["members"]]
        if len(ids) < 2:
            continue
        primary, dups = ids[0], ids[1:]
        if merge_members(primary, dups, actor="merge all"):
            merged_people += 1
            merged_records += len(dups)

    if not merged_people:
        return redirect("/admin/duplicates?ok=" + quote("Nothing to merge."))
    return redirect("/admin/duplicates?ok=" +
                    quote(f"Merged {merged_records} duplicate record"
                          f"{'' if merged_records == 1 else 's'} across "
                          f"{merged_people} {'person' if merged_people == 1 else 'people'}."))


@app.route("/admin/merge", methods=["POST"])
def admin_merge():
    if not session.get("admin"):
        return redirect(url_for("admin"))

    try:
        primary_id = int(request.form.get("primary_id"))
    except (TypeError, ValueError):
        return redirect("/admin/duplicates?err=" + quote("Pick which profile to keep first."))

    dup_ids = [int(d) for d in request.form.getlist("duplicate_ids") if str(d).isdigit()]
    dup_ids = [d for d in dup_ids if d != primary_id]
    if not dup_ids:
        return redirect("/admin/duplicates?err=" + quote("Tick at least one account to merge in."))

    result = merge_members(primary_id, dup_ids, actor="admin")
    if not result:
        return redirect("/admin/duplicates?err=" + quote("That merge didn't go through. Refresh and try again."))

    n = len(dup_ids)
    return redirect(f"/admin/member/{primary_id}?ok=" +
                    quote(f"Merged {n} account{'' if n == 1 else 's'} in. Messages and access were combined."))


