def looks_like_question(text, max_words=8):
    """Whether a message reads as a question rather than an answer, so the
    onboarding questions never swallow 'how much is the course?' as a name."""
    t = (text or "").strip().lower()
    if not t:
        return False
    if "?" in t:
        return True
    if len(t.split()) > max_words:
        return True
    return t.startswith(("how ", "what ", "whats ", "what's ", "why ", "when ", "where ",
                         "can ", "could ", "do ", "does ", "is ", "are ", "will ",
                         "should ", "who ", "which "))


def detect_intent(text):
    """
    Work out what someone wants. Returns (best_intent, close_runner_up_or_None).

    Longer phrase matches beat shorter ones, so "i've paid the advanced" is read
    as a payment rather than as a question about the course. When two different
    intents match equally well the caller asks which was meant, because guessing
    wrong sends someone down the wrong path entirely.
    """
    t = (text or "").lower().strip()
    if not t:
        return None, None

    # "code" on its own means their login code, but not when it is somebody
    # asking about a discount or a promo code, which is a different question.
    if any(w in t for w in ("discount", "promo", "voucher", "coupon", "referral code")):
        t = t.replace("code", " ")

    scored = []
    for name, phrases in BOT_INTENTS:
        best = 0
        for p in phrases:
            if len(p) <= 4 and " " not in p:
                if re.search(rf"\b{re.escape(p)}\b", t):
                    best = max(best, len(p))
            elif p in t:
                best = max(best, len(p))
        if best:
            scored.append((best, name))

    if not scored:
        return None, None

    scored.sort(reverse=True)
    top_score, top_name = scored[0]
    for score, name in scored[1:]:
        # A clearly weaker match isn't a real rival, but a near-equal one is.
        if score >= top_score - 2 and name != top_name:
            return top_name, name
    return top_name, None


