def reject_pending_subs(chat_id):
    """Every waiting screenshot from this chat is marked rejected, clearing the way
    for a fresh set."""
    if not chat_id:
        return
    conn = get_db()
    if not conn:
        return
    try:
        with conn, conn.cursor() as cur:
            cur.execute("""UPDATE photo_submissions SET status='rejected', resolved_at=NOW()
                           WHERE chat_id=%s AND status='pending'""", (chat_id,))
    except Exception:
        pass
    finally:
        conn.close()


def ask_for_resend(chat_id, what="onboarding"):
    """Tell the member their screenshots need sending again, and put the bot back
    into collecting mode so the new ones flow straight through."""
    if not chat_id:
        return False
    reject_pending_subs(chat_id)
    if what == "payment":
        set_bot_state(chat_id, state="awaiting_payment_photo")
        return send_telegram_message(
            chat_id,
            "Quick one from our admin team: the payment screenshot you sent doesn't show what "
            "we need, so it couldn't be accepted.\n\n"
            "Please send it again, making sure the payment amount and confirmation are clearly "
            "visible in one screenshot.")
    set_bot_state(chat_id, state="awaiting_onboarding_photos", photo_count=0)
    return send_telegram_message(
        chat_id,
        "Quick one from our admin team: the screenshots you sent don't show what we need, so "
        "they couldn't be accepted. No problem, let's go again.\n\n" + PHOTO1_ASK)


def handle_admin_reply(message) -> bool:
    """
    Approving by replying to a Telegram alert. The admin replies "yes" to the
    alert about a member or a set of screenshots, and this does exactly what
    the matching button on the site does: same grants, same links sent, same
    audit trail. Anything it can't safely do from one word gets pointed back
    at the site instead of guessed at. Returns True when the message was an
    admin reply it dealt with, so the bot doesn't then treat it as onboarding.
    """
    chat_id = message.get("chat", {}).get("id")
    if not is_admin_chat(chat_id):
        return False
    replied = message.get("reply_to_message") or {}
    if not replied:
        return False
    raw = (message.get("text") or "").strip()
    word = raw.lower().rstrip("!.")
    approving = word in APPROVE_WORDS
    resending = word in RESEND_WORDS
    rejecting, reject_note = word in REJECT_WORDS, ""
    if not rejecting:
        # "no: wrong account number" or "reject - only 6 trades show" carries the
        # admin's own words into the decline. The separator right after the word
        # is required, so "no worries, ignore that" never fires a decline.
        import re as _re
        m_note = _re.match(r"^(\w+)\s*[:,\-]\s*(.+)$", raw, _re.S)
        if m_note and m_note.group(1).lower() in REJECT_WORDS:
            rejecting = True
            reject_note = m_note.group(2).strip()
    if not (approving or rejecting or resending):
        # Anything else typed as a reply to an alert about a person is a
        # message FOR that person. Replying "how can we help?" should reach
        # them, not bounce back at admin.
        body = raw
        m_pref = re.match(r"^(?:reply|send|say|msg|message)\s*[:,\-]\s*(.+)$", raw, re.S | re.I)
        if m_pref:
            body = m_pref.group(1).strip()
        body = body.strip().strip('"').strip()
        if not body:
            return False
        _ref_text = (replied.get("text") or replied.get("caption") or "")
        _mid = None
        _m_id = re.search(r"/admin/member/(\d+)", _ref_text)
        if _m_id:
            _mid = int(_m_id.group(1))
        if _mid is None:
            _m_acc = re.search(r"(?:Member ID|Account):?\s*#?(\d+)", _ref_text)
            if _m_acc:
                _mid = int(_m_acc.group(1))
        if _mid is None:
            return False
        _target = get_member_by_id(_mid)
        if not _target:
            return False
        if not _target.get("chat_id"):
            send_telegram_message(chat_id,
                f"{_target.get('name') or 'They'} has no Telegram connected, so that could not "
                f"be delivered.\n\nOpen them: {SITE}/admin/member/{_mid}")
            return True
        send_telegram_message(int(_target["chat_id"]), body)
        try:
            add_message(_mid, "admin", body)
        except Exception:
            pass
        send_telegram_message(chat_id,
                              f"Sent to {_target.get('name') or 'them'}.")
        return True

    def say(msg):
        send_telegram_message(chat_id, msg)

    found = take_tg_action(replied.get("message_id"))
    if not found:
        say("I can't tie that reply to anything still waiting. It may already be done, "
            "or it was an alert without an action. Reply yes to approve, no to decline, "
            "or resend to ask for the photos again, always on the alert itself. "
            f"The full picture is always here:\n{SITE}/admin")
        return True
    action, ref = found

    # ---- brand new onboarder, screenshots checked: send their verification code
    if action == "verify":
        sub = get_photo_submission(ref)
        if not sub or sub.get("status") != "pending":
            clear_tg_action(replied.get("message_id"))
            say("Already handled, nothing more to do on that one.")
            return True
        if resending:
            sent = ask_for_resend(sub.get("chat_id"), "onboarding")
            clear_tg_action(replied.get("message_id"))
            say("Asked them to send both screenshots again, and I'll walk them through it one "
                "photo at a time. You'll get a fresh alert when the new ones land."
                if sent else
                f"Couldn't message them, no Telegram chat on that one. Handle it on the site: {SITE}/admin/photos")
            return True
        if rejecting:
            resolve_photo_submission(ref, "rejected")
            clear_tg_action(replied.get("message_id"))
            target = sub.get("chat_id")
            if target:
                body = ("Hi, thanks for your onboarding submission. We couldn't approve it "
                        "as it stands.\n\n"
                        "Please double check your details and your two screenshots (your deposit "
                        "confirmation, and your MT5 History showing all 10 activation trades), "
                        "then resubmit.")
                if reject_note:
                    body += f"\n\nFrom our team: {reject_note}"
                body += ("\n\nOr just message us here and we'll walk you through onboarding, "
                         "no problem at all.")
                send_telegram_message(target, body)
                say("Declined, and I've told them to check their details and resubmit"
                    + (" with your note included." if reject_note else "."))
            else:
                say("Marked as not approved. No Telegram chat on that one, so nothing could be "
                    f"sent. Handle it on the site: {SITE}/admin/photos")
            return True
        target = sub.get("chat_id")
        if not target:
            say(f"No Telegram chat is attached to that one, so a code can't be sent from here. "
                f"Handle it on the site: {SITE}/admin/photos")
            return True
        code = gen_verification_code()
        save_verification_code(code, target, sub.get("username") or "", sub.get("photo_count") or 2)
        sent = send_telegram_message(
            target,
            "Great news, your screenshots have been checked and everything looks right!\n\n"
            "If you haven't filled in the short form yet, that's the last thing:\n"
            f"{SITE}/onboarding/activate\n\n"
            "Use the same phone number you gave me and it ties itself to you. Once you're approved "
            "I'll send your access code and your signals group link straight here.")
        resolve_photo_submission(ref, "approved")
        clear_tg_action(replied.get("message_id"))
        who = ("@" + sub["username"]) if sub.get("username") else (sub.get("first_name") or "them")
        say(f"Done. Verification code sent to {who}."
            if sent else
            f"Approved, but the code message to {who} didn't send. Resend from the site: {SITE}/admin/photos")
        return True

    # ---- a member who asked for something: grant it and send the links
    if action == "member":
        member = get_member_by_id(ref)
        if not member:
            clear_tg_action(replied.get("message_id"))
            say("That account has gone, possibly merged into another. Check on the site: "
                f"{SITE}/admin")
            return True
        if resending:
            sent = ask_for_resend(member.get("chat_id"), "onboarding")
            clear_tg_action(replied.get("message_id"))
            say(f"Asked {member.get('name') or 'them'} to send both screenshots again, one photo "
                "at a time. Their account and phone number stay linked, so the fresh ones tie "
                "straight back and you'll get a new alert when they land."
                if sent else
                f"Couldn't message them, no Telegram chat linked to that account yet. "
                f"Their profile: {SITE}/admin/member/{ref}")
            return True
        if rejecting:
            clear_tg_action(replied.get("message_id"))
            _sent, summary = decline_member(ref, reject_note)
            say(summary + (" Your note went with it." if reject_note else ""))
            return True
        granted_now = get_member_sections(ref)
        want = requested_sections(member, granted_now)
        if not want:
            clear_tg_action(replied.get("message_id"))
            say(f"{member.get('name') or 'They'} already have everything they've asked for.")
            return True
        set_member_sections(ref, granted_now | want, actor="telegram reply approve")
        conn = get_db()
        if conn:
            try:
                with conn, conn.cursor() as cur:
                    cur.execute("""UPDATE members SET status='approved', community_requested=FALSE,
                                   approved_at=COALESCE(approved_at, NOW()), updated_at=NOW()
                                   WHERE id=%s""", (ref,))
            finally:
                conn.close()
        summary = deliver_sections(ref, want)
        resolve_member_pending_photos(ref)
        clear_tg_action(replied.get("message_id"))
        labels = ", ".join(SECTION_LABELS[x] for x in SECTION_KEYS if x in want)
        say(f"Done. {member.get('name') or 'Member'}: {labels}. {summary}")
        return True

    # ---- an existing member's payment screenshot: unlock the advanced course
    if action == "sub":
        sub = get_photo_submission(ref)
        if not sub or sub.get("status") != "pending":
            clear_tg_action(replied.get("message_id"))
            say("Already handled, nothing more to do on that one.")
            return True
        if resending:
            sent = ask_for_resend(sub.get("chat_id"), "payment")
            clear_tg_action(replied.get("message_id"))
            say("Asked them to send the payment screenshot again. You'll get a fresh alert "
                "when it lands."
                if sent else
                f"Couldn't message them, no Telegram chat on that one. Handle it on the site: {SITE}/admin/photos")
            return True
        if rejecting:
            resolve_photo_submission(ref, "rejected")
            clear_tg_action(replied.get("message_id"))
            target = sub.get("chat_id")
            if target:
                body = ("Hi, about your Advanced course payment screenshot: we couldn't approve "
                        "it as it stands.")
                if reject_note:
                    body += f"\n\nFrom our team: {reject_note}"
                body += "\n\nIf you think that's wrong, just message us here and we'll sort it."
                send_telegram_message(target, body)
                say("Declined and they've been told" + (" with your note." if reject_note else "."))
            else:
                say("Marked as not approved. No Telegram chat on that one to message.")
            return True
        member_id = sub.get("member_id")
        if not member_id:
            say("That one isn't tied to an account yet, so it needs a pair of eyes on the site "
                f"to pick whose it is: {SITE}/admin/photos")
            return True
        want = {"advanced"} if sub.get("kind") == "payment" else {"signals_gold", "fundamentals"}
        granted_now = get_member_sections(member_id)
        set_member_sections(member_id, granted_now | want, actor="telegram reply approve")
        conn = get_db()
        if conn:
            try:
                with conn, conn.cursor() as cur:
                    cur.execute("""UPDATE members SET status='approved',
                                   approved_at=COALESCE(approved_at, NOW()), updated_at=NOW()
                                   WHERE id=%s""", (member_id,))
            finally:
                conn.close()
        summary = deliver_sections(member_id, want)
        resolve_photo_submission(ref, "approved")
        clear_tg_action(replied.get("message_id"))
        labels = ", ".join(SECTION_LABELS[x] for x in SECTION_KEYS if x in want)
        say(f"Done. Unlocked {labels}. {summary}")
        return True

    return False


@app.route("/webhook", methods=["POST"])
def telegram_webhook():
    update = request.get_json(silent=True) or {}
    message = update.get("message") or update.get("edited_message")
    if not message:
        return "ok"

    # Their answer to "who referred you", asked from the admin side.
    try:
        _rt = (message.get("text") or "").strip()
        _rc = message.get("chat", {}).get("id")
        if _rt and _rc and get_bot_state(_rc).get("state") == "awaiting_referral_answer":
            clear_bot_state(_rc)
            low = _rt.lower()
            nobody = any(w in low for w in ("no one", "noone", "nobody", "myself", "social",
                                            "instagram", "tiktok", "facebook", "found you",
                                            "no ", "none"))
            mk = marketer_match(_rt, get_marketers())
            name = mk["name"] if mk else ("Inner Circle" if nobody else _rt[:60])
            conn = get_db()
            if conn:
                try:
                    with conn, conn.cursor() as cur:
                        cur.execute("""UPDATE members SET referred_by=COALESCE(NULLIF(referred_by,''), %s),
                                       updated_at=NOW() WHERE chat_id=%s""", (name, _rc))
                finally:
                    conn.close()
            if mk:
                send_telegram_message(_rc, f"Lovely, thank you! I've put you down as referred by "
                                           f"{mk['name']}. \u2728 Your form will be checked shortly.")
            elif nobody:
                send_telegram_message(_rc, "No problem at all, thanks for letting us know. \u2728 "
                                           "Your form will be checked shortly.")
            else:
                send_telegram_message(_rc, "Thank you! I've passed that on. \u2728 Your form will "
                                           "be checked shortly.")
            notify_admin(f"\U0001F4DD REFERRAL ANSWER\n\n\"{_rt[:100]}\"\n\nRecorded as: {name}")
            return "ok"
    except Exception:
        pass

    # Partners saying "partner": a quick check that they really are one, then
    # support that already knows the answers.
    try:
        _pt = (message.get("text") or "").strip()
        _pl = _pt.lower()
        _pc = message.get("chat", {}).get("id")
        if _pc and not is_admin_chat(_pc) and _pl in ("partner", "partners", "partner hub",
                                                      "partner support", "i'm a partner",
                                                      "im a partner"):
            set_bot_state(_pc, state="awaiting_partner_name")
            send_telegram_message(_pc,
                "Lovely, let's get you sorted. \u2728 What name do you partner under? "
                "Just so I know I'm talking to the right person.")
            return "ok"

        if _pc and get_bot_state(_pc).get("state") == "awaiting_partner_name" and _pt:
            mk = marketer_match(_pt, get_marketers())
            if not mk:
                clear_bot_state(_pc)
                send_telegram_message(_pc,
                    "I can't find that name on our partner list, so I don't want to share "
                    "partner bits with the wrong person. If you are one of ours, message "
                    "admin and you'll be set up. If you're a member with a question, "
                    "just ask me here and I'll help. \U0001F90D")
                notify_admin(f"\U0001F50D Someone said partner but the name didn't match: "
                             f"\"{_pt[:60]}\". Chat {_pc}.")
                return "ok"
            set_bot_state(_pc, state="partner_support", partner=mk["name"])
            bits = ["Hi " + mk["name"] + "! \u2728 What can I help with?", "",
                    "1. My hub and where to log in",
                    "2. How my pay works",
                    "3. Onboarding someone step by step",
                    "4. The messages and voice note to send",
                    "5. Something else"]
            if is_pu_partner(mk):
                bits.insert(5, "6. My PU Prime link")
            send_telegram_message(_pc, "\n".join(bits) + "\n\nJust reply with a number.")
            return "ok"

        if _pc and get_bot_state(_pc).get("state") == "partner_support" and _pt:
            name = get_bot_state(_pc).get("partner") or ""
            mk = marketer_match(name, get_marketers()) or {}
            pick = _pl.strip(". ")
            if pick in ("1", "hub", "login"):
                msg = (f"Your hub lives at {SITE}/partners. Log in with your name and the "
                       f"password admin set for you. Inside: your clients this month, "
                       f"what you're owed, the leaderboard and all your training. No password "
                       f"yet? Message admin and one will be set.")
            elif pick in ("2", "pay"):
                msg = ("Kudo pay is one-off per client: they deposit £300 or more, do 10 "
                       "trades, get approved, and hold an ROI of 1.5 at month close. You're "
                       "paid at the end of the following month, between the 25th and the last "
                       "day. Bonuses stack by volume, from £5 a person at 5 clients up to £13 "
                       "each at 50. Full detail is in your training under Kudo.")
                if is_pu_partner(mk):
                    msg += ("\n\nPU Prime is different: recurring, paid per lot on every trade "
                            "your people place, for as long as they trade. Same rule though: "
                            "your people must say your name when they register for the extra "
                            "signals, or the trades don't come back to you.")
            elif pick in ("3", "onboarding", "onboard"):
                msg = ("Send them the link, then: they deposit £300 or more, do their 10 "
                       "trades, message me the word onboarding, send two screenshots, and "
                       "give me their number like this:\n\n07700 900123, referred by "
                       f"{name}\n\nThen the short form at {SITE}/onboarding/activate with "
                       f"the same number, and when it asks how they found us they put: "
                       f"referred by {name}. That mention is your pay, so put it in the same "
                       "message as the link.")
            elif pick in ("4", "messages", "message", "voice note", "script"):
                msg = (f"They're all in your hub: {SITE}/partners/training, under Getting "
                       "started. The word-for-word message for women, the version for men, "
                       "and the voice note script. Copy them exactly, then let the website do "
                       "the rest.")
            elif pick == "6" and is_pu_partner(mk):
                if (mk.get("pu_link") or "").strip():
                    msg = (f"Your PU Prime link: {mk['pu_link']}\n\nYour people use that link, "
                           f"then type: referred by {name} in the referred by box on the extra "
                           "signals form. Both steps, or the credit doesn't reach you.")
                else:
                    msg = ("Admin hasn't added your PU Prime link yet, message and "
                           "she'll pop it on. Meanwhile your people can type your name in the "
                           "Find my link box on the extra signals page.")
            else:
                clear_bot_state(_pc)
                notify_admin(f"\U0001F91D Partner question from {name}: \"{_pt[:150]}\"\n\n"
                             f"Chat {_pc}. Reply here to answer them.")
                send_telegram_message(_pc,
                    "I've passed that straight to admin and they'll come back to you here. "
                    "Anything else in the meantime, just say partner again. \U0001F90D")
                return "ok"
            clear_bot_state(_pc)
            send_telegram_message(_pc, msg + "\n\nAnything else? Say partner again any time.")
            return "ok"
    except Exception:
        pass

    # "Who do I click for PU Prime?" The bot works it out from who they
    # onboarded through and answers with the exact name, and the exact link.
    try:
        _t = (message.get("text") or "").strip().lower()
        _chat = message.get("chat", {}).get("id")
        PU_ASK_PHRASES = ("pu referral", "pu refferal", "who referred me pu", "pu referrer",
                          "who do i click", "which name do i click", "who do i pick",
                          "which name do i pick", "pu name", "whose link", "which link do i use")
        if _t and _chat and not is_admin_chat(_chat) and any(p in _t for p in PU_ASK_PHRASES):
            _uname = (message.get("from") or {}).get("username")
            member = member_for_chat(_chat, _uname)
            marketers = get_marketers()
            pmks = pu_marketers(marketers)
            charlotte_link = PU_CHARLOTTE_LINK or "the main button on innercircletrading.co/signals"
            if member:
                kudo = marketer_match(member.get("referred_by"), marketers)
                if kudo and (kudo.get("pu_link") or "").strip():
                    send_telegram_message(_chat,
                        f"You came to us through {kudo['name']}, so for PU Prime you're with "
                        f"{kudo['name']} too. \u2728\n\nUse this link to create your PU Prime "
                        f"account: {kudo['pu_link']}\n\nAnd when you fill in the extra signals "
                        f"form, type {kudo['name']} in the referred by box so everything matches.")
                    return "ok"
                if kudo:
                    send_telegram_message(_chat,
                        f"You came to us through {kudo['name']}, who handles the onboarding side "
                        f"only. So for PU Prime you're with us directly, Inner Circle. \u2728\n\n"
                        f"Use the main button on the extra signals page ({charlotte_link}) and "
                        f"leave the form's referred by box as Inner Circle.")
                    return "ok"
                # Onboarded with Charlotte or nothing recorded: someone with a PU
                # link may still have sent them here, so ask before assuming.
                if pmks:
                    names = ", ".join(mk["name"] for mk in pmks)
                    set_bot_state(_chat, state="awaiting_pu_ref_answer")
                    send_telegram_message(_chat,
                        "Happy to point you to the right place! Quick check first: did any of "
                        f"these send you here for the extra signals?\n\n{names}\n\n"
                        "Reply with their name if so, or just say no and I'll sort you out.")
                    return "ok"
                send_telegram_message(_chat,
                    f"You're with us directly, Inner Circle. \u2728 Use the main button on the extra signals "
                    f"page ({charlotte_link}) and leave the form's referred by box as Inner Circle.")
                return "ok"
            send_telegram_message(_chat,
                "Easy one: unless a specific person sent you here, you're with us directly, Inner Circle. Use "
                f"the main button on the extra signals page ({charlotte_link}) and leave the "
                "form's referred by box as Inner Circle. If someone specific did send you, use "
                "the link they gave you and type their name on the form.")
            return "ok"

        # Their answer to the did-anyone-send-you question above.
        if _t and _chat and not is_admin_chat(_chat) \
                and get_bot_state(_chat).get("state") == "awaiting_pu_ref_answer":
            clear_bot_state(_chat)
            marketers = get_marketers()
            pmks = pu_marketers(marketers)
            mk = marketer_match(message.get("text"), pmks)
            _uname = (message.get("from") or {}).get("username")
            member = member_for_chat(_chat, _uname)
            charlotte_link = PU_CHARLOTTE_LINK or "the main button on innercircletrading.co/signals"
            if mk:
                if member:
                    conn = get_db()
                    if conn:
                        try:
                            with conn, conn.cursor() as cur:
                                cur.execute("""UPDATE members SET pu_referred_by=%s, updated_at=NOW()
                                               WHERE id=%s""", (mk["name"], member["id"]))
                        finally:
                            conn.close()
                send_telegram_message(_chat,
                    f"Lovely, you're with {mk['name']} for PU Prime. \u2728\n\n"
                    f"Use this link to create your account: {mk['pu_link']}\n\n"
                    f"And type {mk['name']} in the referred by box on the extra signals form.")
                return "ok"
            negative = _t in ("no", "nope", "no one", "nobody", "none", "not sure", "unsure", "no.")
            if member:
                conn = get_db()
                if conn:
                    try:
                        with conn, conn.cursor() as cur:
                            cur.execute("""UPDATE members SET pu_referred_by='Inner Circle', updated_at=NOW()
                                           WHERE id=%s""", (member["id"],))
                    finally:
                        conn.close()
            if negative:
                send_telegram_message(_chat,
                    f"No problem at all, you're with us directly, Inner Circle. \u2728 Use the main button on "
                    f"the extra signals page ({charlotte_link}) and leave the form's referred by "
                    f"box as Inner Circle.")
            else:
                send_telegram_message(_chat,
                    "That's not a name I recognise from our PU partners, so I've put you with "
                    f"Inner Circle, which is always safe. Use the main button on the extra signals "
                    f"page ({charlotte_link}). If you think that's wrong, message us on the site "
                    "chat and a real person will sort it.")
                notify_admin(f"\U0001F50D Someone answered the PU referral check with a name I "
                             f"couldn't match: \"{(message.get('text') or '')[:80]}\"\n\n"
                             f"Chat: {_chat}. They've been put with Inner Circle for now.")
            return "ok"
    except Exception:
        pass

    # A member telling us, at any point, who actually referred them. "Lucy
    # referred me" or "referred by Lucy" switches their attribution there and
    # then, which is what keeps the marketer tally honest.
    try:
        _t = (message.get("text") or "").strip()
        _chat = message.get("chat", {}).get("id")
        if _t and _chat and not is_admin_chat(_chat) and "referred" in _t.lower() \
                and get_bot_state(_chat).get("state") not in (
                    "awaiting_onboard_phone", "awaiting_onboard_name",
                    "awaiting_onboard_referrer", "awaiting_onboarding_photos"):
            m_ref = (re.search(r"^@?([A-Za-z][\w'.\- ]{1,30}?)\s+referred\s+me\b", _t, re.I)
                     or re.search(r"referred\s+(?:by|through|from)\s+@?([A-Za-z][\w'.\- ]{1,30})\s*$", _t, re.I))
            if m_ref:
                _name = m_ref.group(1).strip().strip(".,!")
                conn = get_db()
                updated = False
                if conn:
                    try:
                        with conn, conn.cursor() as cur:
                            cur.execute("""UPDATE members SET referred_by=%s, updated_at=NOW()
                                           WHERE chat_id=%s AND merged_into IS NULL""", (_name, _chat))
                            updated = cur.rowcount > 0
                            if not updated:
                                cur.execute("""UPDATE photo_submissions SET referred_by=%s
                                               WHERE chat_id=%s AND status='pending'""", (_name, _chat))
                                updated = cur.rowcount > 0
                    finally:
                        conn.close()
                if updated:
                    send_telegram_message(_chat, f"Noted! You're down as referred by {_name}. \u2728")
                    notify_admin(f"\U0001F4CB Referrer updated by the member themselves: now {_name}.\n\n"
                                 f"Chat: {_chat}")
                    return "ok"
    except Exception:
        pass

    # Admin replying "yes" to an alert. Dealt with before anything else so the
    # bot never mistakes the admin's reply for a member onboarding.
    try:
        if handle_admin_reply(message):
            return "ok"
    except Exception:
        pass

    try:
        last = _meta_get("checkins_last_run")
        due = True
        if last:
            due = (datetime.utcnow() - datetime.fromisoformat(last)).total_seconds() > 3600
        if due:
            _meta_set("checkins_last_run", datetime.utcnow().isoformat())
            send_due_checkins()
            send_due_followups()
            send_due_assign_notes()
    except Exception:
        pass

    chat_id = message.get("chat", {}).get("id")
    username = message.get("from", {}).get("username")
    first_name = (message.get("from", {}).get("first_name") or "").strip()
    raw_text = (message.get("text") or "").strip()
    text = raw_text.lower()

    # One tap connect: /start connect-<token> ties this chat to that account and
    # sends them everything straight away. No verification code, no photos.
    if raw_text.startswith("/start ") and "connect-" in raw_text:
        _tok = raw_text.split("connect-", 1)[1].strip()
        _mid = member_id_from_token(_tok)
        _ch = message.get("chat", {}).get("id")
        if _mid and _ch and not is_admin_chat(_ch):
            _who = get_member_by_id(_mid)
            connect_member_chat(_mid, _ch, message.get("from", {}).get("username") or "",
                                why="one tap connect link")
            _have = get_member_sections(_mid)
            if _who and (_who.get("status") == "approved") and _have:
                deliver_sections(_mid, set(_have), note="connected by link")
            else:
                send_telegram_message(_ch,
                    "You're connected \u2728\n\nEverything lands right here the moment your "
                    "account is approved.")
            notify_admin(f"\U0001F517 {(_who or {}).get('name') or 'A member'} connected their "
                         f"Telegram with the one tap link.")
            return "ok"

    # "connect my account": anyone who already has an account and just needs
    # their Telegram tied to it. One question, then everything arrives.
    _ch0 = message.get("chat", {}).get("id")
    if _ch0 and not is_admin_chat(_ch0) and text in (
            "connect", "connect me", "connect my account", "link me", "link my account",
            "i already have an account", "i have an account", "already a member",
            "im already a member", "i'm already a member"):
        set_bot_state(_ch0, state="awaiting_connect_phone")
        send_telegram_message(_ch0,
            "Of course \u2728\n\nWhat's your phone number? The same one that's on your account, "
            "just the digits is perfect.\n\nI'll tie this chat to your account and send your "
            "login and your groups straight away.")
        return "ok"

    if (_ch0 and not is_admin_chat(_ch0) and raw_text
            and get_bot_state(_ch0).get("state") == "awaiting_connect_phone"):
        if not normalize_phone(raw_text):
            send_telegram_message(_ch0,
                "That doesn't look like a phone number. Just the digits is perfect, e.g. "
                "07123 456789.")
            return "ok"
        _hit = find_member_by_phone(raw_text)
        clear_bot_state(_ch0)
        if not _hit:
            send_telegram_message(_ch0,
                "I can't find an account on that number yet.\n\nIf you've just filled in the "
                "form, give it a minute and try again. If you haven't yet, say ONBOARDING and "
                "I'll walk you through it from the start.")
            notify_admin(f"\u2139\uFE0F Someone tried to connect with {raw_text} and no account "
                         f"matched. Chat {_ch0}.")
            return "ok"
        connect_member_chat(_hit["id"], _ch0,
                            message.get("from", {}).get("username") or "",
                            why="they asked to connect and gave their number")
        _fresh = get_member_by_id(_hit["id"]) or _hit
        _have = get_member_sections(_hit["id"])
        if _fresh.get("status") == "approved" and _have:
            deliver_sections(_hit["id"], set(_have), note="connected on request")
        elif _fresh.get("status") == "approved":
            send_telegram_message(_ch0,
                "You're connected \u2728\n\nYour account is approved. Say MY LOGIN any time and "
                "I'll send your code again.")
        else:
            send_telegram_message(_ch0,
                "You're connected \u2728\n\nYour account is still being checked. The moment it "
                "is approved, your login and your groups land right here.")
        notify_admin(f"\U0001F517 {_fresh.get('name') or 'A member'} connected their Telegram by "
                     f"phone number.")
        return "ok"
    caption = (message.get("caption") or "").lower().strip()
    photos = message.get("photo")
    # An empty or whitespace-only message still deserves an answer rather than
    # silence, otherwise it looks like we've ignored them.
    if (message.get("text") is not None and not raw_text and not photos
            and not message.get("document") and not message.get("sticker")
            and not message.get("voice")):
        _ch = message.get("chat", {}).get("id")
        _st = get_bot_state(_ch).get("state") if _ch else None
        if _ch:
            if _st == "awaiting_onboarding_photos":
                send_telegram_message(_ch, "Sorry, that came through empty. Whenever you're ready, "
                                           "send photo 1: your deposit confirmation.")
            elif _st == "awaiting_onboard_phone":
                send_telegram_message(_ch, "Sorry, that came through empty. I just need your phone "
                                           "number, just the digits is perfect.")
            elif _st == "awaiting_payment_photo":
                send_telegram_message(_ch, "Sorry, that came through empty. Send your Advanced "
                                           "payment screenshot whenever you're ready.")
            else:
                send_telegram_message(_ch, "Sorry, that came through empty! What can I help you "
                                           "with? Say menu to see everything I can do.")
        return "ok"
    photo_file_id = (photos[-1].get("file_id") if photos else None)
    msg_id = message.get("message_id")

    if chat_id:
        upsert_bot_contact(username, chat_id, first_name)
        # Remember what to call them, so the connect list is names not numbers.
        if first_name or username:
            try:
                _c2 = get_db()
                if _c2:
                    try:
                        with _c2, _c2.cursor() as _cu:
                            _cu.execute("""INSERT INTO bot_state (chat_id, who)
                                           VALUES (%s,%s)
                                           ON CONFLICT (chat_id) DO UPDATE SET who=EXCLUDED.who""",
                                        (chat_id, (first_name or username or "")[:60]))
                    finally:
                        _c2.close()
            except Exception:
                pass

    if not TELEGRAM_API:
        return "ok"

    def reply(msg):
        try:
            requests.post(f"{TELEGRAM_API}/sendMessage",
                          json={"chat_id": chat_id, "text": msg}, timeout=10)
        except Exception:
            pass

    # Telegram can send a contact card. That, or a typed number, is what lets
    # the bot recognise the same person again without a @username.
    contact = message.get("contact") or {}
    shared_phone = contact.get("phone_number")

    state_row = get_bot_state(chat_id)
    state = state_row.get("state")
    already_greeted = bool(state_row.get("greeted"))
    member = member_for_chat(chat_id, username)
    is_member = bool(member and member.get("status") == "approved"
                     and (member.get("access_code") or "").strip())
    # Worked out up front because the menu is built from it.
    granted = get_member_sections(member["id"]) if member else set()

    def link_by_phone(raw):
        """
        Tie this chat to the account on that number, so we know them next time.

        Never for the admin chat: typing a member's number in there is you
        looking someone up, not you being them. Linking it would send that
        member's code and links to you instead of to them.
        """
        found = find_member_by_phone(raw)
        if not found:
            return None
        if is_admin_chat(chat_id):
            return found
        conn = get_db()
        if conn:
            try:
                with conn, conn.cursor() as cur:
                    cur.execute("""UPDATE members SET chat_id=%s,
                                   telegram_username=COALESCE(NULLIF(telegram_username,''), %s),
                                   updated_at=NOW() WHERE id=%s""",
                                (chat_id, username, found["id"]))
            finally:
                conn.close()
        audit(found["id"], "Telegram linked", "matched by phone number in chat")
        # Anything they were approved for while we had no chat goes now.
        try:
            flush_owed(found["id"])
        except Exception:
            pass
        return get_member_by_id(found["id"])

    def contact_block():
        who = f"@{username}" if username else (first_name or "Unknown")
        lines = [f"From: {who}"]
        if member:
            lines.append(f"Account: #{member['id']} {member.get('name') or ''} "
                         f"{pretty_phone(member.get('phone'))}")
        else:
            lines.append("No account matched to this chat yet.")
        if username:
            lines.append(f"Reply: https://t.me/{username}")
        else:
            lines.append(f"No @username set. Chat ID: {chat_id}. Reply to their forwarded photo, "
                         f"or message them on the site at /admin/inbox.")
        return "\n".join(lines)

    # -----------------------------------------------------------------
    # Set pieces
    # -----------------------------------------------------------------
    def build_menu(intro):
        """
        The menu is built from what this person actually has. A brand new
        visitor has no use for "lost links", and a member doesn't need telling
        how to onboard, so neither of them sees the other's options.
        """
        lines = [intro, "", "Just message me any of these:", ""]

        if not is_member:
            lines += [
                "🚀  \"getting started\"  -  how it all works, from scratch",
                "📝  \"onboarding\"  -  the steps to get set up",
                "✅  \"activate\"  -  once you've done those steps",
                "📚  \"how to trade\"  -  our free beginners course",
                "📈  \"advanced\"  -  the £99 chart reading course",
                "👋  \"I have an account\"  -  already a member? I'll find you",
                "🚀  \"getting started\"  -  how it all works, from scratch",
                "📝  \"onboarding\"  -  the steps to get set up",
                "✅  \"activate\"  -  once you've done those steps",
                "📚  \"how to trade\"  -  our free beginners course",
                "📈  \"advanced\"  -  the £99 chart reading course",
                "👭  \"female wealth\"  -  our women only community",
                "",
                f"New here? Start at {SITE}/onboarding",
            ]
        else:
            g = granted
            lines.append("🔑  \"my login\"  -  your access code, sent straight back")
            if any(k in g for k in ("signals_gold", "signals_currency")):
                lines.append("🔗  \"my signals\"  -  every group link you have")
            if "fundamentals" in g:
                lines.append("📚  \"my course\"  -  your Trading Fundamentals lessons")
            if "advanced" in g:
                lines.append("📈  \"advanced\"  -  your Advanced Chart Reading lessons")
            else:
                lines.append("📈  \"unlock advanced\"  -  the £99 chart reading course")
            if "signals_currency" not in g:
                lines.append("➕  \"get more signals\"  -  add the extra signals groups")
            if "her" in g:
                lines.append("👭  \"female wealth\"  -  your women only community")
            else:
                lines.append("👭  \"female wealth\"  -  our women only community")
            lines.append("🎉  \"share results\"  -  send us how you're getting on")
            lines += [
                "",
                f"Your account: {SITE}/account",
                f"Your group links: {SITE}/my-signals",
            ]

        lines += [
            "",
            "Or just ask me a question in your own words. If I can't answer it, one of the "
            "team will, and they'll come back to you on the website.",
        ]
        return "\n".join(lines)

    WELCOME_MENU = build_menu("Hey, welcome to Inner Circle! 👋")

    ONBOARDING_STEPS = (
        "Great, let's get you set up. It's three steps and it's all done on the website.\n\n"
        "1️⃣ Go to https://innercircletrading.co/onboarding and follow the steps there.\n"
        "   You'll open your broker account, make your deposit, and place your 10 activation trades.\n\n"
        "2️⃣ Once you've done all three, come back here and message me the word:\n\n"
        "   activate\n\n"
        "3️⃣ I'll then tell you exactly which screenshots to send, and once they're checked "
        "you'll get your access code and your signals group.\n\n"
        "Take your time with step 1, and just message \"activate\" here when it's done."
    )

    ACTIVATE_STEPS = (
        "Perfect, last bit and you're in. I need two screenshots, one at a time.\n\n"
        "📸 First, please send photo 1: your deposit confirmation\n"
        "   Showing the money landed in your broker account.\n\n"
        "Once I've got that one, I'll ask you for photo 2: your MT5 History tab with "
        "all 10 activation trades visible together.\n\n"
        "Once both are in I'll ask three quick details, then you fill in the short form on the "
        "website. One review covers the lot, up to 24 hours but usually much "
        "quicker, and your access code and group link land straight here."
    )

    ADVANCED_STEPS = (
        "Advanced Chart Reading is our paid course, £99 one time and it's yours for good. "
        "23 lessons on reading charts yourself: candlestick patterns, market structure, support "
        "and resistance, liquidity, and building your own strategy.\n\n"
        "Here's how to get it:\n\n"
        "1️⃣ Pay here: https://innercircletrading.co/education/advanced\n\n"
        "2️⃣ Once you've paid, come back and message me:\n\n"
        "   paid\n\n"
        "3️⃣ I'll ask for a screenshot of your payment, then our admin team unlocks your access "
        "and I'll message you here the moment it's live."
    )

    def links_for_member():
        """Only the groups they actually have, never a link they can't use."""
        if not member:
            return None
        rows = [(n, u) for sec, n, _b, u in SIGNAL_GROUPS if sec in granted]
        if not rows:
            return None
        listed = "\n\n".join(f"{n}\n{u}" for n, u in rows)
        return (f"Here are all the groups you have access to:\n\n{listed}\n\n"
                f"They're always saved on your account too:\n"
                f"https://innercircletrading.co/my-signals")

    # -----------------------------------------------------------------
    # 1. Commands and greetings. The welcome only goes out here, never as
    #    a catch-all reply to something the bot didn't understand.
    # -----------------------------------------------------------------
    HELP_TRIGGERS = (
        "/start", "/menu", "/help", "/options", "menu", "options", "help", "help me",
        "what can you do", "what can you help with", "what can you help me with",
        "what do you do", "what can i ask", "what can i ask you", "how can you help",
        "how can you help me", "what are my options", "list", "commands", "start",
        "what else", "anything else", "i'm lost", "im lost", "lost", "confused",
        "not sure", "dont know", "don't know", "?", "??",
    )
    if text in HELP_TRIGGERS or text.rstrip("?!. ") in HELP_TRIGGERS:
        reply(WELCOME_MENU)
        set_bot_state(chat_id, greeted=True)
        return "ok"

    # Anything sent while we're waiting on a check-in reply becomes a
    # submission for review. Nothing reaches the site without approval.
    if state == "awaiting_checkin":
        if photos:
            ids = [p[-1].get("file_id") for p in [photos] if p] if isinstance(photos, list) else []
            file_ids = [photos[-1].get("file_id")] if isinstance(photos, list) and photos else []
            sid = add_submission(member.get("id") if member else None, chat_id,
                                 "result", raw_text or "", file_ids, source="bot")
            reply("Got it, thank you. That's gone to the team to look over.\n\n"
                  "If we'd like to use it we'll check with you first. Anything else I can help with?")
            notify_admin(f"📸 RESULTS SUBMITTED\n\n{contact_block()}\n\n"
                         f"Review it: {SITE}/admin/submissions")
            set_bot_state(chat_id, state=None)
            return "ok"
        if raw_text and len(raw_text.strip()) > 3:
            low = raw_text.strip().lower()
            if low in ("no", "no thanks", "no thank you", "nope", "not now", "nah"):
                reply("No problem at all, I won't ask again. I'm here if you need anything.")
                set_bot_state(chat_id, state=None)
                return "ok"
            sid = add_submission(member.get("id") if member else None, chat_id,
                                 "feedback", raw_text, source="bot")
            reply("Thank you, that's really useful.\n\n"
                  "If we'd like to put it on the website we'll ask you first. "
                  "Anything I can help you with while you're here?")
            notify_admin(f"💬 FEEDBACK SUBMITTED\n\n{contact_block()}\n\n"
                         f"\"{raw_text[:300]}\"\n\nReview it: {SITE}/admin/submissions")
            set_bot_state(chat_id, state=None)
            return "ok"

    GREETINGS = ("hi", "hey", "hello", "yo", "hiya", "heya", "good morning", "good afternoon",
                 "good evening", "hi there", "hey there", "hello there", "morning", "evening",
                 "hi!", "hey!", "hello!", "hiya!")
    # A greeting is a greeting however it is typed: "hiya!!", "hey hun",
    # "good morning :)". Exact matching missed nearly all of them.
    _bare = re.sub(r"[^a-z ]", " ", text)
    _bare = " ".join(_bare.split())
    _greet_words = {"hi", "hey", "hello", "yo", "hiya", "heya", "morning", "afternoon",
                    "evening", "howdy", "hallo", "helloo", "hii", "heyy", "sup"}
    _filler = {"there", "hun", "babe", "good", "you", "u", "ok", "okay", "all", "right",
               "guys", "team", "please", "just", "quick", "question", "again"}
    _is_greeting = bool(_bare) and all(w in _greet_words | _filler for w in _bare.split()) \
        and any(w in _greet_words for w in _bare.split()) and len(_bare.split()) <= 4

    if (text in GREETINGS or _is_greeting) and not photos:
        # A member gets greeted as a member. Telling someone who has been
        # trading with us for a month to "start onboarding" is the single most
        # annoying thing this bot could do.
        if is_member:
            who = (member.get("name") or "").split(" ")[0] or first_name
            reply(f"Welcome back{', ' + who if who else ''}.\n\n"
                  f"What can I help you with?\n\n"
                  f"🔑  \"my login\"  -  your access code\n"
                  f"🔗  \"my signals\"  -  every group link you have\n"
                  f"📚  \"my course\"  -  your lessons\n"
                  f"🎉  \"share results\"  -  send us how you're getting on\n\n"
                  f"Or just ask me anything.")
            set_bot_state(chat_id, greeted=True)
            return "ok"
        if already_greeted:
            name_bit = f" {first_name}" if first_name else ""
            reply(f"Hey{name_bit}, what can I help you with?")
        else:
            reply(WELCOME_MENU)
            set_bot_state(chat_id, greeted=True)
        return "ok"

    # -----------------------------------------------------------------
    # 0. Mid-conversation onboarding questions, asked once the screenshots
    #    are in. Name has to match the broker account, and knowing how people
    #    found us is worth asking while they're still talking to us.
    # -----------------------------------------------------------------
    # The old flow asked for name, then referrer, then phone. It's one question
    # now, and these two states only survive on sessions that were mid-flow when
    # that changed: move them straight to the phone question rather than making
    # anyone answer the retired ones.
    if state in ("awaiting_onboard_name", "awaiting_onboard_referrer"):
        set_bot_state(chat_id, state="awaiting_onboard_phone")
        state = "awaiting_onboard_phone"
        if raw_text and not photos:
            reply("Actually, I've got everything else I need. \U0001F90D\n\n"
                  "Just your phone number, the same one you'll put on the website form, so your "
                  "photos and form land on one account.\n\n"
                  "If someone referred you, add their name after it, like:\n"
                  "07700 900123, referred by Lucy")
            return "ok"

    if state == "awaiting_onboard_phone" and (raw_text or shared_phone) and not photos \
            and not (raw_text and looks_like_question(raw_text, max_words=10) and not shared_phone):
        given = shared_phone or raw_text.strip()
        if raw_text.strip().lower() in ("skip", "no", "later"):
            clear_bot_state(chat_id)
            reply("No problem. Fill in the form on the website whenever you're ready, and "
                  "our team will tie everything together by hand:\n"
                  f"{SITE}/onboarding/activate\n\n"
                  "Reviews take up to 24 hours but are usually much quicker, and your access "
                  "code and group link will land right here.")
            return "ok"
        # "07700 900123, Lucy": the number and, optionally, who sent them,
        # in one message instead of two separate questions.
        ref_after = ""
        m_split = re.match(r"^([\d\s()+.\-]{7,})[,;\s]+([A-Za-z@][\w@'.\- ]{1,40})$", given)
        if m_split:
            given, ref_after = m_split.group(1).strip(), m_split.group(2).strip()
            # "referred by Lucy", "ref by Lucy", "from Lucy" all mean Lucy
            ref_after = re.sub(r"^(referred\s+by|refered\s+by|ref\s+by|referral\s+from|sent\s+by|from)\s+",
                               "", ref_after, flags=re.I).strip()
        norm = normalize_phone(given)
        if not norm:
            reply("That doesn't look like a phone number. Just the digits is perfect, "
                  "e.g. 07123 456789. Or say skip and we'll match you by hand.")
            return "ok"
        stamp_submission_phone(chat_id, norm)
        if ref_after:
            conn = get_db()
            if conn:
                try:
                    with conn, conn.cursor() as cur:
                        cur.execute("""UPDATE photo_submissions SET referred_by=%s
                                       WHERE chat_id=%s AND status='pending'""", (ref_after, chat_id))
                        cur.execute("""UPDATE members SET referred_by=COALESCE(NULLIF(referred_by,''), %s),
                                       updated_at=NOW() WHERE chat_id=%s""", (ref_after, chat_id))
                finally:
                    conn.close()
        found = link_by_phone(given)
        clear_bot_state(chat_id)
        if found:
            # the website form is already in: everything's together, one approval left
            link_chat_subs_to_member(chat_id, found["id"])
            inherit_sub_referrer(found["id"], chat_id)
            if str(found.get("account_number") or "").strip():
                notify_admin_action(
                    f"🟢 ONBOARDING COMPLETE, ONE TAP\n\n{contact_block()}\n\n"
                    f"{found.get('name') or 'Member'} has now sent everything: form AND both "
                    f"screenshots, all tied to one account (#{found['id']}).\n"
                    f"Check the images above, then this one reply approves them, sends their "
                    f"code and their group link.",
                    "member", found["id"])
                reply("Perfect, that's you completely done, form and screenshots all in. "
                      "Our team gives it one final check, up to 24 hours but usually much "
                      "quicker, and your access code and group link land right here.")
            else:
                reply("Lovely, that's tied to your account. Last step is the short form on "
                      f"the website:\n{SITE}/onboarding/activate\n\n"
                      "Use this same phone number on it. Once it's in, our team approves "
                      "everything in one go, up to 24 hours but usually much quicker.")
        else:
            reply("Saved. Now the short form on the website:\n"
                  f"{SITE}/onboarding/activate\n\n"
                  "Use this same number on it and everything ties together on its own"
                  + (f", and when it asks how you found us, put: {ref_after}."
                     if ref_after else ", and it asks how you found us, so pop the name of "
                     "whoever sent you in that box.") + "\n\n"
                  "Once it's in, our team approves the lot in one go, up to 24 hours but "
                  "usually much quicker, and your access code and group link land right here.")
        return "ok"

    # -----------------------------------------------------------------
    # 1. Risk, money and boundaries. These come before everything else,
    #    because getting them wrong matters more than being helpful.
    # -----------------------------------------------------------------
    # Someone being abusive, or fishing for something the bot shouldn't touch.
    # Answer once, calmly, and point at a person. Never argue back.
    HOSTILE = ("stupid", "useless", "idiot", "shut up", "scam", "scammer", "fraud",
               "rip off", "ripoff", "thief", "liar", "fake", "hate you", "worthless")
    UNSAFE_ASK = ("guaranteed profit", "guarantee me", "double my money", "get rich quick",
                  "can't lose", "cant lose", "sure thing", "insider", "manipulate",
                  "launder", "tax free", "avoid tax", "hide money", "fake screenshot",
                  "fake results", "make me rich")

    if raw_text and any(w in text for w in UNSAFE_ASK):
        reply("I have to be straight with you on that one.\n\n"
              "There are no guaranteed profits in trading, and nobody can promise you'll double "
              "your money. Anyone who tells you otherwise isn't being honest with you.\n\n"
              "We never claim your results will be the same as anyone else's. All results vary. "
              "You trade your own account and keep full control of it, and every signal says so.\n\n"
              "What we actually offer is signals with the levels set out, free education so you "
              "understand them, and people to ask. Trading carries risk and you can lose money.\n\n"
              f"The free course is here: {SITE}/education/fundamentals")
        notify_admin(f"⚠️ WORTH A LOOK\n\n{contact_block()}\n\nThey asked:\n{raw_text}")
        return "ok"

    if raw_text and any(w in text for w in HOSTILE):
        # Answer the substance rather than deflecting. Someone calling it a scam
        # usually wants to know what is actually being claimed, so tell them.
        reply("Fair enough, let me be straight with you about what this is.\n\n"
              "We have never claimed your results will match anyone else's. All results vary, "
              "and they always will. You trade your own account, you keep full control of it, "
              "and every signal we send says exactly that.\n\n"
              "Trading carries risk and you can lose money. That's written on the website and "
              "I'll say it to you here too.\n\n"
              f"The education is free: {SITE}/education/fundamentals. It's free on purpose, so "
              "people trade sensibly instead of copying numbers they don't understand.\n\n"
              "Anything else you want to ask me?")
        notify_admin(f"⚠️ WORTH A LOOK\n\n{contact_block()}\n\nThey said:\n{raw_text}")
        return "ok"

    LOSS_WORDS = ("can i lose", "could i lose", "will i lose", "lose money", "lose my money",
                  "is it risky", "how risky", "is it safe", "guaranteed", "guarantee",
                  "am i guaranteed", "can i lose money", "risk of losing", "what if i lose")
    if any(w in text for w in LOSS_WORDS) and not photos:
        reply(
            "Yes. You can lose money, and you should assume you will lose on some trades.\n\n"
            "I'm not going to tell you otherwise. Nothing here is guaranteed, no signal is a "
            "prediction, and past results are not a guide to what happens next.\n\n"
            "What we do is teach you to manage it: small position sizes, a stop loss on every "
            "trade, and never risking money you need. Some of our members are up, some are "
            "down. That's the honest picture.\n\n"
            "Only ever trade with money you can genuinely afford to lose. If money is tight "
            "right now, this is not the moment to start.\n\n"
            "Nothing I say is financial advice. Your account is yours and every decision in it "
            "is yours."
        )
        return "ok"

    MONEY_WORDS = ("how much do i need", "how much money", "minimum deposit", "how much to start",
                   "what do i need to start", "minimum to join", "how much to join",
                   "starting amount", "what deposit", "how much deposit", "minimum")
    if any(w in text for w in MONEY_WORDS) and not photos:
        reply(
            "For the main gold signals, the minimum deposit is £300.\n\n"
            "The broker adds a 50% match on top, so £300 gives you around £450 to trade with. "
            "The match is the broker's, not ours.\n\n"
            "For extra signals there's no minimum and the match still applies, but we recommend "
            "at least £150 so you can size sensibly. Going in smaller than that makes proper "
            "risk management very hard.\n\n"
            "The money goes into your own broker account, not to us, and it stays yours the "
            "whole time. You control it and you can withdraw it.\n\n"
            "Only put in what you'd be genuinely comfortable losing. You can lose it, and this "
            "isn't financial advice.\n\n"
            f"The full steps are here: {SITE}/onboarding"
        )
        return "ok"

    # If someone is talking to the bot inappropriately, it does not play along.
    OUT_OF_BOUNDS = ("send nudes", "you're sexy", "youre sexy", "are you single", "kiss me",
                     "i love you baby", "sexy", "horny", "naked", "date me", "wanna hook up")
    if any(w in text for w in OUT_OF_BOUNDS) and not photos:
        reply("I'm the Inner Circle support bot, so let's keep it to trading.\n\n"
              "Anything I can help you with on the signals, the courses or your account?")
        return "ok"

    # Guaranteed-money and get-rich framing gets corrected, not encouraged.
    HYPE_WORDS = ("get rich quick", "make me rich", "double my money", "how much will i make",
                  "how much can i make", "quit my job", "become a millionaire", "easy money",
                  "free money")
    if any(w in text for w in HYPE_WORDS) and not photos:
        reply(
            "I can't tell you what you'll make, and I'd be wary of anyone who does.\n\n"
            "There's no guaranteed return here. Some weeks are good, some are not, and losing "
            "trades are part of it for everyone. Anyone promising you a number is selling "
            "something.\n\n"
            "What we can promise is that you'll be taught what you're doing rather than blindly "
            "copying, and that results get posted openly, wins and losses both.\n\n"
            "Please don't put in money you're relying on, and don't treat this as a way out of "
            "a tight spot. Nothing here is financial advice."
        )
        return "ok"

    # -----------------------------------------------------------------
    # 1a. "I already have an account". This used to fall through to the
    #     onboarding script, which is what happened on Jordan's test.
    # -----------------------------------------------------------------
    HAVE_ACCOUNT = ("i have an account", "i already have an account", "already have an account",
                    "i'm already a member", "im already a member", "already a member",
                    "i am a member", "i'm a member", "im a member", "i have account",
                    "already signed up", "i already signed up", "i'm signed up",
                    "i've onboarded", "ive onboarded", "already onboarded", "account")
    if any(w in text for w in HAVE_ACCOUNT) and not photos:
        if is_member:
            who = (member.get("name") or "").split(" ")[0] or first_name
            reply(f"You do{', ' + who if who else ''}, and I can see it here.\n\n"
                  f"Your access code: {member['access_code']}\n"
                  f"Log in: {SITE}/unlock\n\n"
                  f"All your group links: {SITE}/my-signals\n\n"
                  f"What did you need? Say \"my signals\" for your links, or just ask.")
            return "ok"
        reply("Let me find it. What phone number did you sign up with?\n\n"
              "Send it here and I'll pull your account up. If you'd rather not, message us on "
              f"the website at {SITE}/messages and we'll sort it.")
        set_bot_state(chat_id, state="awaiting_phone")
        return "ok"

    # -----------------------------------------------------------------
    # 1b. A phone number, shared or typed, links them to their account
    # -----------------------------------------------------------------
    typed_phone = None
    if raw_text and not photos:
        digits = "".join(ch for ch in raw_text if ch.isdigit())
        if len(digits) >= 9 and len(digits) <= 15 and len(digits) >= len(raw_text) - 5:
            typed_phone = raw_text

    # Plain English admin commands, said however you would say them out loud:
    # "send Pete his login code and signals", "approve Pete", "Pete?".
    # Only ever from the admin chat, and always about somebody else.
    if is_admin_chat(chat_id) and raw_text and not typed_phone and not shared_phone:
        _t = " ".join(re.sub(r"[^a-z0-9' ]", " ", text).split())
        _words = _t.split()
        _cmd = None

        # What is being asked for, spotted anywhere in the sentence.
        _wants_code = any(w in _words for w in ("login", "logins", "code", "access", "password"))
        _wants_links = any(w in _words for w in ("signal", "signals", "link", "links", "group",
                                                 "groups"))
        _is_approve = any(w in _words for w in ("approve", "approved", "accept", "accepted"))
        _is_connect = "connect" in _words or "reconnect" in _words
        _is_find = any(w in _words for w in ("find", "lookup", "who", "check", "status"))
        _has_send = any(w in _words for w in ("send", "resend", "give", "issue"))

        if _is_approve:
            _cmd = "approve"
        elif _is_connect:
            _cmd = "connect"
        elif "everything" in _words and _has_send:
            _cmd = "links"            # everything means code and links
        elif _wants_links and (_has_send or _wants_code):
            _cmd = "links"            # links carry the code too
        elif _wants_code and _has_send:
            _cmd = "login"
        elif _is_find:
            _cmd = "find"
        elif _t.endswith("?") or (raw_text.strip().endswith("?") and len(_words) <= 3):
            _cmd = "find"

        if _cmd:
            # The name is whatever is left once the instruction words are gone.
            STOP = {"send", "resend", "give", "issue", "please", "pls", "now", "to", "the", "a",
                    "his", "her", "their", "them", "him", "hers", "and", "with", "plus", "also",
                    "login", "logins", "code", "access", "password", "signal", "signals", "link",
                    "links", "group", "groups", "approve", "approved", "accept", "accepted",
                    "i", "ive", "have", "has", "connect", "connected", "reconnect", "find",
                    "lookup", "look", "up", "who", "is", "check", "status", "for", "everything",
                    "all", "of", "over", "out", "on"}
            _who = " ".join(w for w in _words if w not in STOP).strip()
            if not _who:
                reply("Who do you mean? Say it with their name, like \"send Pete his login\".")
                return "ok"

            _hits = members_by_name(_who)
            if not _hits:
                reply(f"I can't find anyone called \"{esc(_who)}\".\n\n"
                      f"Try part of the name as it is on their account, or open "
                      f"{SITE}/admin to search properly.")
                return "ok"
            if len(_hits) > 1:
                reply("More than one match:\n\n"
                      + "\n".join(f"#{m_['id']} {m_.get('name') or 'no name'} "
                                   f"{pretty_phone(m_.get('phone'))}" for m_ in _hits)
                      + "\n\nSay the command again with more of the name.")
                return "ok"
            _p = _hits[0]
            _pid = _p["id"]
            _have = get_member_sections(_pid)
            if _cmd == "find":
                _bits = ", ".join(SECTION_LABELS[k] for k in SECTION_KEYS if k in _have) or "nothing yet"
                reply(f"#{_pid} {_p.get('name') or 'no name'}\n"
                      f"{pretty_phone(_p.get('phone'))}\n"
                      f"Status: {_p.get('status') or 'pending'}\n"
                      f"Has: {_bits}\n"
                      f"Telegram: {'connected' if _p.get('chat_id') else 'not connected yet'}\n\n"
                      f"{SITE}/admin/member/{_pid}")
                return "ok"
            if _cmd == "connect" or not _p.get("chat_id"):
                reply(f"{_p.get('name') or 'They'} has no Telegram connected"
                      + (", so nothing can be sent yet." if _cmd != "connect" else ".")
                      + "\n\nSend them this and one tap does it:\n"
                      f"https://t.me/Innercircleverifybot?start=connect-{connect_token(_pid)}"
                      + (f"\n\nTheir code is {_p.get('access_code')} if you would rather send it "
                         f"by hand." if _p.get("access_code") else ""))
                return "ok"
            if _cmd == "approve":
                approve_member(_pid)
                _fresh = get_member_by_id(_pid) or _p
                _send = _have or {"signals_gold"}
                deliver_sections(_pid, set(_send), note="approved from the bot")
                reply(f"Done. {_fresh.get('name')} is approved and has been sent their code "
                      f"and their links.")
                return "ok"
            if _cmd == "login":
                _mm, _code, _sent = resend_access_code(_pid)
                reply(f"Sent. {_p.get('name')} has their code again."
                      if _sent else
                      f"Couldn't send it. Their code is {_code or 'not set'}.")
                return "ok"
            if _cmd == "links":
                if not _have:
                    reply(f"{_p.get('name')} has nothing unlocked yet, so there are no links to "
                          f"send. Open {SITE}/admin/member/{_pid} to give them access.")
                    return "ok"
                deliver_sections(_pid, set(_have), note="sent from the bot")
                reply(f"Sent. {_p.get('name')} has their links and their code.")
                return "ok"

    # A number given to the bot belongs to that chat, so the connect list can
    # show who is who by phone number rather than a bare chat id.
    if chat_id and (shared_phone or typed_phone) and not is_admin_chat(chat_id):
        try:
            _pn = normalize_phone(shared_phone or typed_phone)
            _c3 = get_db()
            if _c3 and _pn:
                try:
                    with _c3, _c3.cursor() as _cu3:
                        _cu3.execute("""INSERT INTO bot_state (chat_id, phone) VALUES (%s,%s)
                                        ON CONFLICT (chat_id) DO UPDATE SET phone=EXCLUDED.phone""",
                                     (chat_id, _pn))
                finally:
                    _c3.close()
        except Exception:
            pass

    if is_admin_chat(chat_id) and (shared_phone or typed_phone):
        # Admin looking someone up, not admin being them. Show who it is and
        # stop, so nothing gets linked or sent to the wrong chat.
        _look = find_member_by_phone(shared_phone or typed_phone)
        if _look:
            reply(f"That number is {_look.get('name') or 'an account'} "
                  f"(#{_look['id']}).\n\nOpen them: {SITE}/admin/member/{_look['id']}\n\n"
                  f"Nothing has been linked or sent, this is admin.")
        else:
            reply("No account on that number.\n\nNothing has been linked or sent, this is admin.")
        return "ok"

    if shared_phone or (typed_phone and (state == "awaiting_phone" or not member)):
        found = link_by_phone(shared_phone or typed_phone)
        if found:
            member = found
            is_member = bool(found.get("status") == "approved"
                             and (found.get("access_code") or "").strip())
            clear_bot_state(chat_id)
            granted_now = get_member_sections(found["id"])
            if is_member:
                lines = [f"Found you, thanks. You're {found.get('name') or 'all set'} on our system.",
                         "",
                         f"Your access code: {found['access_code']}",
                         f"Log in at {SITE}/unlock"]
                rows = [(n_, u) for sec, n_, _b, u in SIGNAL_GROUPS if sec in granted_now]
                if rows:
                    lines += ["", "And here are your group links:", ""]
                    lines += [f"{n_}\n{u}" for n_, u in rows]
                lines += ["", f"They're always saved at {SITE}/my-signals",
                          "", "Anything else I can help with?"]
                reply("\n".join(lines))
            else:
                reply(f"Found you, thanks. Your account is on our system but it hasn't been "
                      f"approved yet.\n\nAs soon as your screenshots are checked I'll message you "
                      f"here with your code and your group link. If you haven't sent them yet, "
                      f"message me \"activate\" and I'll talk you through it.")
            return "ok"
        if state == "awaiting_phone":
            clear_bot_state(chat_id)
            reply("I can't find an account on that number, sorry.\n\n"
                  "It might be worth double checking it, or if you signed up with a different "
                  f"number just tell me and I'll try again.\n\n"
                  f"If you'd rather speak to one of the team directly, message us on the website "
                  f"at {SITE}/messages and someone will pick it up.")
            return "ok"

    # -----------------------------------------------------------------
    # 1c. Closing off politely when they're done
    # -----------------------------------------------------------------
    NO_WORDS = ("no", "no thanks", "nope", "no thank you", "that's all", "thats all",
                "all good", "i'm good", "im good", "nothing else", "that's it", "thats it",
                "no im good", "no i'm good", "all sorted", "sorted")
    THANKS_WORDS = ("thanks", "thank you", "cheers", "ta", "thanx", "thankyou", "much appreciated",
                    "great thanks", "perfect thanks", "brilliant")
    stripped = text.rstrip("!. ")
    if stripped in NO_WORDS or stripped in THANKS_WORDS:
        tips_done = bool(state_row.get("tips_sent"))
        closing = "No problem at all. "
        if stripped in THANKS_WORDS:
            closing = "You're welcome. "
        if not tips_done:
            # The reminder of what I can do goes out once, not every time.
            closing += ("Any time you need me, I can sort your access code, your group links, "
                        "onboarding, the courses, or the community. Just say the word.\n\n"
                        "Have a good one.")
            set_bot_state(chat_id, tips_sent=True)
        else:
            closing += "Have a good one."
        clear_bot_state(chat_id)
        reply(closing)
        return "ok"

    # -----------------------------------------------------------------
    # 1d. Answering a "did you mean" question
    # -----------------------------------------------------------------
    pending = state_row.get("pending_intent")
    if pending and stripped in ("1", "2", "first", "second", "the first", "the second",
                                "yes", "yeah", "yep"):
        options = pending.split("|")
        pick = options[0] if stripped in ("1", "first", "the first", "yes", "yeah", "yep") else (
            options[1] if len(options) > 1 else options[0])
        set_bot_state(chat_id, pending_intent="")
        answer, new_state = bot_answer(pick, member, is_member, get_member_sections(member["id"]) if member else set())
        if new_state == "send_links":
            answer, new_state = (links_for_member() or
                                 f"I can't see any groups on your account yet. Once you're approved "
                                 f"they'll all be at {SITE}/my-signals"), None
        if answer:
            if new_state:
                set_bot_state(chat_id, state=new_state)
            reply(answer + "\n\nAnything else I can help with?")
            return "ok"

    # -----------------------------------------------------------------
    # 2. Where we're mid-conversation, that comes first
    # -----------------------------------------------------------------

    # They sent a photo but we don't know what it's for, and they've just told us.
    def claim_parked_photos(new_kind):
        """Relabel anything they sent before we knew what it was, then forward it."""
        conn = get_db()
        moved = 0
        if conn:
            try:
                with conn, conn.cursor() as cur:
                    cur.execute("""SELECT message_id FROM photo_submissions
                                   WHERE chat_id=%s AND kind='unknown' AND status='pending'""",
                                (chat_id,))
                    ids = [r[0] for r in cur.fetchall() if r[0]]
                    cur.execute("""UPDATE photo_submissions SET kind=%s
                                   WHERE chat_id=%s AND kind='unknown' AND status='pending'""",
                                (new_kind, chat_id))
                    moved = len(ids)
            except Exception:
                ids = []
            finally:
                conn.close()
            for mid_ in ids:
                forward_photo_to_admin(chat_id, mid_)
        return moved

    if state == "awaiting_photo_purpose" and not photos:
        if any(w in text for w in ("onboard", "verif", "activation", "deposit", "trades", "1", "one")):
            got = claim_parked_photos("onboarding")
            set_bot_state(chat_id, state="awaiting_onboarding_photos", photo_count=got)
            if got >= 2:
                clear_bot_state(chat_id)
                notify_admin_action(f"📸 ONBOARDING, READY TO REVIEW\n\n{contact_block()}\n\n"
                                    f"Tick to approve: {SITE}/admin/photos",
                                    "verify", latest_submission_id(chat_id, "onboarding"))
                set_bot_state(chat_id, state="awaiting_onboard_phone")
                reply("Perfect, that's both of them, thank you. They've gone to our admin team.\n\n"
                      "One last thing: your phone number, the same one you'll put on the "
                      "website form, so your photos and form land on one account.\n\n"
                      "Just the digits is perfect, e.g. 07700 900123")
            elif got == 1:
                notify_admin(f"📸 ONBOARDING 1 of 2, DEPOSIT CONFIRMATION\n\n{contact_block()}\n\n"
                             f"Waiting on their closed trades history.")
                reply("Lovely, I've logged that as your deposit confirmation.\n\n"
                      "\U0001F4F8 Now photo 2: your closed trades history.\n\n"
                      "In MT5: History tab, then screenshot the screen showing all 10 of your "
                      "activation trades together. All 10 need to be visible in the one "
                      "screenshot, and that's you done.")
            else:
                reply(ACTIVATE_STEPS)
            return "ok"
        if any(w in text for w in ("payment", "paid", "advanced", "course", "2", "two")):
            got = claim_parked_photos("payment")
            if got:
                clear_bot_state(chat_id)
                notify_admin_action(f"💷 ADVANCED COURSE PAYMENT\n\n{contact_block()}\n\n"
                                    f"Tick to approve: {SITE}/admin/photos",
                                    "sub", latest_submission_id(chat_id, "payment"))
                reply("Got it, thank you. That's gone to our admin team as your Advanced course "
                      "payment and they'll unlock your access, up to 24 hours but usually much quicker. "
                      "I'll message you here the moment it's live.")
            else:
                set_bot_state(chat_id, state="awaiting_payment_photo")
                reply("Got it, that's your Advanced course payment. Send the payment screenshot "
                      "over and I'll pass it straight to our admin team.")
            return "ok"
        if any(w in text for w in ("result", "share", "win", "profit", "3", "three")):
            got = claim_parked_photos("results")
            if got:
                clear_bot_state(chat_id)
                notify_admin(f"🎉 MEMBER RESULTS\n\n{contact_block()}")
                reply("Brilliant, thanks for sharing! Passed straight to the team.")
            else:
                set_bot_state(chat_id, state="awaiting_results_photos")
                reply("Lovely, send your results screenshots over and I'll pass them to the team.")
            return "ok"

    # -----------------------------------------------------------------
    # 3. Photos
    # -----------------------------------------------------------------
    payment_words = ["advanced paid", "paid advanced", "paid for advanced", "payment for advanced",
                     "advanced payment", "paid the advanced", "advanced course paid",
                     "paid for the advanced", "proof of payment", "payment proof",
                     "paid £99", "paid 99", "i've paid", "ive paid", "just paid"]
    results_words = ["share results", "my results", "share my results", "sharing results",
                     "here are my results", "results from", "my profit", "my wins"]

    if photos:
        is_payment_ctx = (state == "awaiting_payment_photo"
                          or any(w in caption for w in payment_words))
        is_results_ctx = (state == "awaiting_results_photos"
                          or any(w in caption for w in results_words))
        is_onboarding_ctx = (state == "awaiting_onboarding_photos"
                             or any(w in caption for w in ("deposit", "activation", "trades",
                                                           "onboarding", "verification")))

        if is_payment_ctx:
            clear_bot_state(chat_id)
            upsert_photo_submission(chat_id, username, first_name, "payment", 1, msg_id)
            add_photo_file_id(chat_id, "payment", photo_file_id)
            forward_photo_to_admin(chat_id, msg_id)
            notify_admin_action(f"💷 ADVANCED COURSE PAYMENT\n\n{contact_block()}\n\n"
                                f"Tick to approve: https://innercircletrading.co/admin/photos\n\nScreenshot below:",
                                "sub", latest_submission_id(chat_id, "payment"))
            reply("Thanks, got your payment screenshot and it's gone straight to our admin team.\n\n"
                  "They'll check it and unlock your Advanced Chart Reading access, usually well "
                  "within 24 hours. I'll message you here the moment it's live.")
            return "ok"

        if is_results_ctx:
            clear_bot_state(chat_id)
            forward_photo_to_admin(chat_id, msg_id)
            notify_admin(f"🎉 MEMBER RESULTS\n\n{contact_block()}\n\nScreenshot below:")
            reply("Brilliant, thanks for sharing! Passed straight to the team. "
                  "Always good to see how everyone's getting on.")
            return "ok"

        if is_onboarding_ctx:
            count = int(state_row.get("photo_count") or 0) + 1
            set_bot_state(chat_id, state="awaiting_onboarding_photos", photo_count=count)
            forward_photo_to_admin(chat_id, msg_id)
            upsert_photo_submission(chat_id, username, first_name, "onboarding", count, msg_id)
            add_photo_file_id(chat_id, "onboarding", photo_file_id)
            if count == 1:
                notify_admin(f"📸 ONBOARDING 1 of 2, DEPOSIT CONFIRMATION\n\n{contact_block()}\n\n"
                             f"Image below. Waiting on their closed trades history.")
                reply("Got your first screenshot, thank you.\n\n"
                      "\U0001F4F8 Now photo 2: your closed trades history.\n\n"
                      "In MT5: History tab, then screenshot the screen showing all 10 of your "
                      "activation trades together. All 10 need to be visible in the one "
                      "screenshot.")
            else:
                clear_bot_state(chat_id)
                notify_admin_action(
                    f"📸 ONBOARDING 2 of 2, CLOSED TRADES, READY TO REVIEW\n\n{contact_block()}\n\n"
                    f"Image below. Check the deposit confirmation and the 10 closed trades, then "
                    f"tick to approve: https://innercircletrading.co/admin/photos",
                    "verify", latest_submission_id(chat_id, "onboarding"))
                set_bot_state(chat_id, state="awaiting_onboard_phone")
                reply("Both screenshots received, thank you!\n\n"
                      "One last thing: your phone number, the same one you'll put on the "
                      "website form, so your photos and form land on one account.\n\n"
                      "Just the digits is perfect, e.g. 07700 900123")
            return "ok"

        # An extra photo while we're mid-questions: keep it with their onboarding
        # set and hold their place, rather than derailing into "what's this for?".
        if state in ("awaiting_onboard_name", "awaiting_onboard_referrer", "awaiting_onboard_phone"):
            upsert_photo_submission(chat_id, username, first_name, "onboarding", 2, msg_id)
            add_photo_file_id(chat_id, "onboarding", photo_file_id)
            forward_photo_to_admin(chat_id, msg_id, "Extra onboarding screenshot")
            ask_next = "your phone number, the same one you'll put on the website form"
            reply("Got that one too, I've kept it with your other screenshots.\n\n"
                  f"And I still just need {ask_next}.")
            return "ok"

        # A photo out of the blue. Ask what it's for before sending anything
        # on, otherwise the admin chat fills up with screenshots that turn out
        # to be nothing.
        set_bot_state(chat_id, state="awaiting_photo_purpose")
        # Parked as "unknown" in the database, so it survives a restart and can
        # be relabelled the moment they tell us what it is.
        upsert_photo_submission(chat_id, username, first_name, "unknown", 1, msg_id)
        add_photo_file_id(chat_id, "unknown", photo_file_id)
        reply("Thanks for that! Quick check so it goes to the right place, what's this screenshot for?\n\n"
              "1️⃣ Onboarding verification (your deposit and your 10 activation trades, 2 photos)\n"
              "2️⃣ Advanced course payment (1 photo)\n"
              "3️⃣ Results you're sharing with the community\n\n"
              "Just reply 1, 2 or 3 and I'll sort it.")
        return "ok"

    # -----------------------------------------------------------------
    # 4. Work out what they want, and say so if it's ambiguous
    # -----------------------------------------------------------------
    granted = get_member_sections(member["id"]) if member else set()
    intent, rival = detect_intent(raw_text)

    # Some intents are broad enough that matching one isn't the same as knowing
    # what someone needs. "something's wrong with my account" matches "my
    # account", but they could mean their code, their links, or their approval.
    # Ask, rather than answer confidently and send them the wrong way.
    BROAD = {"my_account": ("lost_code", "lost_links"),
             "signals_general": ("lost_links", "onboarding"),
             "community": ("community", "lost_links")}
    VAGUE = ("thing", "something", "stuff", "issue", "problem", "wrong", "not working",
             "doesnt work", "doesn't work", "isnt working", "isn't working", "wont work",
             "won't work", "help with", "sort out", "need the", "need my", "cant get",
             "can't get", "trouble", "broken", "stuck")
    if intent in BROAD and not rival and any(v in text for v in VAGUE):
        a, b = BROAD[intent]
        if a != b:
            intent, rival = a, b

    if intent and rival:
        # Two things match equally well. Ask rather than guess wrong.
        set_bot_state(chat_id, pending_intent=f"{intent}|{rival}")
        reply(f"Happy to help, just so I point you the right way, did you mean:\n\n"
              f"1. {INTENT_LABELS.get(intent, intent)}\n"
              f"2. {INTENT_LABELS.get(rival, rival)}\n\n"
              f"Reply 1 or 2 and I'll sort it.")
        return "ok"

    if intent:
        answer, new_state = bot_answer(intent, member, is_member, granted)

        if new_state == "send_links":
            links = links_for_member()
            new_state = None
            if links:
                answer = links
            elif member:
                answer = ("Your account isn't approved yet, so there aren't any group links on it "
                          "so far. The moment it is, I'll send them straight here.")
            else:
                answer = ("I can't match this chat to an account, so I can't tell which groups are "
                          "yours.\n\nSend me the phone number you signed up with and I'll find you "
                          "and send them over.")
                new_state = "awaiting_phone"

        if answer:
            # Mid-onboarding, a question gets its answer but never moves them off
            # their step: the place is held and gently re-asked underneath.
            HOLD_REMINDER = {
                "awaiting_onboarding_photos": "\n\nAnd when you're ready, I'm still waiting on "
                                              "your two proof screenshots, photo 1 first: your "
                                              "deposit confirmation.",
                "awaiting_onboard_phone": "\n\nAnd when you're ready, I still just need your "
                                          "phone number, the one you'll put on the website form.",
                "awaiting_payment_photo": "\n\nAnd when you're ready, I'm still waiting on your "
                                          "payment screenshot.",
            }
            if state in HOLD_REMINDER:
                reply(answer + HOLD_REMINDER[state])
                return "ok"
            if new_state:
                set_bot_state(chat_id, state=new_state)
            follow_up = "" if new_state else "\n\nAnything else I can help with?"
            reply(answer + follow_up)
            if intent == "lost_code" and is_member:
                audit(member["id"], "code resent by bot", "they asked for it on Telegram")
            return "ok"

    # -----------------------------------------------------------------
    # 5. Nothing matched. Older answers, then a real person.
    # -----------------------------------------------------------------
    if raw_text:
        answer, matched = keyword_reply(raw_text, chat_id=chat_id)
        if matched:
            # If they're mid-onboarding, answer them and put the step back in
            # front of them, so a question never quietly loses their place.
            hold = {
                "awaiting_onboarding_photos": "\n\nAnd when you're ready, I'm still waiting on your "
                                              "two proof screenshots, photo 1 first: your deposit "
                                              "confirmation.",
                "awaiting_onboard_phone": "\n\nAnd when you're ready, I still just need your phone "
                                          "number, the one you'll put on the website form.",
                "awaiting_payment_photo": "\n\nAnd when you're ready, I'm still waiting on your "
                                          "Advanced course payment screenshot.",
            }.get(state)
            reply(answer + (hold or "\n\nAnything else I can help with?"))
            return "ok"

        TRADING_WORDS = ["pip", "leverage", "stop loss", "take profit", "spread", "candlestick",
                         "support", "resistance", "risk", "chart", "indicator", "moving average",
                         "rsi", "fibonacci", "trend", "entry", "how do i trade", "how to trade",
                         "margin", "drawdown", "scalping", "swing", "analysis",
                         "buy or sell", "long or short"]
        if any(w in text for w in TRADING_WORDS):
            if "fundamentals" in granted:
                # They've paid their dues and have the course, so give them a
                # straight answer here rather than only a link.
                overview = next((v for k, v in FUNDAMENTALS_OVERVIEWS.items() if k in text), None)
                if overview:
                    reply(f"{overview}\n\n"
                          f"It's covered in more depth in your Trading Fundamentals course:\n"
                          f"{SITE}/education/fundamentals\n\n"
                          f"If you want it explained properly by one of the team, message us on "
                          f"the website at {SITE}/messages and someone will talk it through with "
                          f"you.\n\nAnything else I can help with?")
                else:
                    reply(f"That one's covered properly in your Trading Fundamentals course, and "
                          f"in more depth than I can manage in a message:\n\n"
                          f"{SITE}/education/fundamentals\n\n"
                          f"If it's still not clear after the lesson, message us on the website at "
                          f"{SITE}/messages and one of the team will explain it properly."
                          f"\n\nAnything else I can help with?")
            else:
                reply(f"Good question, and our free Trading Fundamentals course covers it properly. "
                      f"You get it as soon as you're onboarded.\n\n"
                      f"Message me \"onboarding\" and I'll walk you through getting set up, or have "
                      f"a look here: {SITE}/education/fundamentals\n\n"
                      f"Anything else I can help with?")
            return "ok"

        # Mid-onboarding, they've asked something rather than sent what was needed.
        # Never lose their place over it: answer with what's still needed and hold
        # the state exactly where it was.
        MID_ONBOARDING_NUDGE = {
            "awaiting_onboarding_photos": (
                "No problem. Where we're up to: " + ("I just need your two proof screenshots, "
                "one at a time.\n\n") + "\U0001F4F8 Photo 1 first: your deposit confirmation, "
                "showing the amount and that it completed.\n\n"
                "Send it whenever you're ready, or ask me anything else first."),
            "awaiting_onboard_phone": (
                "Sure. And when you're ready, I just need your phone number, the same one "
                "you'll put on the website form, so everything ties to one account. "
                "Or say skip and we'll match you by hand."),
            "awaiting_payment_photo": (
                "No problem. When you're ready, send your Advanced course payment screenshot "
                "showing the amount and confirmation, and I'll pass it straight to the team."),
        }
        if state in MID_ONBOARDING_NUDGE:
            reply(MID_ONBOARDING_NUDGE[state])
            return "ok"

        # Genuinely stuck. Offer the list once, then hand to a real person.
        if state == "offered_help":
            clear_bot_state(chat_id)
            reply(f"I'm still not getting it, sorry, and I'd rather not send you round in circles.\n\n"
                  f"Message us on the website and one of the team will pick it up and answer you "
                  f"properly:\n\n{SITE}/messages\n\n"
                  f"They can see your account, so they'll be able to sort whatever it is.")
            notify_admin(f"❓ BOT COULDN'T HELP, SENT THEM TO THE SITE\n\n{contact_block()}\n\n"
                         f"Their message:\n{raw_text}\n\nReply here: {SITE}/admin/inbox")
            return "ok"

        set_bot_state(chat_id, state="offered_help")
        reply(build_menu("I'm not quite sure what you're after there, sorry.") +
              "\n\nIf none of those are it, tell me again in your own words and I'll get one of "
              "the team on it.")
        notify_admin(f"❓ UNANSWERED MESSAGE\n\n{contact_block()}\n\nTheir message:\n{raw_text}\n\n"
                     f"Reply here: {SITE}/admin/inbox")

    return "ok"


