@app.route("/account/hide-extra-note", methods=["POST"])
def hide_extra_note():
    """They have said not right now, so it does not come back."""
    mid = session.get("member_id")
    if mid:
        try:
            _meta_set(f"extra_note_hidden:{mid}", datetime.utcnow().isoformat())
        except Exception:
            pass
    return redirect("/account")


@app.route("/account/risk-agree", methods=["POST"])
def account_risk_agree():
    """
    Records that a member has read and accepted the risk statement. Shown once,
    on their own account page, after they are in. Not on the open website.
    """
    mid = session.get("member_id")
    if not mid:
        return redirect(url_for("unlock"))
    conn = get_db()
    if conn:
        try:
            with conn, conn.cursor() as cur:
                cur.execute("UPDATE members SET risk_agreed_at=NOW() WHERE id=%s", (mid,))
        except Exception:
            pass
        finally:
            conn.close()
    audit(mid, "risk statement accepted", "on their account page")
    return redirect("/account")


@app.route("/account")
def account():
    if session.get("admin") and not session.get("member_id"):
        # Admin has no member account of their own, so send them somewhere useful
        # rather than showing an empty one.
        return redirect(url_for("admin"))
    if not is_verified():
        return redirect(url_for("unlock"))

    name = session.get("member_name", "")
    granted = current_sections()
    me = get_member_by_id(session.get("member_id")) or {}
    access_code = me.get("access_code") or ""

    # Shown once, here, after they are a member. Never on the open website.
    risk_gate = "" if me.get("risk_agreed_at") else RISK_AGREEMENT_HTML

    # A week in, once, let them know the extra signals exist. Only if they are
    # actually open, only for gold members who have not already taken them, and
    # it goes away the moment they say so.
    extra_note = ""
    try:
        approved_at = me.get("approved_at")
        week_in = bool(approved_at and (datetime.utcnow() - approved_at).days >= 7) \
            if hasattr(approved_at, "year") else False
        already = bool((me.get("currency_account_number") or "").strip())
        # Saying no puts it away for two months, not for ever. People change
        # their minds, and being asked twice a year is not nagging.
        dismissed = False
        hidden_at = _meta_get(f"extra_note_hidden:{me.get('id')}")
        if hidden_at:
            try:
                when = datetime.fromisoformat(str(hidden_at)[:19])
                dismissed = (datetime.utcnow() - when).days < 60
            except Exception:
                dismissed = True
        if (pu_signals_open() and week_in and not already and not dismissed
                and "signals_gold" in granted):
            extra_note = """
    <div class="callout" style="margin: 0 0 26px; border-color: var(--gold);">
      <span class="eyebrow">Ready for more</span>
      <h3 style="font-size: 19px; margin: 8px 0 8px;">Extra signals</h3>
      <p style="color: var(--ink-dim); font-size: 14.5px; line-height: 1.8; margin: 0 0 14px;">
        You have been with us a week, so here is what comes next. Extra signals gives you more
        groups, more pairs and different sessions through the day, from quick moves to longer
        ones. More chances to trade, the same way you already know. Your first deposit is
        matched 100% in credit.</p>
      <div class="cta-row" style="gap: 10px;">
        <a href="/signals" class="btn btn-primary btn-sm">See the extra signals</a>
        <form method="POST" action="/account/hide-extra-note" style="margin:0;">
          <button type="submit" class="btn btn-ghost btn-sm">Not for me right now</button>
        </form>
      </div>
    </div>"""
    except Exception:
        extra_note = ""
    # And a permanent copy they can open whenever they like, showing the date
    # they agreed. Same words they ticked, nothing rewritten.
    risk_record = ""
    if me.get("risk_agreed_at"):
        risk_record = (
            '<details style="margin-top:26px; border:1px solid var(--line); border-radius:12px; '
            'padding:14px 16px;">'
            '<summary style="cursor:pointer; font-size:14px; color:var(--ink-dim);">'
            'Your disclaimer, agreed ' + esc(fmt_date(me.get("risk_agreed_at"))) + '</summary>'
            + RISK_STATEMENT_TEXT +
            '<p style="color:var(--ink-dim); font-size:12.5px; margin:14px 0 0;">You agreed to '
            'this on ' + esc(fmt_datetime(me.get("risk_agreed_at"))) + '. It is kept on your '
            'account so you can read it back any time.</p>'
            '</details>')

    # key -> (unlocked blurb, open link, locked blurb, locked link)
    ROWS = {
        "signals_gold":     ("Approved and active", None,
                             "Not on the gold signals", None),
        "signals_currency": ("Approved and active", ("View Extra Signals", "/signals"),
                             "More groups, more pairs, more chances to trade", ("View Extra Signals", "/signals")),
        "fundamentals":     ("Free course, 41 lessons", ("Open course", "/education/fundamentals/0"),
                             "Not unlocked yet", None),
        "advanced":         ("Unlocked, 23 lessons", ("Open course", "/education/advanced/0"),
                             "£99 one-time, not yet unlocked", ("Unlock it", "/education/advanced/0")),
        "her":              ("Unlocked, masterclasses, mindset lessons and your group link", ("Open Female Wealth", "/her"),
                             "Women-only space, request access", ("Request to join", "/community")),
    }

    rows = []
    for key, label, _ in SECTIONS:
        on_blurb, on_link, off_blurb, off_link = ROWS[key]
        unlocked = key in granted
        blurb, link = (on_blurb, on_link) if unlocked else (off_blurb, off_link)
        colour = "var(--rose)" if (unlocked and key == "her") else "var(--green)"
        head = (f'<strong style="color: {colour};">✓ {label}</strong>' if unlocked
                else f'<span style="color: var(--ink-dim);">🔒 {label}</span>')
        cta = (f'<br><a href="{link[1]}" class="inline-link" style="font-size: 13px;">{link[0]} →</a>'
               if link else "")
        rows.append(
            f'<li style="padding: 14px 0; border-bottom: 1px solid var(--line);">{head}'
            f'<br><span style="color: var(--ink-dim); font-size: 13px;">{blurb}</span>{cta}</li>'
        )
    rows_html = "".join(rows)

    content = f"""
<section style="padding: 70px 0;">
  <div class="wrap" style="max-width: 560px;">
{risk_gate}
    {extra_note}
    <span class="eyebrow">Your account</span>
    <h1 style="font-size: 30px; margin: 10px 0 8px;">Hi{', ' + esc(name) if name else ''}</h1>
    <p style="color: var(--ink-dim); margin-bottom: 36px;">Here's what you've got access to.</p>

    <div class="form-panel">
      <ul style="list-style: none; padding: 0; margin: 0;">
        {rows_html}
      </ul>
    </div>

    <a href="/my-signals" class="btn btn-primary" style="margin-top: 22px; width: 100%; text-align: center;">
      All your signals and group links
    </a>

    <div style="display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-top:30px;">
      <div class="form-panel" style="max-width:100%; text-align:center;">
        <h3 style="font-size:17px; margin:0 0 8px;">Share your results</h3>
        <p style="color:var(--ink-dim); font-size:14px;">Message "share results" to our bot and send your screenshots. Wins, lessons, progress, all welcome.</p>
        <a href="https://t.me/Innercircleverifybot" target="_blank" rel="noopener" class="inline-link" style="font-size:13px;">Share now →</a>
      </div>
      <div class="form-panel" style="max-width:100%; text-align:center;">
        <h3 style="font-size:17px; margin:0 0 8px;">Need support?</h3>
        <p style="color:var(--ink-dim); font-size:14px;">Message us privately any time. No question is too small, genuinely.</p>
        <a href="/messages" class="inline-link" style="font-size:13px;">Message us →</a>
      </div>
    </div>

    <div class="callout" style="margin-top: 26px;">
      <strong>Your access code is {esc(access_code) if access_code else 'on your account'}</strong>
      <br><span style="font-size:13.5px;">We'll keep you signed in on this device. Lost it anyway? Ask our bot to resend it, or
      <a href="/messages" class="inline-link">message us here</a>.</span>
    </div>

    <p style="color: var(--ink-dim); font-size: 13px; margin-top: 28px;">
      Need help? <a href="/messages" class="inline-link">Message us here</a>, or on
      <a href="https://t.me/Innercircleverifybot" target="_blank" rel="noopener" class="inline-link">Telegram</a>,
      where you can say <strong>help</strong> to see everything our bot can sort out, or
      <strong>lost links</strong> to get your groups sent back to you.
      <br><a href="/logout" class="inline-link">Log out</a>
    </p>
    {risk_record}
  </div>
</section>
"""
    return render_template_string(base_layout("My Account", content, ""))


@app.route("/messages", methods=["GET", "POST"])
def member_messages():
    if not is_verified():
        return redirect(url_for("unlock"))

    member_id = session.get("member_id")

    if request.method == "POST":
        body = request.form.get("body", "").strip()
        if body:
            add_message(member_id, "member", body)
            notify_admin(
                f"💬 NEW MESSAGE FROM MEMBER\n\n"
                f"{session.get('member_name','Member')} (ID {member_id})\n\n"
                f"{body}\n\n"
                f"Reply at https://innercircletrading.co/admin/messages/{member_id}"
            )
        return redirect(url_for("member_messages"))

    msgs = get_messages(member_id)
    if msgs:
        thread = "".join(
            f'<div style="margin-bottom: 18px; text-align: {"right" if m["sender"]=="member" else "left"};">'
            f'<div style="display: inline-block; max-width: 80%; text-align: left; padding: 12px 16px; border-radius: 14px; '
            f'background: {"var(--bg-alt-2)" if m["sender"]=="member" else "var(--gold)"}; '
            f'color: {"var(--ink)" if m["sender"]=="member" else "var(--bg)"};">'
            f'<div style="font-size: 11px; opacity: 0.7; margin-bottom: 4px;">{"You" if m["sender"]=="member" else "Inner Circle"}</div>'
            f'{m["body"]}</div></div>'
            for m in msgs
        )
    else:
        thread = '<p style="color: var(--ink-dim); text-align: center; padding: 30px 0;">No messages yet. Send us anything you need below.</p>'

    content = f"""
<section style="padding: 60px 0;">
  <div class="wrap" style="max-width: 620px;">
    <a href="/account" class="inline-link" style="font-size: 13px;">← Back to my account</a>
    <h1 style="font-size: 28px; margin: 16px 0 8px;">Messages</h1>
    <p style="color: var(--ink-dim); margin-bottom: 30px;">Message us directly here, we'll reply as soon as we can.</p>
    <div class="form-panel" style="max-width: 100%; margin-bottom: 22px;">{thread}</div>
    <div class="form-panel" style="max-width: 100%;">
      <form method="POST">
        <label>Your message</label>
        <input type="text" name="body" placeholder="Type your message..." required>
        <button type="submit">Send</button>
      </form>
    </div>
  </div>
</section>
"""
    return render_template_string(base_layout("Messages", content, ""))


@app.route("/my-signals")
def my_signals():
    """
    Every Telegram group this member has access to, in one place, so a lost
    link is never a problem. Groups they haven't unlocked show as locked with
    a route to unlocking them, rather than being hidden.
    """
    if not is_verified():
        return redirect(url_for("unlock"))

    granted = current_sections()

    unlocked, locked = [], []
    for section, name, blurb, url in SIGNAL_GROUPS:
        if section in granted:
            unlocked.append(
                f'<div class="benefit" style="text-align:left; border-color:var(--green);">'
                f'<strong style="font-size:16px;">{name}</strong>'
                f'<p style="color:var(--ink-dim); font-size:14px; margin:6px 0 12px;">{blurb}</p>'
                f'<a href="{url}" target="_blank" rel="noopener" class="btn btn-primary" '
                f'style="padding:9px 20px; font-size:13px;">Open in Telegram</a></div>'
            )
        else:
            if section == "signals_currency":
                cta, cta_url = "Unlock more signals", "/signals"
            elif section == "her":
                cta, cta_url = "Request access", "/community"
            else:
                cta, cta_url = "Start onboarding", "/onboarding"
            locked.append(
                f'<div class="benefit" style="text-align:left; opacity:0.72;">'
                f'<strong style="font-size:16px; color:var(--ink-dim);">🔒 {name}</strong>'
                f'<p style="color:var(--ink-dim); font-size:14px; margin:6px 0 12px;">{blurb}</p>'
                f'<a href="{cta_url}" class="inline-link" style="font-size:13px;">{cta} →</a></div>'
            )

    unlocked_html = "".join(unlocked) or (
        '<p style="color:var(--ink-dim);">Nothing unlocked yet. Once your onboarding is approved '
        'your groups appear here.</p>')
    locked_html = (
        f'<h2 style="font-size:20px; margin:44px 0 16px;">Not unlocked yet</h2>'
        f'<div class="grid5" style="grid-template-columns:1fr;">{"".join(locked)}</div>'
        if locked else "")

    content = f"""
<section style="padding: 60px 0;">
  <div class="wrap" style="max-width: 760px;">
    <a href="/account" class="inline-link" style="font-size: 13px;">← Back to my account</a>
    <span class="eyebrow" style="margin-top: 20px;">Your groups</span>
    <h1 style="font-size: 32px; margin: 10px 0 10px;">Your signals and links</h1>
    <p style="color: var(--ink-dim); margin-bottom: 34px;">
      Every group you have access to, in one place. Lost a link, or left a group by accident?
      Open it again from here any time.
    </p>

    <h2 style="font-size: 20px; margin: 0 0 16px;">Open to you now</h2>
    <div class="grid5" style="grid-template-columns:1fr;">{unlocked_html}</div>
    {locked_html}

    <p style="color: var(--ink-dim); font-size: 13px; margin-top: 34px;">
      Request to join each group and we'll approve you shortly. Turn notifications on so you
      don't miss anything.
      <br>Something not working? <a href="/messages" class="inline-link">Message us here</a>, or say
      <strong>lost links</strong> to
      <a href="https://t.me/Innercircleverifybot" target="_blank" rel="noopener" class="inline-link">our bot</a>
      and it'll send them all again.
    </p>
  </div>
</section>
"""
    return render_template_string(base_layout("Your Signals", content, "signals"))


@app.route("/results")
def results():
    """
    Real signals, real member results, real quotes. The disclaimer is built into
    this page rather than tucked in the footer, because a page showing winning
    trades is exactly where someone needs to read it.
    """
    signals = "".join(
        f'<div class="sig-example">'
        f'<span class="sig-group">{esc(x["group"])}</span>'
        f'<p class="sig-call">{esc(x["call"])}</p>'
        f'<ul class="sig-out">'
        + "".join(f'<li>{esc(o)}</li>' for o in x["outcome"]) +
        f'</ul></div>'
        for x in SIGNAL_EXAMPLES
    )

    # Accepted screenshots stream from Telegram, so nothing needs uploading
    shared = [{"image": f'/shared/{p["id"]}/image/0',
               "caption": (p.get("body") or "Shared by a member").strip()[:120],
               "alt": "Member submitted result"}
              for p in published("result") if (p.get("file_ids") or "").strip()]
    uploaded = [{"image": f'/results/image/{i["id"]}',
                 "caption": i["caption"],
                 "alt": i["caption"] or "Member result screenshot"}
                for i in get_result_images(limit=60)]
    # Everything goes to the page and the spinner cycles through it, three at
    # a time, so nothing you upload is ever hidden.
    gallery_items = uploaded + shared + RESULTS_ITEMS

    if gallery_items:
        # Three on screen, turning through the whole set. Everything uploaded
        # gets its turn rather than only the first three ever showing.
        shots_data = json.dumps([
            {"src": r["image"],
             "alt": (r.get("alt") or r.get("caption") or "Member result"),
             "cap": (r.get("caption") or "")}
            for r in gallery_items])
        gallery = "".join(
            f'<figure class="shot"><div class="shot-frame">'
            f'<img src="{esc(r["image"])}" '
            f'alt="{esc(r.get("alt") or r.get("caption") or "Member result")}" '
            f'loading="lazy" onerror="this.closest(\'figure\').style.display=\'none\'">'
            f'</div><figcaption>{esc(r.get("caption") or "")}</figcaption></figure>'
            for r in gallery_items[:3]
        )
        gallery_section = f"""
<section class="tinted tinted-edge" id="shots">
  <div class="wrap" style="max-width: 900px;">
    <div class="section-head" style="max-width:100%;">
      <span class="eyebrow">Member screenshots</span>
      <h2>Straight from their accounts</h2>
    </div>
    <div class="shots" id="shot-grid">{gallery}</div>
    <div class="shot-dots" id="shot-dots"></div>
    <script>
      (function () {{
        var shots = {shots_data};
        if (shots.length <= 3) return;
        var grid = document.getElementById('shot-grid');
        var dots = document.getElementById('shot-dots');
        var pages = Math.ceil(shots.length / 3), page = 0;
        for (var i = 0; i < pages; i++) {{
          var d = document.createElement('span');
          if (i === 0) d.className = 'on';
          dots.appendChild(d);
        }}
        function show(n) {{
          var figs = grid.querySelectorAll('figure.shot');
          for (var i = 0; i < 3; i++) {{
            var item = shots[(n * 3 + i) % shots.length];
            var f = figs[i];
            if (!f || !item) continue;
            var img = f.querySelector('img');
            img.src = item.src;
            img.alt = item.alt;
            f.querySelector('figcaption').textContent = item.cap;
            f.style.display = '';
          }}
          var ds = dots.querySelectorAll('span');
          for (var j = 0; j < ds.length; j++) ds[j].className = (j === n ? 'on' : '');
        }}
        setInterval(function () {{
          grid.classList.add('turning');
          setTimeout(function () {{
            page = (page + 1) % pages;
            show(page);
            grid.classList.remove('turning');
          }}, 500);
        }}, 5000);
      }})();
    </script>
    <p class="risk-note">Members trade their own accounts, at their own position sizes, using
       risk management based on what is in their account. We show wins and losses both, because a
       page of nothing but wins would tell you nothing useful. Your results will not be the same,
       and some members lose money.</p>
    <p class="risk-note">These are a sample and they are not updated often. Inside the community
       we post results as they happen, wins and losses, so members see the real picture day to
       day rather than a handful of screenshots on a website.</p>
  </div>
</section>"""
    elif session.get("admin"):
        # Members see nothing rather than an empty band, but you should know
        # why the section is missing and how to fill it.
        gallery_section = """
<section class="tinted tinted-edge">
  <div class="wrap" style="max-width: 900px;">
    <div style="border:1px dashed var(--line); border-radius:14px; padding:20px 22px;">
      <strong>Member screenshots, admin only note</strong>
      <p style="color:var(--ink-dim); font-size:14px; line-height:1.8; margin:6px 0 0;">
        Nothing is showing here yet. Two ways to fill it:
        <a href="/admin/results" class="inline-link">upload screenshots yourself</a> straight from
        your phone, or accept ones members send the bot under
        <a href="/admin/submissions" class="inline-link">Feedback</a>. Either appears here
        straight away. Members do not see this note.</p>
    </div>
  </div>
</section>"""
    else:
        # Nothing to show yet, so show nothing rather than an empty band.
        gallery_section = ""

    # Approved submissions sit alongside the quotes we already had, newest first
    # Accepted feedback carries the section it was sent about, so it lands in
    # the right band rather than all going into one pile.
    SECTION_LABEL = {"signals_currency": "Extra signals member",
                     "signals_gold": "Signals member",
                     "fundamentals": "Foundation student",
                     "advanced": "Advanced student",
                     "her": "Wealth Circle member"}
    live = [{"quote": p["body"],
             "who": (p.get("member_name") or "Member").strip().split(" ")[0] or "Member",
             "band": SECTION_LABEL.get((p.get("section") or "").strip(), "")}
            for p in published("feedback") if (p.get("body") or "").strip()]
    # Feedback split by where it came from, so someone can find the bit that
    # applies to them. Even numbers only in each group, so the grid never ends
    # on a lonely half row.
    def _group(items):
        items = list(items)
        return items[:len(items) - (len(items) % 2)]

    def _quote_block(items):
        return "".join(
            f'<blockquote class="say"><p>{esc(f_["quote"])}</p>'
            f'<cite>{esc(f_.get("who") or "Member")}</cite></blockquote>'
            for f_ in items)

    all_feedback = live + MEMBER_FEEDBACK
    def _is(f_, *words):
        """Which band does this belong in? The section it was sent about wins,
        and the older hand written quotes fall back to who said it."""
        w = ((f_.get("band") or "") + " " + (f_.get("who") or "")).lower()
        return any(x in w for x in words)

    raw_extra = [f for f in all_feedback if _is(f, "extra")]
    raw_her = ([f for f in all_feedback if _is(f, "wealth circle")]
               or list(COMMUNITY_FEEDBACK))
    raw_signal = [f for f in all_feedback
                  if f not in raw_extra and f not in raw_her and not _is(
                      f, "student", "course", "fundamentals", "advanced")]

    # The real course reviews, kept apart so Foundation and Advanced each get
    # their own even pair rather than being lumped together.
    raw_found = [f for f in all_feedback if _is(f, "fundamentals", "foundation")] \
        + list(FUNDAMENTALS_REVIEWS)
    raw_adv = [f for f in all_feedback if _is(f, "advanced")] + list(ADVANCED_REVIEWS)

    # Counts you asked for: four from the signals groups, two from each of the
    # rest. A band only shows if it has a real even pair behind it, and any
    # single quote with nowhere to go sits with the signals group instead.
    for pool in (raw_extra,):
        if len(pool) < 2:
            raw_signal += pool
            pool.clear()

    # Four in each band where four real ones exist, otherwise two, always an
    # even number so no band ends on a lonely half row.
    def _even_up_to_four(items):
        items = _group(items)
        return items[:4] if len(items) >= 4 else items[:2]

    signal_q = _even_up_to_four(raw_signal)
    extra_q = _even_up_to_four(raw_extra)
    found_q = _even_up_to_four(raw_found)
    adv_q = _even_up_to_four(raw_adv)
    her_q = _even_up_to_four(raw_her)

    def _band(anchor, eyebrow, title, note, items, tint=""):
        if not items:
            return ""
        return f"""
<section class="{tint}" id="{anchor}">
  <div class="wrap" style="max-width: 900px;">
    <div class="section-head" style="max-width:100%;">
      <span class="eyebrow">{esc(eyebrow)}</span>
      <h2>{esc(title)}</h2>
      <p>{esc(note)}</p>
    </div>
    <div class="says">{_quote_block(items)}</div>
  </div>
</section>"""

    waiting = []
    if len(raw_extra) < 2 and len([f for f in all_feedback if _is(f, "extra")]) == 1:
        waiting.append("extra signals: one real quote on file, needs a second before its band "
                       "appears")
    admin_note = ""
    if waiting and session.get("admin"):
        admin_note = ('<section><div class="wrap" style="max-width:900px;">'
                      '<div style="border:1px dashed var(--line); border-radius:14px; '
                      'padding:16px 18px;"><strong>Feedback, admin only note</strong>'
                      '<p style="color:var(--ink-dim); font-size:14px; line-height:1.8; '
                      'margin:6px 0 0;">Bands show in even pairs, so nothing looks half finished. '
                      + esc("; ".join(waiting)) +
                      '. Accept another under <a href="/admin/submissions" class="inline-link">'
                      'Feedback</a> and it appears on its own. Members do not see this.</p>'
                      '</div></div></section>')

    quotes = (admin_note
              + _band("say", "In their words", "From the signals groups",
                    "Members following the daily gold signals.", signal_q)
              + _band("extra", "The extra groups", "From extra signals members",
                      "Members who added the extra groups for more trades a day.", extra_q,
                      tint="tinted")
              + _band("courses", "The Foundation course", "From beginners learning the basics",
                      "Members working through the free Foundation course.", found_q)
              + _band("advanced", "The Advanced course", "From people reading charts",
                      "Members who took the Advanced chart reading course.", adv_q, tint="tinted")
              + _band("women", "Wealth Circle", "From the women in Female Wealth",
                      "Members of our women-only community.", her_q))

    content = f"""
<section class="hero page-hero" style="padding-bottom: 40px;">
  <div class="wrap" style="grid-template-columns: 1fr; max-width: 860px;">
    <div>
      <span class="eyebrow">Results</span>
      <h1>The wins and<br>the <em>losses.</em></h1>
      <p class="lede">Real signals from the groups and real messages from members.
         Posted as they happened, not curated after the fact.</p>
    </div>
  </div>
</section>

<section class="risk-band">
  <div class="wrap" style="max-width: 860px;">
    <p><strong>Read this first.</strong> {RESULTS_DISCLAIMER}</p>
  </div>
</section>

<section id="signals">
  <div class="wrap" style="max-width: 900px;">
    <div class="section-head" style="max-width:100%;">
      <span class="eyebrow">From the groups</span>
      <h2>Signals as they went out</h2>
      <p>The call first, then what the group posted as it played out. Every one of these
         is a message that actually went to members.</p>
    </div>
    <div class="sig-grid">{signals}</div>
    <p class="risk-note">These are individual trades on particular days. Other trades on other
       days went differently, including trades that lost. A signal is not a prediction.</p>
  </div>
</section>



{quotes}

{gallery_section}

<section>
  <div class="wrap" style="max-width: 900px;">
    <p class="risk-note">Real messages from real members, shared with permission. They describe
       one person's experience, not a typical result or anything you should expect.</p>
  </div>
</section>

<section class="band-dark">
  <div class="wrap" style="max-width: 760px; text-align: center;">
    <h2 style="font-size: 26px; margin-bottom: 14px;">Learn it before you lean on it</h2>
    <p style="margin-bottom: 24px;">The free course teaches you what the levels mean, so you're
       following a trade you understand rather than copying numbers.</p>
    <div class="cta-row" style="justify-content:center;">
      <a href="/education/fundamentals" class="btn btn-primary">Start the free course</a>
      <a href="/onboarding" class="btn btn-ghost">Get set up</a>
    </div>
  </div>
</section>

<section class="risk-band">
  <div class="wrap" style="max-width: 860px;">
    <p>{RESULTS_DISCLAIMER}</p>
  </div>
</section>
"""
    return render_template_string(base_layout("Results", content, ""))


