def _lib_tile(t, a, why, kind="book"):
    """One shelf tile. The title is a link, so a tap takes her straight to it."""
    author = f'<div class="bk-author">{esc(a)}</div>' if a else ""
    what = "podcast" if kind == "listen" else "book"
    q = quote(f"{t} {a} {what}".strip())
    return (f'<div class="bk">'
            f'<a class="bk-title" href="https://www.google.com/search?q={q}" target="_blank" '
            f'rel="noopener" style="text-decoration:none; color:inherit; display:block;">'
            f'{esc(t)} <span style="color:var(--rose); font-size:12px;">&#8599;</span></a>'
            f'{author}<p>{esc(why)}</p></div>')


