def partner_unread_count(marketer_id):
    """Replies from admin a partner has not opened yet."""
    if not marketer_id:
        return 0
    mk = next((k for k in get_marketers() if k["id"] == marketer_id), None)
    member_id = (mk or {}).get("member_id")
    if not member_id:
        return 0
    seen = _meta_get(f"seen:msgs:p{marketer_id}") or ""
    try:
        msgs = get_messages(member_id) or []
    except Exception:
        return 0
    n = 0
    for m in msgs:
        if (m.get("sender") or "") != "admin":
            continue
        when = m.get("created_at")
        if not seen or (when and str(when) > seen):
            n += 1
    return n


def member_unread_count(member_id):
    """Replies from admin a member has not opened yet."""
    if not member_id:
        return 0
    seen = _meta_get(f"seen:msgs:m{member_id}") or ""
    try:
        msgs = get_messages(member_id) or []
    except Exception:
        return 0
    return sum(1 for m in msgs
               if (m.get("sender") or "") == "admin"
               and (not seen or (m.get("created_at") and str(m["created_at"]) > seen)))


def hub_who_key():
    """Who is looking: a member, a partner, or admin. One key each."""
    if session.get("marketer_id"):
        return f"p{session['marketer_id']}"
    if session.get("member_id"):
        return f"m{session['member_id']}"
    if session.get("admin"):
        return "admin"
    return ""


def hub_unread(space, who_key):
    """
    How much has happened on a board since this person last opened it. Counts
    posts and replies, so a busy thread shows up as well as a new question.
    """
    if not who_key:
        return 0
    seen = _meta_get(f"seen:{space}:{who_key}") or ""
    conn = get_db()
    if not conn:
        return 0
    try:
        with conn.cursor() as cur:
            if seen:
                cur.execute("""SELECT COUNT(*) FROM hub_posts
                               WHERE COALESCE(space,'her')=%s AND hidden=FALSE
                                 AND COALESCE(last_activity, created_at) > %s""",
                            (space, seen))
            else:
                cur.execute("""SELECT COUNT(*) FROM hub_posts
                               WHERE COALESCE(space,'her')=%s AND hidden=FALSE""", (space,))
            row = cur.fetchone()
            return int(row[0]) if row else 0
    except Exception:
        return 0
    finally:
        conn.close()


def hub_mark_seen(space, who_key):
    if who_key:
        try:
            _meta_set(f"seen:{space}:{who_key}", datetime.utcnow().isoformat())
        except Exception:
            pass


def unread_pill(n):
    """A small count on a tab. Nothing at all when there is nothing new."""
    if not n:
        return ""
    return (f'<span style="display:inline-block; min-width:17px; padding:1px 5px; margin-left:6px; '
            f'border-radius:9px; background:var(--gold, #C4A272); color:#12100E; font-size:10.5px; '
            f'font-weight:700; line-height:15px; text-align:center; vertical-align:top;">'
            f'{n if n < 100 else "99+"}</span>')


