@app.route("/her/course/<slug>")
def her_course(slug):
    if not has_access("her") and not session.get("admin"):
        return redirect(url_for("community"))

    course = next((c for c in HER_COURSES if c[0] == slug), None)
    if not course:
        return redirect("/her/courses")
    _, title, blurb, section_names = course

    title_to_idx = {t: i for i, (t, _) in enumerate(HER_MASTERCLASSES)}
    done = get_done_lessons(session.get("member_id"))
    locked = her_lock_map()
    blocks = []
    for cat_name, cat_desc, titles in HER_CATEGORIES:
        if cat_name not in section_names:
            continue
        real = [t for t in titles if t in title_to_idx]
        open_here = [t for t in real if t not in locked]
        done_here = sum(1 for t in open_here if t in done)
        count_html = (f'<span style="color:var(--rose); font-size:13px; font-weight:600;"> · '
                      f'{done_here} of {len(open_here)} done</span>') if done_here else ""
        def row(t):
            if t in locked and not session.get("admin"):
                return (f'<div class="her-card small locked">'
                        f'<span class="her-title">&#128274;&nbsp;{esc(t)}</span>'
                        f'<span class="unlock-tag">Unlocks {esc(nice_date(locked[t]))}</span></div>')
            tick = '<span style="color:var(--rose); font-weight:700;">&#10003;&nbsp;</span>' if t in done else ''
            adm = (f'<span class="unlock-tag">Releases {esc(nice_date(locked[t]))}</span>'
                   if t in locked else '')
            return (f'<a href="/her/masterclass/{title_to_idx[t]}" class="her-card small">'
                    f'<span class="her-title">{tick}{esc(t)}</span>{adm}'
                    f'<span class="her-arrow">→</span></a>')
        items = "".join(row(t) for t in real)
        blocks.append(
            f'<div style="margin-bottom:40px;">'
            f'<h2 style="font-family:\'Fraunces\',serif; font-size:23px; margin:0 0 6px;">{esc(cat_name)}{count_html}</h2>'
            f'<p style="color:var(--ink-dim); font-size:14px; margin:0 0 16px;">{esc(cat_desc)}</p>'
            f'{items}</div>')

    body = "".join(blocks) or (
        '<div class="callout">This one is being written now. It will appear here as soon as '
        'it is ready, and you will not need to do anything to get it.</div>')

    content = f"""
<section style="padding:52px 0 70px;">
  <div class="wrap" style="max-width:720px;">
    <a href="/her/courses" class="inline-link" style="font-size:13px;">← All courses</a>
    <div class="section-head" style="max-width:100%; margin:22px 0 32px;">
      <span class="eyebrow">Female Wealth</span>
      <h1 style="font-size:32px; margin:10px 0 12px;">{esc(title)}</h1>
      <p>{esc(blurb)}</p>
    </div>
    {body}
  </div>
</section>
"""
    return render_template_string(base_layout(title, content, "community", theme="plum"))


